def _proof_dimension_exhausted(
    proof: Mapping[str, Any],
    dimension_id: str,
) -> bool:
    source_model_proof = _proof_source_model_proof(proof)
    synthesis = _proof_source_family_synthesis(proof)
    containers = (proof, source_model_proof, synthesis)
    for container in containers:
        if dimension_id in _string_items(container.get("exhausted_source_dimension")):
            return True
        if dimension_id in _string_items(container.get("exhausted_dimensions")):
            return True
        for row in _list_of_dicts(container.get("exhausted_dimensions")):
            if row.get("dimension_id") == dimension_id:
                return True
    if dimension_id in _nested_strings_for_key(proof, "exhausted_source_dimension"):
        return True
    return False


