def _draw_post_stack_clean_no_anchor_source_shape_requested(
    context: MetaCeilingContext,
) -> bool:
    if context.function != DRAW_FUNCTION or context.register_class != "fpr":
        return False
    proof = context.current_ceiling
    next_families = set(_nested_strings_for_key(proof, "next_unsupported_source_family"))
    next_models = set(_nested_strings_for_key(proof, "next_unsupported_source_model"))
    next_dimensions = set(
        _nested_strings_for_key(proof, "next_unsupported_source_dimension")
    )
    terminal_reasons = set(_nested_strings_for_key(proof, "terminal_reason"))
    terminal_blockers = set(_nested_strings_for_key(proof, "terminal_blocker"))
    if context.next_unsupported_source_family:
        next_families.add(context.next_unsupported_source_family)
    if context.next_unsupported_source_model:
        next_models.add(context.next_unsupported_source_model)
    if context.next_unsupported_source_dimension:
        next_dimensions.add(context.next_unsupported_source_dimension)
    exhausted_dimensions = {
        str(row.get("dimension_id"))
        for row in _list_of_dicts_for_nested_key(proof, "exhausted_dimensions")
        if row.get("dimension_id") is not None
    }
    post_product_recovery_terminal = (
        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_FINAL_FAMILY in next_families
        or DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_FINAL_MODEL in next_models
        or DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_TERMINAL_REASON in terminal_reasons
        or DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_TERMINAL_BLOCKER in terminal_blockers
        or DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION in exhausted_dimensions
    )
    post_stack_source_shape_requested = (
        DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_FINAL_FAMILY in next_families
        or DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_FINAL_MODEL in next_models
        or DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_DIMENSION in next_dimensions
    )
    return post_product_recovery_terminal or post_stack_source_shape_requested


