def _semantic_sort_zero_candidate_generation_blockers(
    dimensions: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    if (
        context.function != SORT_FUNCTION
        or not _should_generate_sort_semantic_algorithm_shapes(context)
    ):
        return []
    blockers: list[dict[str, Any]] = []
    for row in dimensions:
        dimension_id = str(row.get("dimension_id"))
        if dimension_id not in SORT_SEMANTIC_ALGORITHM_DIMENSIONS:
            continue
        if int(row.get("candidate_count") or 0) != 0:
            continue
        blockers.append(
            {
                "dimension_id": dimension_id,
                "reason": SORT_SEMANTIC_SOURCE_REGION_PATTERN_BLOCKER,
                "required_patterns": list(SORT_SEMANTIC_REQUIRED_SOURCE_PATTERNS),
            }
        )
    return blockers


