def _draw_stack_clean_no_anchor_recovery_zero_candidate_generation_blockers(
    dimensions: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    if not _draw_stack_clean_no_anchor_recovery_stage_active(context):
        return []
    for row in dimensions:
        if row.get("dimension_id") != DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION:
            continue
        if int(row.get("candidate_count") or 0) != 0:
            return []
        evidence = _draw_stack_clean_no_anchor_recovery_evidence(context)
        probes = (
            _list_of_dicts(evidence.get("ranked_recovery_probes"))
            if isinstance(evidence, Mapping)
            else []
        )
        if not probes:
            probes = _draw_stack_clean_no_anchor_recovery_probes(evidence or {})
        blockers: list[dict[str, Any]] = []
        for index, probe in enumerate(probes, start=1):
            probe_id = _non_empty_str(probe.get("probe_id")) or f"rank-{index}"
            blockers.append(
                {
                    "dimension_id": DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION,
                    "probe_id": probe_id,
                    "rank": _int_or_none(probe.get("rank")) or index,
                    "reason": (
                        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_SOURCE_REGION_PATTERN_BLOCKER
                    ),
                    "terminal_blocker": (
                        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_TERMINAL_BLOCKER
                    ),
                    "seed_candidate_id": (
                        evidence.get("seed_candidate_id")
                        if isinstance(evidence, Mapping)
                        else probe.get("seed_candidate_id")
                    ),
                    "source_retained": (
                        evidence.get("source_retained")
                        if isinstance(evidence, Mapping)
                        else probe.get("source_retained")
                    ),
                    "pcdump_path": (
                        evidence.get("pcdump_path")
                        if isinstance(evidence, Mapping)
                        else probe.get("pcdump_path")
                    ),
                    "source_hunks": list(evidence.get("source_hunks") or [])
                    if isinstance(evidence, Mapping)
                    else [],
                    "target_score": evidence.get("target_score")
                    if isinstance(evidence, Mapping)
                    else None,
                    "expression_score": evidence.get("expression_score")
                    if isinstance(evidence, Mapping)
                    else None,
                    "missing_source_span": probe_id,
                    "required_source_span": _draw_stack_clean_required_source_span(
                        probe_id
                    ),
                }
            )
        return blockers
    return []


def _draw_stack_clean_required_source_span(probe_id: str) -> str:
    return {
        "row-delta-anchor-local": "row_offset = y_offset_owner * (f32) row;",
        "digit-fsubs-anchor-temp": (
            "base = (f32) digit; HSD_JObjReqAnimAll(jobj, base);"
        ),
        "col-product-anchor-owner-transfer": (
            "col_product_owner = (f32) col; col_product_owner *= y_spacing;"
        ),
        "frame-clean-owner-prune": (
            "y_offset_owner = y_offset; row_offset = y_offset_owner * (f32) row;"
        ),
    }.get(probe_id, "ranked recovery source span")


