def _draw_post_alternate_source_context_zero_candidate_generation_blockers(
    dimensions: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    if not _draw_post_alternate_source_context_stage_active(context):
        return []
    missing = list(DRAW_POST_ALTERNATE_SOURCE_CONTEXT_REQUIRED_SOURCE_PATTERNS)
    source_text = context.current_ceiling.get("_source_text_for_generation")
    if isinstance(source_text, str):
        _, span = _find_source_function(source_text, context)
        if span is not None:
            _, missing = _draw_post_alternate_function_region_ready(
                source_text[span.sig_start : span.full_end]
            )
    for row in dimensions:
        if row.get("dimension_id") != DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION:
            continue
        if int(row.get("candidate_count") or 0) != 0:
            return []
        evidence = _draw_post_alternate_retained_terminal_evidence(context)
        return [
            {
                "dimension_id": DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION,
                "reason": DRAW_POST_ALTERNATE_SOURCE_CONTEXT_PATTERN_BLOCKER,
                "required_source_patterns": missing,
                "retained_scored_probes": list(
                    evidence.get("retained_scored_probes") or []
                ),
                "source_hunks_by_candidate": list(
                    evidence.get("source_hunks_by_candidate") or []
                ),
            }
        ]
    return []


