    if _draw_stack_clean_no_anchor_recovery_stage_active(context):
        return []
    if not _draw_product_translate_expression_graph_exhausted(context):
        return []
    evidence = _draw_product_translate_expression_graph_retained_terminal_evidence(
        context
    )
    blocker = {
        "dimension_id": DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_DIMENSION,
        "reason": DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_NO_FLOOR_BLOCKER,
        "terminal_blocker": (DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_NO_FLOOR_BLOCKER),
        "retained_scored_probes": list(evidence.get("retained_scored_probes") or []),
        "source_hunks_by_candidate": list(
            evidence.get("source_hunks_by_candidate") or []
        ),
    }
    stack_clean = evidence.get("stack_clean_no_anchor_evidence")
    if isinstance(stack_clean, Mapping):
        blocker["next_unsupported_source_dimension"] = (
            DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION
        )
        blocker["stack_clean_no_anchor_evidence"] = dict(stack_clean)
    return [blocker]


