def _draw_post_alternate_no_modeled_source_family_zero_candidate_generation_blockers(
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    if _draw_stack_clean_no_anchor_recovery_stage_active(context):
        return []
