def _should_terminalize_zero_candidate_generation(
    context: MetaCeilingContext,
    generation_blockers: Sequence[Mapping[str, Any]],
) -> bool:
    if not generation_blockers:
        return False
    if context.function == DRAW_FUNCTION:
        return any(
            row.get("reason")
            in {
                DRAW_ALTERNATE_FPR_RETAINED_ROW_OFFSET_SPLIT_BLOCKER,
                DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_EXHAUSTED_NEXT_FAMILY,
                DRAW_POST_SOURCE_CONTEXT_PATTERN_BLOCKER,
                DRAW_POST_SOURCE_CONTEXT_NO_FLOOR_BLOCKER,
                DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_PATTERN_BLOCKER,
                DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_NO_FLOOR_BLOCKER,
                DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_PATTERN_BLOCKER,
                DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_NO_FLOOR_BLOCKER,
                DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_SOURCE_REGION_PATTERN_BLOCKER,
                DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_PATTERN_BLOCKER,
                DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_TERMINAL_BLOCKER,
                DRAW_POST_STACK_LOOP_CALLSITE_SOURCE_CONTEXT_PATTERN_BLOCKER,
                DRAW_POST_STACK_LOOP_CALLSITE_SOURCE_CONTEXT_TERMINAL_BLOCKER,
                DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_PATTERN_BLOCKER,
                DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_TERMINAL_BLOCKER,
                DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_PATTERN_BLOCKER,
                DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_TERMINAL_BLOCKER,
            }
            or row.get("terminal_blocker")
            == DRAW_POST_ALTERNATE_NO_MODELED_SOURCE_TERMINAL_BLOCKER
            for row in generation_blockers
            if isinstance(row, Mapping)
        )
    if context.function != SORT_FUNCTION:
        return False
    return any(
        row.get("reason")
        in {
            SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_SOURCE_REGION_PATTERN_BLOCKER,
            SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_SOURCE_REGION_PATTERN_BLOCKER,
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_FAMILY,
            SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_SOURCE_REGION_PATTERN_BLOCKER,
            SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_SOURCE_REGION_PATTERN_BLOCKER,
            SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_SOURCE_REGION_PATTERN_BLOCKER,
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_SOURCE_REGION_PATTERN_BLOCKER,
        }
        for row in generation_blockers
        if isinstance(row, Mapping)
    )


