def _dimensions_with_generation_blockers(
    dimensions: Sequence[Mapping[str, Any]],
    generation_blockers: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    blockers_by_dimension: dict[str, list[dict[str, Any]]] = {}
    for blocker in generation_blockers:
        dimension_id = _non_empty_str(blocker.get("dimension_id"))
        if dimension_id is None:
            continue
        blockers_by_dimension.setdefault(dimension_id, []).append(dict(blocker))

    annotated: list[dict[str, Any]] = []
    for row in dimensions:
        out = dict(row)
        dimension_id = str(out.get("dimension_id"))
        blockers = blockers_by_dimension.get(dimension_id, [])
        if blockers:
            out["status"] = "blocked"
            out["blockers"] = [
                *_normalized_blocker_entries(out.get("blockers")),
                *blockers,
            ]
        annotated.append(out)
    present = {str(row.get("dimension_id")) for row in annotated}
    for dimension_id, blockers in blockers_by_dimension.items():
        if dimension_id in present:
            continue
        annotated.append(
            {
                "dimension_id": dimension_id,
                "generated_candidate_ids": [],
                "scored_candidate_ids": [],
                "candidate_count": 0,
                "scored_count": 0,
                "status": "blocked",
                "blockers": blockers,
            }
        )
    return annotated


def classify_source_family_scores(
    candidates: Sequence[Mapping[str, Any]],
    score_payloads: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
    *,
    continue_after_final_source_family: bool = False,
) -> dict[str, Any]:
    joined = _join_score_rows(candidates, score_payloads, context)
    score_rows = joined["score_rows"]
    for row in score_rows:
        _apply_required_assignment_blockers(row)
    generated_dimensions = _dimension_status_rows(
        candidates,
        (),
        function=context.function,
    )
    generation_blockers = _zero_candidate_generation_blockers(
        generated_dimensions,
        context,
        continue_after_final_source_family=continue_after_final_source_family,
    )
    if generation_blockers:
        generated_dimensions = _dimensions_with_generation_blockers(
            generated_dimensions,
            generation_blockers,
        )
    draw_alternate_stage = _draw_alternate_stage_active(context)
    draw_post_alternate_source_context_stage = (
        _draw_post_alternate_source_context_stage_active(context)
    )
    draw_post_source_context_whole_function_stage = (
        _draw_post_source_context_whole_function_stage_active(context)
    )
    draw_post_all_known_source_context_stage = (
        _draw_post_all_known_source_context_stage_active(context)
    )
    draw_product_translate_expression_graph_stage = (
        _draw_product_translate_expression_graph_stage_active(context)
    )
    draw_stack_clean_no_anchor_recovery_stage = (
        _draw_stack_clean_no_anchor_recovery_stage_active(context)
    )
    draw_post_stack_clean_no_anchor_source_shape_stage = (
        _draw_post_stack_clean_no_anchor_source_shape_stage_active(context)
    )
    draw_post_stack_loop_callsite_source_context_stage = (
        _draw_post_stack_loop_callsite_source_context_stage_active(context)
    )
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage = (
        _draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage_active(
            context
        )
    )
    draw_post_row_offset_owner_expression_lifetime_stage = (
        _draw_post_row_offset_owner_expression_lifetime_stage_active(context)
    )
    draw_post_all_known_structural_floor_rejected = (
        _draw_post_all_known_prior_structural_guard_rejected(context)
    )
    draw_post_ceiling_floor = _draw_post_ceiling_floor(context, score_rows)
    actionable = [
        row
        for row in score_rows
        if _row_source_actionable_progress(
            row,
            draw_alternate_stage=draw_alternate_stage,
            draw_post_alternate_source_context_stage=(
                draw_post_alternate_source_context_stage
            ),
            draw_post_source_context_whole_function_stage=(
                draw_post_source_context_whole_function_stage
            ),
            draw_post_all_known_source_context_stage=(
                draw_post_all_known_source_context_stage
            ),
            draw_product_translate_expression_graph_stage=(
                draw_product_translate_expression_graph_stage
            ),
            draw_stack_clean_no_anchor_recovery_stage=(
                draw_stack_clean_no_anchor_recovery_stage
            ),
            draw_post_stack_clean_no_anchor_source_shape_stage=(
                draw_post_stack_clean_no_anchor_source_shape_stage
            ),
            draw_post_stack_loop_callsite_source_context_stage=(
                draw_post_stack_loop_callsite_source_context_stage
            ),
            draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage=(
                draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
            ),
            draw_post_row_offset_owner_expression_lifetime_stage=(
                draw_post_row_offset_owner_expression_lifetime_stage
            ),
            draw_post_all_known_structural_floor_rejected=(
                draw_post_all_known_structural_floor_rejected
            ),
            draw_post_ceiling_floor=draw_post_ceiling_floor,
        )
        and row["structural_guard_accepted"]
        and _row_satisfies_required_assignments(row)
        and row["score_error"] is None
    ]
    risky_progress = [
        row
        for row in score_rows
        if _row_source_actionable_progress(
            row,
            draw_alternate_stage=draw_alternate_stage,
            draw_post_alternate_source_context_stage=(
                draw_post_alternate_source_context_stage
            ),
            draw_post_source_context_whole_function_stage=(
                draw_post_source_context_whole_function_stage
            ),
            draw_post_all_known_source_context_stage=(
                draw_post_all_known_source_context_stage
            ),
            draw_product_translate_expression_graph_stage=(
                draw_product_translate_expression_graph_stage
            ),
            draw_stack_clean_no_anchor_recovery_stage=(
                draw_stack_clean_no_anchor_recovery_stage
            ),
            draw_post_stack_clean_no_anchor_source_shape_stage=(
                draw_post_stack_clean_no_anchor_source_shape_stage
            ),
            draw_post_stack_loop_callsite_source_context_stage=(
                draw_post_stack_loop_callsite_source_context_stage
            ),
            draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage=(
                draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
            ),
            draw_post_row_offset_owner_expression_lifetime_stage=(
                draw_post_row_offset_owner_expression_lifetime_stage
            ),
            draw_post_all_known_structural_floor_rejected=(
                draw_post_all_known_structural_floor_rejected
            ),
            draw_post_ceiling_floor=draw_post_ceiling_floor,
        )
        and not row["structural_guard_accepted"]
    ]

    base_payload: dict[str, Any] = {
        "function": context.function,
        "source_function": context.source_function,
        "candidate_count": len(candidates),
        "score_count": len(score_payloads),
        "joined_score_count": len(score_rows),
        "score_rows": score_rows,
        "duplicate_score_rows": joined["duplicate_score_rows"],
        "unjoined_score_rows": joined["unjoined_score_rows"],
        "metadata_mismatches": joined["metadata_mismatches"],
        "missing_score_candidate_ids": joined["missing_score_candidate_ids"],
    }
    semantic_recombine = _sort_semantic_recombine_summary(score_rows, context)
    if semantic_recombine is not None:
        base_payload["semantic_recombine"] = semantic_recombine
    partial_score = _live_score_partial_summary(score_rows)
    if partial_score is not None:
        base_payload["partial_score"] = partial_score
        base_payload["partial"] = True
        base_payload["interrupted"] = True
        base_payload["terminal_blocker"] = partial_score["terminal_blocker"]
        base_payload["last_candidate"] = {
            "candidate_id": partial_score["last_candidate_id"],
            "source_retained": partial_score.get("last_candidate_path"),
        }
        base_payload["interruption"] = dict(partial_score)
    if generation_blockers:
        base_payload["generation_blockers"] = generation_blockers
        base_payload["generated_family_dimensions"] = generated_dimensions

    if actionable:
        ranked = _rank_score_rows(actionable)
        return {
            **base_payload,
            "status": "actionable",
            "ranked_candidates": ranked,
            "best_candidate": ranked[0],
            "risky_candidates": _rank_score_rows(risky_progress),
        }

    blockers: list[dict[str, Any]] = []
    if joined["unjoined_score_rows"]:
        blockers.append({"reason": "unjoined-score-rows"})
    if joined["metadata_mismatches"]:
        blockers.append({"reason": "score-metadata-mismatch"})
    if partial_score is not None:
        blockers.append(
            {
                "reason": partial_score["reason"],
                "terminal_blocker": partial_score["terminal_blocker"],
                "candidate_ids": [partial_score["last_candidate_id"]],
                "score_error": partial_score.get("score_error"),
            }
        )
    error_rows = [row for row in score_rows if row["score_error"] is not None]
    if error_rows:
        invalid_rows = [
            row for row in error_rows if _score_row_invalid_generated_source(row)
        ]
        if invalid_rows:
            blockers.append(
                {
                    "reason": "invalid-generated-source",
                    "candidate_ids": [
                        row["candidate_id"]
                        for row in invalid_rows
                        if row.get("candidate_id") is not None
                    ],
                    "source_validation": [
                        dict(row["source_validation"])
                        for row in invalid_rows
                        if isinstance(row.get("source_validation"), Mapping)
                    ],
                }
            )
        blockers.append(
            {
                "reason": "score-row-error",
                "candidate_ids": [row["candidate_id"] for row in error_rows],
            }
        )
    source_context_full_unit_blocker = _source_context_missing_full_unit_source_blocker(
        score_rows
    )
    if source_context_full_unit_blocker is not None:
        blockers.append(source_context_full_unit_blocker)
    rejected_rows = [
        row
        for row in score_rows
        if row["score_error"] is None and not row["structural_guard_accepted"]
    ]
    if rejected_rows:
        blockers.append(
            {
                "reason": "structural-guard-not-accepted",
                "candidate_ids": [row["candidate_id"] for row in rejected_rows],
            }
        )
    required_rejected_rows = [
        row
        for row in score_rows
        if row["score_error"] is None
        and _row_requires_required_assignments(row)
        and not _row_satisfies_required_assignments(row)
    ]
    if required_rejected_rows:
        blockers.append(
            {
                "reason": "protected-targets-not-jointly-preserved",
                "candidate_ids": [
                    str(row.get("candidate_id"))
                    for row in required_rejected_rows
                    if row.get("candidate_id")
                ],
            }
        )
    if partial_score is not None:
        return {
            **base_payload,
            "status": "incomplete",
            "reason": partial_score["reason"],
            "blockers": blockers,
            "risky_candidates": _rank_score_rows(risky_progress),
        }
    if joined["missing_score_candidate_ids"]:
        return {
            **base_payload,
            "status": "incomplete",
            "reason": "not-all-generated-candidates-scored",
            "blockers": blockers,
            "risky_candidates": _rank_score_rows(risky_progress),
        }
    if blockers:
        if _draw_alternate_floor_exhaustion_can_terminalize(
            score_rows,
            blockers,
            draw_alternate_stage=draw_alternate_stage,
            draw_post_alternate_source_context_stage=(
                draw_post_alternate_source_context_stage
            ),
            draw_post_source_context_whole_function_stage=(
                draw_post_source_context_whole_function_stage
            ),
            draw_post_all_known_source_context_stage=(
                draw_post_all_known_source_context_stage
            ),
            draw_product_translate_expression_graph_stage=(
                draw_product_translate_expression_graph_stage
            ),
            draw_stack_clean_no_anchor_recovery_stage=(
                draw_stack_clean_no_anchor_recovery_stage
            ),
            draw_post_stack_clean_no_anchor_source_shape_stage=(
                draw_post_stack_clean_no_anchor_source_shape_stage
            ),
            draw_post_stack_loop_callsite_source_context_stage=(
                draw_post_stack_loop_callsite_source_context_stage
            ),
            draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage=(
                draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
            ),
            draw_post_row_offset_owner_expression_lifetime_stage=(
                draw_post_row_offset_owner_expression_lifetime_stage
            ),
            draw_post_ceiling_floor=draw_post_ceiling_floor,
        ):
            terminal_blockers = [
                _draw_no_floor_terminal_blocker(
                    draw_post_ceiling_floor,
                    draw_post_alternate_source_context_stage=(
                        draw_post_alternate_source_context_stage
                    ),
                    draw_post_source_context_whole_function_stage=(
                        draw_post_source_context_whole_function_stage
                    ),
                    draw_post_all_known_source_context_stage=(
                        draw_post_all_known_source_context_stage
                    ),
                    draw_product_translate_expression_graph_stage=(
                        draw_product_translate_expression_graph_stage
                    ),
                    draw_stack_clean_no_anchor_recovery_stage=(
                        draw_stack_clean_no_anchor_recovery_stage
                    ),
                    draw_post_stack_clean_no_anchor_source_shape_stage=(
                        draw_post_stack_clean_no_anchor_source_shape_stage
                    ),
                    draw_post_stack_loop_callsite_source_context_stage=(
                        draw_post_stack_loop_callsite_source_context_stage
                    ),
                    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage=(
                        draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
                    ),
                    draw_post_row_offset_owner_expression_lifetime_stage=(
                        draw_post_row_offset_owner_expression_lifetime_stage
                    ),
                ),
                *blockers,
            ]
            terminal = build_terminal_source_family_proof(
                candidates,
                score_rows,
                context,
                terminal_blockers=terminal_blockers,
                generation_blockers=generation_blockers,
                generated_dimensions=generated_dimensions,
            )
            return {
                **base_payload,
                **terminal,
                "blockers": blockers,
                "risky_candidates": _rank_score_rows(risky_progress),
            }
        if _can_terminalize_structural_guard_exhaustion(
            context,
            score_rows,
            blockers,
        ) or _can_terminalize_required_assignment_exhaustion(
            context,
            score_rows,
            blockers,
        ):
            terminal = build_terminal_source_family_proof(
                candidates,
                score_rows,
                context,
                terminal_blockers=blockers,
                generation_blockers=generation_blockers,
                generated_dimensions=generated_dimensions,
            )
            return {
                **base_payload,
                **terminal,
                "blockers": blockers,
                "risky_candidates": _rank_score_rows(risky_progress),
            }
        if _can_terminalize_unscoreable_source_context_exhaustion(
            context,
            score_rows,
            blockers,
        ):
            terminal_blockers = _dedupe_dicts(
                [
                    *[dict(row) for row in blockers if isinstance(row, Mapping)],
                    _unscoreable_source_context_terminal_blocker(score_rows),
                ]
            )
            terminal = build_terminal_source_family_proof(
                candidates,
                score_rows,
                context,
                terminal_blockers=terminal_blockers,
                generation_blockers=generation_blockers,
                generated_dimensions=generated_dimensions,
            )
            return {
                **base_payload,
                **terminal,
                "blockers": blockers,
                "risky_candidates": _rank_score_rows(risky_progress),
            }
        return {
            **base_payload,
            "status": "blocked",
            "reason": (
                "invalid-generated-source"
                if any(_score_row_invalid_generated_source(row) for row in score_rows)
                else "score-rows-not-terminal-safe"
            ),
            "blockers": blockers,
            "risky_candidates": _rank_score_rows(risky_progress),
        }
    terminal_blockers: list[dict[str, Any]] = []
    if (
        draw_alternate_stage
        or draw_post_alternate_source_context_stage
        or draw_post_source_context_whole_function_stage
        or draw_post_all_known_source_context_stage
        or draw_product_translate_expression_graph_stage
        or draw_stack_clean_no_anchor_recovery_stage
        or draw_post_stack_clean_no_anchor_source_shape_stage
        or draw_post_stack_loop_callsite_source_context_stage
        or draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
        or draw_post_row_offset_owner_expression_lifetime_stage
    ) and score_rows:
        terminal_blockers.append(
            _draw_no_floor_terminal_blocker(
                draw_post_ceiling_floor,
                draw_post_alternate_source_context_stage=(
                    draw_post_alternate_source_context_stage
                ),
                draw_post_source_context_whole_function_stage=(
                    draw_post_source_context_whole_function_stage
                ),
                draw_post_all_known_source_context_stage=(
                    draw_post_all_known_source_context_stage
                ),
                draw_product_translate_expression_graph_stage=(
                    draw_product_translate_expression_graph_stage
                ),
                draw_stack_clean_no_anchor_recovery_stage=(
                    draw_stack_clean_no_anchor_recovery_stage
                ),
                draw_post_stack_clean_no_anchor_source_shape_stage=(
                    draw_post_stack_clean_no_anchor_source_shape_stage
                ),
                draw_post_stack_loop_callsite_source_context_stage=(
                    draw_post_stack_loop_callsite_source_context_stage
                ),
                draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage=(
                    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
                ),
                draw_post_row_offset_owner_expression_lifetime_stage=(
                    draw_post_row_offset_owner_expression_lifetime_stage
                ),
            )
        )
    terminal = build_terminal_source_family_proof(
        candidates,
        score_rows,
        context,
        terminal_blockers=terminal_blockers,
        generation_blockers=generation_blockers,
        generated_dimensions=generated_dimensions,
    )
    return {
        **base_payload,
        **terminal,
    }


_BOUNDED_FULL_UNIT_SOURCE_CONTEXT_DIMENSIONS = {
    SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION,
    SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION,
    SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION,
    SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_DIMENSION,
    SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_DIMENSION,
    SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_DIMENSION,
    SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_DIMENSION,
    SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION,
}


def _can_terminalize_unscoreable_source_context_exhaustion(
    context: MetaCeilingContext,
    score_rows: Sequence[Mapping[str, Any]],
    blockers: Sequence[Mapping[str, Any]],
) -> bool:
    if context.function != SORT_FUNCTION or not score_rows:
        return False
    blocker_reasons = {
        row.get("reason") for row in blockers if isinstance(row, Mapping)
    }
    if blocker_reasons - {"score-row-error"}:
        return False
    attempted_ids = {
        str(row.get("dimension_id"))
        for row in score_rows
        if row.get("dimension_id") is not None
    }
    if not attempted_ids or not (
        attempted_ids <= _BOUNDED_FULL_UNIT_SOURCE_CONTEXT_DIMENSIONS
    ):
        return False
    return all(_score_row_is_unscoreable_generated_source(row) for row in score_rows)


def _score_row_is_unscoreable_generated_source(row: Mapping[str, Any]) -> bool:
    if row.get("score_error") != "pcdump missing":
        return False
    if row.get("full_unit_source") is not True:
        return False
    if not row.get("source_hunks"):
        return False
    if _non_empty_str(row.get("source_retained")) is None:
        return False
    if row.get("dimension_id") not in _BOUNDED_FULL_UNIT_SOURCE_CONTEXT_DIMENSIONS:
        return False
    return True


def _unscoreable_source_context_terminal_blocker(
    score_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    return {
        "reason": "generated-source-unscoreable",
        "candidate_ids": [
            row.get("candidate_id")
            for row in score_rows
            if row.get("candidate_id") is not None
        ],
        "dimension_ids": _dedupe_strings(
            str(row.get("dimension_id"))
            for row in score_rows
            if row.get("dimension_id") is not None
        ),
        "score_errors": _dedupe_strings(
            str(row.get("score_error"))
            for row in score_rows
            if row.get("score_error") is not None
        ),
        "message": (
            "Generated bounded full-unit source candidates could not be "
            "compiled/scored, so this source-family candidate set is exhausted."
        ),
    }


def _row_source_actionable_progress(
    row: Mapping[str, Any],
    *,
    draw_alternate_stage: bool,
    draw_post_alternate_source_context_stage: bool,
    draw_post_source_context_whole_function_stage: bool,
    draw_post_all_known_source_context_stage: bool,
    draw_product_translate_expression_graph_stage: bool,
    draw_stack_clean_no_anchor_recovery_stage: bool,
    draw_post_stack_clean_no_anchor_source_shape_stage: bool,
    draw_post_stack_loop_callsite_source_context_stage: bool,
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage: bool,
    draw_post_row_offset_owner_expression_lifetime_stage: bool,
    draw_post_all_known_structural_floor_rejected: bool,
    draw_post_ceiling_floor: Mapping[str, int],
) -> bool:
    if (
        draw_alternate_stage
        or draw_post_alternate_source_context_stage
        or draw_post_source_context_whole_function_stage
        or draw_post_all_known_source_context_stage
        or draw_product_translate_expression_graph_stage
        or draw_stack_clean_no_anchor_recovery_stage
        or draw_post_stack_clean_no_anchor_source_shape_stage
        or draw_post_stack_loop_callsite_source_context_stage
        or draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
        or draw_post_row_offset_owner_expression_lifetime_stage
    ):
        if (
            (
                draw_post_stack_clean_no_anchor_source_shape_stage
                or draw_post_stack_loop_callsite_source_context_stage
                or draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
                or draw_post_row_offset_owner_expression_lifetime_stage
            )
            and (
                _draw_post_alternate_score_matched(row, "target") > 0
                or _real_expression_matched(row) > 0
                or _row_draw_post_stack_clean_frame_progress(row)
            )
        ):
            return True
        if _row_exceeds_draw_post_ceiling_floor(row, draw_post_ceiling_floor):
            return True
        return (
            (
                draw_post_all_known_source_context_stage
                or draw_product_translate_expression_graph_stage
            )
            and draw_post_all_known_structural_floor_rejected
            and _row_structural_guard_accepted(row)
        )
    return _row_progress_count(row) > 0


def _draw_post_ceiling_floor(
    context: MetaCeilingContext,
    score_rows: Sequence[Mapping[str, Any]],
) -> dict[str, int]:
    del score_rows
    floor = {"target": 0, "expression": 0}
    _collect_draw_post_ceiling_floor(context.current_ceiling, floor)
    if (
        _draw_alternate_stage_active(context)
        or _draw_post_alternate_source_context_stage_active(context)
        or _draw_post_source_context_whole_function_stage_active(context)
        or _draw_post_all_known_source_context_stage_active(context)
        or _draw_product_translate_expression_graph_stage_active(context)
        or _draw_stack_clean_no_anchor_recovery_stage_active(context)
        or _draw_post_stack_clean_no_anchor_source_shape_stage_active(context)
        or _draw_post_stack_loop_callsite_source_context_stage_active(context)
        or _draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage_active(
            context
        )
        or _draw_post_row_offset_owner_expression_lifetime_stage_active(context)
    ):
        floor["target"] = max(floor["target"], 1)
        floor["expression"] = max(floor["expression"], 1)
    return floor


def _collect_draw_post_ceiling_floor(raw: Any, floor: dict[str, int]) -> None:
    if isinstance(raw, Mapping):
        for key in ("best_target_matched", "target_matched"):
            value = _int_or_none(raw.get(key))
            if value is not None:
                floor["target"] = max(floor["target"], value)
        for key in ("best_expression_matched", "expression_matched"):
            value = _int_or_none(raw.get(key))
            if value is not None:
                floor["expression"] = max(floor["expression"], value)
        target_score = raw.get("target_score")
        if isinstance(target_score, Mapping):
            value = _int_or_none(target_score.get("matched"))
            if value is not None:
                floor["target"] = max(floor["target"], value)
        expression_score = raw.get("expression_score")
        if isinstance(expression_score, Mapping):
            value = _int_or_none(expression_score.get("matched"))
            if value is not None:
                floor["expression"] = max(floor["expression"], value)
        metrics = raw.get("metrics")
        if isinstance(metrics, Mapping):
            _collect_draw_post_ceiling_floor(metrics, floor)
        for value in raw.values():
            if isinstance(value, (Mapping, list, tuple)):
                _collect_draw_post_ceiling_floor(value, floor)
    elif isinstance(raw, Sequence) and not isinstance(raw, (str, bytes)):
        for value in raw:
            _collect_draw_post_ceiling_floor(value, floor)


def _row_exceeds_draw_post_ceiling_floor(
    row: Mapping[str, Any],
    floor: Mapping[str, int],
) -> bool:
    return _draw_post_alternate_score_matched(row, "target") > int(
        floor.get("target") or 0
    ) or _real_expression_matched(row) > int(floor.get("expression") or 0)


def _row_draw_post_stack_clean_frame_progress(row: Mapping[str, Any]) -> bool:
    if not _row_structural_guard_accepted(row):
        return False
    normalized_diff = _draw_stack_clean_no_anchor_normalized_diff_lines(row)
    if normalized_diff not in (None, 0):
        return False
    opcode_similarity = _draw_stack_clean_no_anchor_opcode_similarity(row)
    if opcode_similarity is not None and opcode_similarity < 0.999:
        return False
    frame = _draw_stack_clean_no_anchor_frame_facts(row)
    expected = _int_or_none(frame.get("expected_frame"))
    current = _int_or_none(frame.get("current_frame"))
    delta = _int_or_none(frame.get("frame_delta"))
    if expected is None or current is None:
        return False
    if current == expected or delta == 0:
        return True
    return abs(delta or 0) < 8


_DRAW_ALTERNATE_TERMINAL_SAFE_BLOCKER_REASONS = {
    "structural-guard-not-accepted",
    "protected-targets-not-jointly-preserved",
}


def _draw_alternate_floor_exhaustion_can_terminalize(
    score_rows: Sequence[Mapping[str, Any]],
    blockers: Sequence[Mapping[str, Any]],
    *,
    draw_alternate_stage: bool,
    draw_post_alternate_source_context_stage: bool,
    draw_post_source_context_whole_function_stage: bool,
    draw_post_all_known_source_context_stage: bool,
    draw_product_translate_expression_graph_stage: bool,
    draw_stack_clean_no_anchor_recovery_stage: bool,
    draw_post_stack_clean_no_anchor_source_shape_stage: bool,
    draw_post_stack_loop_callsite_source_context_stage: bool,
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage: bool,
    draw_post_row_offset_owner_expression_lifetime_stage: bool,
    draw_post_ceiling_floor: Mapping[str, int],
) -> bool:
    if (
        not draw_alternate_stage
        and not draw_post_alternate_source_context_stage
        and not draw_post_source_context_whole_function_stage
        and not draw_post_all_known_source_context_stage
        and not draw_product_translate_expression_graph_stage
        and not draw_stack_clean_no_anchor_recovery_stage
        and not draw_post_stack_clean_no_anchor_source_shape_stage
        and not draw_post_stack_loop_callsite_source_context_stage
        and not draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage
        and not draw_post_row_offset_owner_expression_lifetime_stage
    ) or not score_rows:
        return False
    if any(row.get("score_error") is not None for row in score_rows):
        return False
    if any(
        _row_exceeds_draw_post_ceiling_floor(row, draw_post_ceiling_floor)
        for row in score_rows
    ):
        return False
    blocker_reasons = {
        str(blocker.get("reason"))
        for blocker in blockers
        if isinstance(blocker, Mapping) and blocker.get("reason")
    }
    return bool(blocker_reasons) and blocker_reasons <= (
        _DRAW_ALTERNATE_TERMINAL_SAFE_BLOCKER_REASONS
    )


def _draw_no_floor_terminal_blocker(
    floor: Mapping[str, int],
    *,
    draw_post_alternate_source_context_stage: bool,
    draw_post_source_context_whole_function_stage: bool = False,
    draw_post_all_known_source_context_stage: bool = False,
    draw_product_translate_expression_graph_stage: bool = False,
    draw_stack_clean_no_anchor_recovery_stage: bool = False,
    draw_post_stack_clean_no_anchor_source_shape_stage: bool = False,
    draw_post_stack_loop_callsite_source_context_stage: bool = False,
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage: bool = False,
    draw_post_row_offset_owner_expression_lifetime_stage: bool = False,
) -> dict[str, Any]:
    if draw_post_row_offset_owner_expression_lifetime_stage:
        return _draw_post_row_offset_owner_expression_lifetime_no_floor_terminal_blocker(
            floor
        )
    if draw_post_stack_loop_callsite_expression_anchor_source_ownership_stage:
        return _draw_post_stack_loop_callsite_expression_anchor_source_ownership_no_floor_terminal_blocker(
            floor
        )
    if draw_post_stack_loop_callsite_source_context_stage:
        return _draw_post_stack_loop_callsite_source_context_no_floor_terminal_blocker(
            floor
        )
    if draw_post_stack_clean_no_anchor_source_shape_stage:
        return _draw_post_stack_clean_no_anchor_source_shape_no_floor_terminal_blocker(
            floor
        )
    if draw_stack_clean_no_anchor_recovery_stage:
        return _draw_stack_clean_no_anchor_recovery_no_floor_terminal_blocker(floor)
    if draw_product_translate_expression_graph_stage:
        return _draw_product_translate_expression_graph_no_floor_terminal_blocker(floor)
    if draw_post_all_known_source_context_stage:
        return _draw_post_all_known_source_context_no_floor_terminal_blocker(floor)
    if draw_post_source_context_whole_function_stage:
        return _draw_post_source_context_whole_function_no_floor_terminal_blocker(floor)
    if draw_post_alternate_source_context_stage:
        return _draw_post_alternate_source_context_no_floor_terminal_blocker(floor)
    return _draw_alternate_no_floor_terminal_blocker(floor)


