def _sort_full_selection_swap_source_candidates(
    source_text: str,
    context: MetaCeilingContext,
    *,
    validation_metadata: Mapping[str, Any],
    seen_source_hashes: set[str],
    seen_hunk_signatures: set[tuple[Any, ...]],
    per_dimension: dict[str, int],
    max_per_dimension: int,
) -> list[SourceFamilyCandidate]:
    if not _should_generate_sort_full_selection_swap(context):
        return []
    _, span = _find_source_function(source_text, context)
    if span is None:
        return []
    generated: list[SourceFamilyCandidate] = []
    for seed_info in _sort_full_selection_swap_seed_sources(source_text, context, span):
        if (
            max_per_dimension >= 0
            and per_dimension.get(SORT_FULL_SELECTION_SWAP_DIMENSION, 0)
            >= max_per_dimension
        ):
            break
        function_text = str(seed_info["function_text"])
        source_base_text = str(seed_info["source_base_text"])
        seed = seed_info.get("seed")
        seed_id = _non_empty_str(seed_info.get("seed_id"))
        for spec in _sort_full_selection_swap_patcher_specs():
            if (
                max_per_dimension >= 0
                and per_dimension.get(SORT_FULL_SELECTION_SWAP_DIMENSION, 0)
                >= max_per_dimension
            ):
                break
            patched_function = spec["patcher"](function_text)
            if patched_function is None or patched_function == function_text:
                continue
            patched_source = (
                source_text[: span.sig_start]
                + patched_function
                + source_text[span.full_end :]
            )
            source_hash = hashlib.sha256(patched_source.encode("utf-8")).hexdigest()
            if source_hash in seen_source_hashes:
                continue
            source_hunks = _source_hunks(
                source_base_text, patched_source, spec["variant_id"]
            )
            hunk_signature = _normalized_hunk_signature(source_hunks)
            if hunk_signature in seen_hunk_signatures:
                continue
            seen_source_hashes.add(source_hash)
            seen_hunk_signatures.add(hunk_signature)
            per_dimension[SORT_FULL_SELECTION_SWAP_DIMENSION] = (
                per_dimension.get(SORT_FULL_SELECTION_SWAP_DIMENSION, 0) + 1
            )
            candidate_id = str(spec["candidate_id"])
            if seed_id is not None:
                candidate_id = (
                    "post-meta-sort-full-selection-"
                    f"{_safe_id_fragment(seed_id)}-{spec['variant_id']}"
                )
            source_components = _source_components_from_spec(spec)
            metadata = dict(validation_metadata)
            metadata.update(
                {
                    "candidate_id": candidate_id,
                    "dimension_id": SORT_FULL_SELECTION_SWAP_DIMENSION,
                    "equivalence_class": spec["equivalence_class"],
                    "full_selection_swap_source_model": True,
                    "semantic_algorithm_shape": True,
                    "requires_target_score_validation": True,
                    "requires_full_unit_source": True,
                    "requires_structural_guard": True,
                    "score_function": context.source_function or context.function,
                    "source_components": [dict(item) for item in source_components],
                    "required_preserved_assignments": list(
                        SORT_FULL_SELECTION_SWAP_REQUIRED_ASSIGNMENTS
                    ),
                    "required_source_patterns": list(
                        SORT_FULL_SELECTION_SWAP_REQUIRED_SOURCE_PATTERNS
                    ),
                }
            )
            if isinstance(seed, Mapping):
                metadata.update(
                    {
                        "retained_pointer_loop_seed": True,
                        "seed_candidate_id": seed.get("candidate_id"),
                        "seed_source_retained": _first_present(
                            seed,
                            "source_retained",
                            "source_file",
                            "candidate_path",
                            "path",
                        ),
                        "seed_target_score": seed.get("target_score"),
                        "seed_structural_guard": seed.get("structural_guard"),
                    }
                )
            metadata["score_source_command_hint"] = _score_command_hint(metadata)
            generated.append(
                SourceFamilyCandidate(
                    candidate_id=candidate_id,
                    family=str(_profile_value(context.function, "family")),
                    dimension_id=SORT_FULL_SELECTION_SWAP_DIMENSION,
                    equivalence_class=str(spec["equivalence_class"]),
                    variant_id=str(spec["variant_id"]),
                    strategy=str(spec["strategy"]),
                    rationale=str(spec["rationale"]),
                    expected_effect=str(spec["expected_effect"]),
                    source_function=context.source_function,
                    source_text=patched_source,
                    source_hunks=source_hunks,
                    source_components=source_components,
                    target_assignments=context.target_assignments,
                    source_spans=[dict(row) for row in context.source_spans],
                    validation_metadata=metadata,
                    origin=str(spec["origin"]),
                    origin_family=(
                        _non_empty_str(seed.get("family"))
                        if isinstance(seed, Mapping)
                        else None
                    ),
                    origin_probe_id=(
                        _non_empty_str(seed.get("candidate_id"))
                        if isinstance(seed, Mapping)
                        else None
                    ),
                )
            )
    return generated


def _sort_full_selection_swap_seed_sources(
    source_text: str,
    context: MetaCeilingContext,
    span: Any,
) -> list[dict[str, Any]]:
    seeds: list[dict[str, Any]] = [
        {
            "function_text": source_text[span.sig_start : span.full_end],
            "source_base_text": source_text,
            "seed": None,
            "seed_id": None,
        }
    ]
    for seed in _sort_lower_drift_init_lifetime_seed_rows(context):
        seed_source = _sort_lower_drift_seed_source_text(seed, context)
        if seed_source is None:
            continue
        seed_function, seed_span = _find_source_function(seed_source, context)
        if seed_span is None:
            continue
        seed_function_text = seed_source[seed_span.sig_start : seed_span.full_end]
        if seed_function != context.source_function:
            seed_function_text = re.sub(
                rf"\b{re.escape(seed_function)}\b",
                context.source_function,
                seed_function_text,
                count=1,
            )
        seeds.append(
            {
                "function_text": seed_function_text,
                "source_base_text": (
                    source_text[: span.sig_start]
                    + seed_function_text
                    + source_text[span.full_end :]
                ),
                "seed": seed,
                "seed_id": _non_empty_str(seed.get("candidate_id")),
            }
        )
    return seeds


