def _sort_post_inline_boundary_selection_emission_source_shape_candidates(
    source_text: str,
    context: MetaCeilingContext,
    *,
    validation_metadata: Mapping[str, Any],
    seen_source_hashes: set[str],
    seen_hunk_signatures: set[tuple[Any, ...]],
    per_dimension: dict[str, int],
    max_per_dimension: int,
) -> list[SourceFamilyCandidate]:
    if not _should_generate_sort_post_inline_boundary_selection_emission_source_shape(
        context,
        continue_after_final_source_family=True,
    ):
        return []
    seeds = _sort_post_inline_boundary_selection_emission_seed_rows(context)
    if not seeds:
        return []

    seed = seeds[0]
    base_source = _sort_lower_drift_seed_source_text(seed, context) or source_text
    _, span = _find_source_function(base_source, context)
    if span is None:
        return []
    function_text = base_source[span.sig_start : span.full_end]
    if not _post_inline_boundary_selection_emission_region_ready(function_text):
        return []

    generated: list[SourceFamilyCandidate] = []
    for spec in _sort_post_inline_boundary_selection_emission_source_shape_specs():
        if (
            max_per_dimension >= 0
            and per_dimension.get(
                SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION,
                0,
            )
            >= max_per_dimension
        ):
            return generated
        patched_source = _post_inline_boundary_selection_emission_patcher(
            base_source,
            span,
            selected_state=str(spec["selected_state"]),
            emission_owner=bool(spec.get("emission_owner")),
        )
        if patched_source is None or patched_source == base_source:
            continue
        source_hash = hashlib.sha256(patched_source.encode("utf-8")).hexdigest()
        if source_hash in seen_source_hashes:
            continue
        variant_id = str(spec["variant_id"])
        source_hunks = _source_hunks(source_text, patched_source, variant_id)
        hunk_signature = _normalized_hunk_signature(source_hunks)
        if hunk_signature in seen_hunk_signatures:
            continue
        seen_source_hashes.add(source_hash)
        seen_hunk_signatures.add(hunk_signature)
        per_dimension[
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
        ] = (
            per_dimension.get(
                SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION,
                0,
            )
            + 1
        )
        candidate_id = str(spec["candidate_id"])
        source_components = _source_components_from_spec(spec)
        metadata = dict(validation_metadata)
        metadata.update(
            {
                "candidate_id": candidate_id,
                "dimension_id": (
                    SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
                ),
                "equivalence_class": spec["equivalence_class"],
                "post_inline_boundary_selection_emission_source_shape": True,
                "semantic_algorithm_shape": True,
                "requires_target_score_validation": True,
                "requires_full_unit_source": True,
                "requires_structural_guard": True,
                "score_function": context.source_function or context.function,
                "source_model_layer_dimension_id": (
                    SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
                ),
                "source_components": [dict(item) for item in source_components],
                "required_preserved_assignments": list(
                    SORT_FULL_SELECTION_SWAP_REQUIRED_ASSIGNMENTS
                ),
                "required_source_patterns": list(
                    SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_REQUIRED_SOURCE_PATTERNS
                ),
                "seed_candidate_id": seed.get("candidate_id"),
                "seed_source_retained": (
                    seed.get("source_retained")
                    or seed.get("source_file")
                    or seed.get("candidate_path")
                    or seed.get("path")
                ),
                "seed_pcdump_path": seed.get("pcdump_path"),
                "seed_source_hunks": list(seed.get("source_hunks") or []),
                "seed_source_components": list(seed.get("source_components") or []),
                "seed_target_score": seed.get("target_score"),
                "seed_structural_guard": seed.get("structural_guard"),
                "seed_one_hit_targets": sorted(
                    _target_hit_virtuals(seed, context.force_phys)
                ),
                "ranked_seed_candidates": seeds,
            }
        )
        metadata["score_source_command_hint"] = _score_command_hint(metadata)
        generated.append(
            SourceFamilyCandidate(
                candidate_id=candidate_id,
                family=str(_profile_value(context.function, "family")),
                dimension_id=(
                    SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
                ),
                equivalence_class=str(spec["equivalence_class"]),
                variant_id=variant_id,
                strategy=str(spec["strategy"]),
                rationale=str(spec["rationale"]),
                expected_effect=str(spec["expected_effect"]),
                source_function=context.source_function,
                source_text=patched_source,
                source_hunks=source_hunks,
                source_components=source_components,
                target_assignments=context.target_assignments,
                source_spans=[dict(row) for row in context.source_spans],
                validation_metadata=metadata,
                origin=str(spec["origin"]),
            )
        )
    return generated


def _post_broader_natural_inline_boundary_patcher(
    source_text: str,
    span: Any,
    *,
    helper_mode: str,
    dst_owner: bool,
) -> str | None:
    function_text = source_text[span.sig_start : span.full_end]
    owner = "dst" if dst_owner else "mnDiagram_804A076C.sorted_names"
    helper_name = f"mnDiagram_SortNamesPostBroader_{helper_mode.replace('-', '_')}"
    comparison = _post_broader_natural_inline_boundary_comparison_block(
        owner=owner,
        helper_name=helper_name,
        helper_mode=helper_mode,
    )
    if comparison is None:
        return None
    patched_function = _SORT_POST_CROSS_TU_J_LOOP_RE.sub(
        lambda match: f"{match.group(1)}{comparison}{match.group(2)}",
        function_text,
        count=1,
    )
    if patched_function == function_text:
        return None
    if dst_owner:
        patched_function = patched_function.replace(
            _SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK,
            """\
            u8* p = dst + max_idx;
            u8 temp = p[0];
""",
            1,
        )
    helper = _post_broader_natural_inline_boundary_helper(
        helper_name,
        helper_mode=helper_mode,
    )
    prefix = source_text[: span.sig_start]
    if helper:
        prefix = f"{prefix}{helper}\n"
    return prefix + patched_function + source_text[span.full_end :]


def _post_broader_natural_inline_boundary_helper(
    helper_name: str,
    *,
    helper_mode: str,
) -> str:
    if helper_mode in {"names", "names-totals"}:
        return f"""\
static inline int {helper_name}(u8 selected_name, u8 candidate_name, u32* totals)
{{
    char* selected_text = GetNameText((0, selected_name));
    char* candidate_text = GetNameText(candidate_name);
    if (candidate_text != NULL)
    {{
        if (totals[selected_name] < totals[candidate_name])
        {{
            return 1;
        }}
        if (selected_text == NULL)
        {{
            return 1;
        }}
    }}
    return 0;
}}
"""
    if helper_mode == "preloaded":
        return f"""\
static inline int {helper_name}(char* selected_text, char* candidate_text, u32 selected_total, u32 candidate_total)
{{
    if (candidate_text == NULL)
    {{
        return 0;
    }}
    if (selected_total < candidate_total)
    {{
        return 1;
    }}
    return selected_text == NULL;
}}
"""
    return ""


def _post_broader_natural_inline_boundary_comparison_block(
    *,
    owner: str,
    helper_name: str,
    helper_mode: str,
) -> str | None:
    if helper_mode in {"names", "names-totals"}:
        return f"""\
            {{
                u8 selected_name = {owner}[max_idx];
                u8 candidate_name = {owner}[j];
                if ({helper_name}(selected_name, candidate_name, totals) != 0)
                {{
                    max_idx = j;
                }}
            }}
"""
    if helper_mode == "preloaded":
        return f"""\
            {{
                u8 selected_name = {owner}[max_idx];
                u8 candidate_name = {owner}[j];
                char* selected_text = GetNameText((0, selected_name));
                char* candidate_text = GetNameText(candidate_name);
                u32 selected_total = totals[selected_name];
                u32 candidate_total = totals[candidate_name];
                if ({helper_name}(selected_text, candidate_text, selected_total, candidate_total) != 0)
                {{
                    max_idx = j;
                }}
            }}
"""
    if helper_mode == "local-decision":
        return f"""\
            {{
                u8 selected_name = {owner}[max_idx];
                u8 candidate_name = {owner}[j];
                char* selected_text = GetNameText((0, selected_name));
                char* candidate_text = GetNameText(candidate_name);
                int candidate_better = 0;
                if (candidate_text != NULL)
                {{
                    if (totals[selected_name] < totals[candidate_name])
                    {{
                        candidate_better = 1;
                    }}
                    else if (selected_text == NULL)
                    {{
                        candidate_better = 1;
                    }}
                }}
                if (candidate_better != 0)
                {{
                    max_idx = j;
                }}
            }}
"""
    return None


def _post_inline_boundary_selection_emission_region_ready(
    function_text: str,
) -> bool:
    return (
        _SORT_POST_INLINE_SELECTION_LOOP_RE.search(function_text) is not None
        and _SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK in function_text
    )


def _post_inline_boundary_selection_emission_patcher(
    source_text: str,
    span: Any,
    *,
    selected_state: str,
    emission_owner: bool,
) -> str | None:
    function_text = source_text[span.sig_start : span.full_end]
    replacement = _post_inline_boundary_selection_emission_loop_block(
        selected_state=selected_state,
    )
    if replacement is None:
        return None
    patched_function = _SORT_POST_INLINE_SELECTION_LOOP_RE.sub(
        lambda match: (
            f"{match.group(1)}"
            f"{replacement}"
            f"{match.group(3)}"
        ),
        function_text,
        count=1,
    )
    if patched_function == function_text:
        return None
    if emission_owner:
        patched_function = patched_function.replace(
            _SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK,
            """\
            u8* p = dst + max_idx;
            u8 temp = *p;
""",
            1,
        )
    return source_text[: span.sig_start] + patched_function + source_text[span.full_end :]


def _post_inline_boundary_selection_emission_loop_block(
    *,
    selected_state: str,
) -> str | None:
    if selected_state == "decision":
        return """\
        for (j = i + 1; j < 0x78; j++) {
            u8 selected_name = mnDiagram_804A076C.sorted_names[max_idx];
            u8 candidate_name = mnDiagram_804A076C.sorted_names[j];
            char* selected_text = GetNameText((0, selected_name));
            char* candidate_text = GetNameText(candidate_name);
            int candidate_better = 0;
            if (candidate_text != NULL)
            {
                if (totals[selected_name] < totals[candidate_name])
                {
                    candidate_better = 1;
                }
                else if (selected_text == NULL)
                {
                    candidate_better = 1;
                }
            }
            if (candidate_better != 0)
            {
                max_idx = j;
            }
        }
"""
    if selected_state == "name":
        return """\
        {
            u8 selected_name = mnDiagram_804A076C.sorted_names[max_idx];
            for (j = i + 1; j < 0x78; j++) {
                u8 candidate_name = mnDiagram_804A076C.sorted_names[j];
                char* selected_text = GetNameText((0, selected_name));
                char* candidate_text = GetNameText(candidate_name);
                int candidate_better = 0;
                if (candidate_text != NULL)
                {
                    if (totals[selected_name] < totals[candidate_name])
                    {
                        candidate_better = 1;
                    }
                    else if (selected_text == NULL)
                    {
                        candidate_better = 1;
                    }
                }
                if (candidate_better != 0)
                {
                    max_idx = j;
                    selected_name = candidate_name;
                }
            }
        }
"""
    if selected_state == "text-total":
        return """\
        {
            u8 selected_name = mnDiagram_804A076C.sorted_names[max_idx];
            char* selected_text = GetNameText((0, selected_name));
            u32 selected_total = totals[selected_name];
            for (j = i + 1; j < 0x78; j++) {
                u8 candidate_name = mnDiagram_804A076C.sorted_names[j];
                char* candidate_text = GetNameText(candidate_name);
                u32 candidate_total = totals[candidate_name];
                int candidate_better = 0;
                if (candidate_text != NULL)
                {
                    if (selected_total < candidate_total)
                    {
                        candidate_better = 1;
                    }
                    else if (selected_text == NULL)
                    {
                        candidate_better = 1;
                    }
                }
                if (candidate_better != 0)
                {
                    max_idx = j;
                    selected_name = candidate_name;
                    selected_text = candidate_text;
                    selected_total = candidate_total;
                }
            }
        }
"""
    return None


def _post_cross_tu_selection_swap_region_ready(function_text: str) -> bool:
    return (
        _SORT_POST_CROSS_TU_J_LOOP_RE.search(function_text) is not None
        and _SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK in function_text
    )


_SORT_POST_CROSS_TU_J_LOOP_RE = re.compile(
    r"(        for \(j = i \+ 1; j < 0x78; j\+\+\) \{\n)"
    r".*?"
    r"(        \}\n        if \(max_idx != i\) \{)",
    re.DOTALL,
)


_SORT_POST_INLINE_SELECTION_LOOP_RE = re.compile(
    r"(        max_idx = i;\n)"
    r"(        for \(j = i \+ 1; j < 0x78; j\+\+\) \{\n)"
    r".*?"
    r"        \}\n"
    r"(        if \(max_idx != i\) \{)",
    re.DOTALL,
)


_SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK = """\
            u8* p = &assets->sorted_fighters[max_idx];
            u8 temp = *(p += sizeof(mnDiagram_804A0750_t));
"""


def _post_cross_tu_selection_swap_patcher(
    *,
    names: bool = False,
    dst_owner: bool = False,
    cache: bool = False,
    emission: bool = False,
) -> Any:
    def patch(function_text: str) -> str | None:
        if not _post_cross_tu_selection_swap_region_ready(function_text):
            return None
        out = function_text
        comparison = _post_cross_tu_selection_swap_comparison_block(
            names=names,
            dst_owner=dst_owner,
            cache=cache,
        )
        out = _SORT_POST_CROSS_TU_J_LOOP_RE.sub(
            lambda match: f"{match.group(1)}{comparison}{match.group(2)}",
            out,
            count=1,
        )
        if emission:
            out = out.replace(
                _SORT_POST_CROSS_TU_BASE_EMISSION_BLOCK,
                """\
            u8* p = dst + max_idx;
            u8 temp = *p;
""",
                1,
            )
        return out

    return patch


def _post_cross_tu_selection_swap_comparison_block(
    *,
    names: bool,
    dst_owner: bool,
    cache: bool,
) -> str:
    owner = "dst" if dst_owner else "mnDiagram_804A076C.sorted_names"
    if cache:
        return f"""\
            {{
                u8 selected_name = {owner}[max_idx];
                u8 candidate_name = {owner}[j];
                char* selected_text = GetNameText((0, selected_name));
                char* candidate_text = GetNameText(candidate_name);
                u32 selected_total = totals[selected_name];
                u32 candidate_total = totals[candidate_name];
                if ((candidate_text != NULL) &&
                    ((selected_total < candidate_total) ||
                     ((selected_text == NULL) && (candidate_text != NULL))))
                {{
                    max_idx = j;
                }}
            }}
"""
    if names:
        return f"""\
            {{
                u8 selected_name = {owner}[max_idx];
                u8 candidate_name = {owner}[j];
                if ((GetNameText(candidate_name) != NULL) &&
                    ((totals[selected_name] < totals[candidate_name]) ||
                     ((GetNameText((0, selected_name)) == NULL) &&
                      (GetNameText(candidate_name) != NULL))))
                {{
                    max_idx = j;
                }}
            }}
"""
    return f"""\
            if ((GetNameText({owner}[j]) != NULL) &&
                ((totals[{owner}[max_idx]] < totals[{owner}[j]]) ||
                 ((GetNameText((0, {owner}[max_idx])) == NULL) &&
                  (GetNameText({owner}[j]) != NULL))))
            {{
                max_idx = j;
            }}
"""


