def _sort_helper_data_layout_context_exhausted(
    context: MetaCeilingContext,
) -> bool:
    if context.function != SORT_FUNCTION:
        return False
    next_models = set(
        _nested_strings_for_key(
            context.current_ceiling, "next_unsupported_source_model"
        )
    )
    if context.next_unsupported_source_model:
        next_models.add(context.next_unsupported_source_model)
    next_families = set(
        _nested_strings_for_key(
            context.current_ceiling, "next_unsupported_source_family"
        )
    )
    if context.next_unsupported_source_family:
        next_families.add(context.next_unsupported_source_family)
    exhausted_rows = _list_of_dicts(
        context.current_ceiling.get("exhausted_dimensions")
    )
    synthesis = context.current_ceiling.get("source_family_synthesis")
    if isinstance(synthesis, Mapping):
        exhausted_rows.extend(_list_of_dicts(synthesis.get("exhausted_dimensions")))
    if any(
        row.get("dimension_id") == SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION
        and _source_family_exhausted_dimension_row_has_materialized_evidence(row)
        for row in exhausted_rows
    ):
        return True
    if isinstance(synthesis, Mapping) and (
        SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION
        in _string_items(synthesis.get("attempted_equivalence_classes"))
    ):
        if _source_family_synthesis_has_materialized_dimension_evidence(
            synthesis,
            SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION,
        ):
            return True
    if SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_MODEL in next_models:
        return True
    if SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_FAMILY in next_families:
        return True
    return False


def _source_family_exhausted_dimension_row_has_materialized_evidence(
    row: Mapping[str, Any],
) -> bool:
    for key in (
        "candidate_ids",
        "scored_candidate_ids",
        "generated_candidate_ids",
        "all_candidate_ids",
    ):
        if _string_items(row.get(key)):
            return True
    for key in (
        "candidate_count",
        "scored_count",
        "generated_candidate_count",
        "scored_candidate_count",
        "available_candidate_count",
    ):
        value = _int_or_none(row.get(key))
        if value is not None and value > 0:
            return True
    status = str(row.get("status") or "").lower()
    if "continuation-exhausted" in status:
        return False
    return "scored" in status or "materialized" in status


def _source_family_synthesis_has_materialized_dimension_evidence(
    synthesis: Mapping[str, Any],
    dimension_id: str,
) -> bool:
    for row in _list_of_dicts(synthesis.get("equivalence_class_details")):
        if (
            row.get("dimension_id") == dimension_id
            and _source_family_exhausted_dimension_row_has_materialized_evidence(row)
        ):
            return True
    for key in (
        "source_hunks_by_candidate",
        "candidate_scores",
        "retained_scored_probes",
        "retained_candidate_inputs",
    ):
        for row in _list_of_dicts(synthesis.get(key)):
            if row.get("dimension_id") == dimension_id:
                return True
    return False


