def _should_generate_sort_post_cross_tu_broader_natural_rewrite(
    context: MetaCeilingContext,
    *,
    continue_after_final_source_family: bool = False,
) -> bool:
    top_level_selection_swap_final = (
        context.next_unsupported_source_family
        == SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_FINAL_FAMILY
        and context.next_unsupported_source_model
        == SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_FINAL_MODEL
    )
    return bool(
        (continue_after_final_source_family or top_level_selection_swap_final)
        and _sort_post_cross_tu_selection_swap_no_modeled_source_family_terminal(
            context
        )
    )


