def _sort_post_inline_boundary_selection_emission_terminal_sentinel(
    context: MetaCeilingContext,
) -> bool:
    next_models = set(
        _nested_strings_for_key(
            context.current_ceiling,
            "next_unsupported_source_model",
        )
    )
    if context.next_unsupported_source_model:
        next_models.add(context.next_unsupported_source_model)
    next_families = set(
        _nested_strings_for_key(
            context.current_ceiling,
            "next_unsupported_source_family",
        )
    )
    if context.next_unsupported_source_family:
        next_families.add(context.next_unsupported_source_family)
    terminal_reasons = set(
        _nested_strings_for_key(context.current_ceiling, "terminal_reason")
    )
    return (
        SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_FINAL_MODEL
        in next_models
        and SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_FINAL_FAMILY
        in next_families
    ) or (
        SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_TERMINAL_REASON
        in terminal_reasons
    )


