def _sort_post_inline_boundary_selection_emission_seed_rows(
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    evidence = _sort_post_cross_tu_retained_terminal_evidence(context)
    hunk_rows = {
        str(row.get("candidate_id")): row
        for row in evidence.get("source_hunks_by_candidate", [])
        if isinstance(row, Mapping) and row.get("candidate_id")
    }
    rows: list[dict[str, Any]] = []
    for raw in [
        *evidence.get("candidate_scores", []),
        *evidence.get("retained_scored_probes", []),
    ]:
        if not isinstance(raw, Mapping):
            continue
        row = dict(raw)
        candidate_id = str(row.get("candidate_id") or "")
        hunk_row = hunk_rows.get(candidate_id)
        if hunk_row:
            row.setdefault("source_hunks", list(hunk_row.get("source_hunks") or []))
            row.setdefault(
                "source_components",
                list(hunk_row.get("source_components") or []),
            )
        if not _is_sort_post_inline_boundary_selection_emission_seed_row(
            row,
            context,
        ):
            continue
        rows.append(row)
    return _dedupe_dicts(
        sorted(
            rows,
            key=_sort_post_inline_boundary_selection_emission_seed_rank_key,
        )
    )


