def _with_draw_retained_source_components(row: Mapping[str, Any]) -> dict[str, Any]:
    out = dict(row)
    if out.get("source_components"):
        return out
    dimension_id = out.get("dimension_id")
    if dimension_id == DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION:
        out["source_components"] = [
            dict(component)
            for component in DRAW_POST_ALTERNATE_SOURCE_CONTEXT_COMPONENTS.values()
        ]
    elif dimension_id == DRAW_POST_SOURCE_CONTEXT_DIMENSION:
        out["source_components"] = [
            dict(component)
            for component in DRAW_POST_SOURCE_CONTEXT_COMPONENTS.values()
        ]
    elif dimension_id == DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_DIMENSION:
        out["source_components"] = [
            dict(component)
            for component in DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_COMPONENTS.values()
        ]
    elif dimension_id == DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_DIMENSION:
        out["source_components"] = [
            dict(component)
            for component in DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_COMPONENTS.values()
        ]
    return out


def _draw_post_alternate_evidence_rows(
    evidence: Mapping[str, Any],
) -> list[dict[str, Any]]:
    return _dedupe_dicts(
        [
            *_list_of_dicts(evidence.get("candidate_scores")),
            *_list_of_dicts(evidence.get("retained_scored_probes")),
        ]
    )


def _draw_post_alternate_row_has_real_evidence(row: Mapping[str, Any]) -> bool:
    return (
        _non_empty_str(row.get("candidate_id")) is not None
        and row.get("dimension_id") == DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_DIMENSION
        and _non_empty_str(row.get("source_retained")) is not None
        and _non_empty_str(row.get("pcdump_path")) is not None
        and isinstance(row.get("target_score"), Mapping)
        and isinstance(row.get("expression_score"), Mapping)
        and bool(_list_of_dicts(row.get("source_hunks")))
    )


def _draw_post_alternate_score_floor(
    rows: Sequence[Mapping[str, Any]],
) -> dict[str, int]:
    floor = {"target": 1, "expression": 1}
    for row in rows:
        metadata = row.get("validation_metadata")
        if not isinstance(metadata, Mapping):
            continue
        target_floor = _int_or_none(metadata.get("baseline_target_floor"))
        expression_floor = _int_or_none(metadata.get("baseline_expression_floor"))
        if target_floor is not None:
            floor["target"] = max(floor["target"], target_floor)
        if expression_floor is not None:
            floor["expression"] = max(floor["expression"], expression_floor)
    return floor


def _draw_post_alternate_row_exceeds_floor(
    row: Mapping[str, Any],
    floor: Mapping[str, int],
) -> bool:
    target_matched = _draw_post_alternate_score_matched(row, "target")
    expression_matched = _real_expression_matched(row)
    return target_matched > int(floor.get("target") or 0) or expression_matched > int(
        floor.get("expression") or 0
    )


def _draw_post_alternate_score_matched(
    row: Mapping[str, Any],
    score_kind: str,
) -> int:
    direct = _int_or_none(row.get(f"{score_kind}_matched"))
    if direct is not None:
        return direct
    score = row.get(f"{score_kind}_score")
    if isinstance(score, Mapping):
        nested = _int_or_none(score.get("matched"))
        if nested is not None:
            return nested
    return 0


