def _source_components_from_spec(spec: Mapping[str, Any]) -> list[dict[str, Any]]:
    rows = spec.get("source_components")
    if not isinstance(rows, Sequence) or isinstance(rows, (str, bytes)):
        return []
    return [dict(row) for row in rows if isinstance(row, Mapping)]


def _should_generate_sort_natural_rewrites(context: MetaCeilingContext) -> bool:
    if context.function != SORT_FUNCTION:
        return False
    next_model = (
        _non_empty_str(context.next_unsupported_source_model)
        or _non_empty_str(context.current_ceiling.get("next_unsupported_source_model"))
        or ""
    ).lower()
    if (
        "broader natural c sort rewrite" in next_model
        or "broader sort source-family synthesis" in next_model
    ):
        return True
    evidence = set(_nested_string_values(context.current_ceiling))
    return (
        set(SOURCE_FAMILY_DIMENSIONS) <= evidence
        and {
            "sort-one-hit-structural-repair",
            "sort-one-hit-recombination",
        }
        <= evidence
    )


def _should_generate_sort_semantic_algorithm_shapes(
    context: MetaCeilingContext,
) -> bool:
    if context.function != SORT_FUNCTION:
        return False
    next_model = (
        _non_empty_str(context.next_unsupported_source_model)
        or _non_empty_str(context.current_ceiling.get("next_unsupported_source_model"))
        or ""
    ).lower()
    if "broader natural c sort rewrite" in next_model:
        return False
    semantic_markers = (
        "semantic sort algorithm shape",
        "unmodeled semantic sort algorithm shape",
        "outside the bounded natural rewrite generator",
    )
    return any(marker in next_model for marker in semantic_markers)


def _nested_string_values(value: Any) -> list[str]:
    if isinstance(value, str):
        return [value]
    if isinstance(value, Mapping):
        out: list[str] = []
        for key, item in value.items():
            if isinstance(key, str):
                out.append(key)
            out.extend(_nested_string_values(item))
        return out
    if isinstance(value, Sequence) and not isinstance(value, (str, bytes)):
        out: list[str] = []
        for item in value:
            out.extend(_nested_string_values(item))
        return out
    return []


def _compose_sort_patchers(*patchers: Any) -> Any:
    def patch(function_text: str) -> str | None:
        patched = function_text
        for patcher in patchers:
            next_source = patcher(patched)
            if next_source is None or next_source == patched:
                return None
            patched = next_source
        return patched

    return patch


