def _draw_product_translate_expression_graph_region_ready(
    function_text: str,
) -> tuple[bool, list[str]]:
    missing: list[str] = []
    if not re.search(r"for\s*\(\s*i\s*=\s*0\s*;\s*i\s*<\s*digit_count", function_text):
        missing.append("for (i = 0; i < digit_count; i++) digit loop")
    if "HSD_JObjSetTranslateX" not in function_text:
        missing.append("HSD_JObjSetTranslateX loop callsite")
    if "x_spacing" not in function_text or "col_offset" not in function_text:
        missing.append("loop-index translate plus col_offset call argument")
    if "col_offset" not in function_text or "col" not in function_text:
        missing.append("col_offset product")
    if not (
        "y_offset" in function_text
        or "row_offset = HSD_JObjGetTranslationY" in function_text
    ):
        missing.append("legacy y_offset or retained row_offset row delta")
    if "row_offset" not in function_text or "row" not in function_text:
        missing.append("row_offset product")
    return not missing, missing


def _compose_draw_function_patchers(*patchers: Any) -> Any:
    def patch(function_text: str) -> str | None:
        patched = function_text
        changed = False
        for patcher in patchers:
            next_text = patcher(patched)
            if next_text is None:
                return None
            if next_text != patched:
                changed = True
            patched = next_text
        return patched if changed else None

    return patch


