def _indexed_comparison_block(
    indent: str,
    *,
    prelude: Sequence[str],
    j_text: str,
    max_total: str,
    j_total: str,
    max_text: str,
) -> str:
    lines = [f"{indent}{{"]
    lines.extend(f"{indent}    {line}" for line in prelude)
    lines.extend(
        [
            f"{indent}    if (({j_text} != NULL) &&",
            f"{indent}        (({max_total} < {j_total}) ||",
            f"{indent}         (({max_text} == NULL) &&",
            f"{indent}          ({j_text} != NULL))))",
            f"{indent}    {{",
            f"{indent}        max_idx = j;",
            f"{indent}    }}",
            f"{indent}}}",
        ]
    )
    return "\n".join(lines)


