def _patch_sort_source_context_comparison_helper(
    source_text: str,
    span: Any,
) -> str | None:
    helper_name = "mnDiagram_PostMetaSortCandidateBetter"
    if helper_name in source_text:
        return None
    patched = _replace_sort_comparison_condition(
        source_text,
        f"{helper_name}(totals, max_idx, j)",
    )
    if patched is None:
        return None
    helper = f"""\
static inline int {helper_name}(u32* totals, int max_idx, int j)
{{
    u8 candidate_name = mnDiagram_804A076C.sorted_names[j];
    u8 selected_name = mnDiagram_804A076C.sorted_names[max_idx];

    return (GetNameText(candidate_name) != NULL) &&
        ((totals[selected_name] < totals[candidate_name]) ||
         ((GetNameText((0, selected_name)) == NULL) &&
          (GetNameText(candidate_name) != NULL)));
}}

"""
    return _insert_before_sort_function(patched, span, helper)


