def _replace_sort_comparison_condition(
    source_text: str,
    replacement_call: str,
) -> str | None:
    old = """\
            if ((GetNameText(mnDiagram_804A076C.sorted_names[j]) != NULL) &&
                ((totals[mnDiagram_804A076C.sorted_names[max_idx]] <
                  totals[mnDiagram_804A076C.sorted_names[j]]) ||
                 ((GetNameText(
                       (0, mnDiagram_804A076C.sorted_names[max_idx])) ==
                   NULL) &&
                  (GetNameText(mnDiagram_804A076C.sorted_names[j]) != NULL))))"""
    if old not in source_text:
        return None
    return source_text.replace(old, f"            if ({replacement_call})", 1)


def _insert_before_sort_function(
    source_text: str,
    span: Any,
    insertion: str,
) -> str:
    return source_text[: span.sig_start] + insertion + source_text[span.sig_start :]


def _insert_before_function_name(
    source_text: str,
    function_name: str,
    insertion: str,
) -> str | None:
    pattern = re.compile(
        rf"(?m)^.*\b{re.escape(function_name)}\s*\(",
    )
    match = pattern.search(source_text)
    if match is None:
        return None
    return source_text[: match.start()] + insertion + source_text[match.start() :]


