def _patch_draw_col_factor_local(function_text: str) -> str | None:
    patched = _replace_first_pattern(
        function_text,
        r"(?P<indent>[ \t]*)col_offset\s*=\s*y_spacing\s*\*\s*\(f32\)\s*col\s*;",
        lambda match: (
            f"{match.group('indent')}{{\n"
            f"{match.group('indent')}    f32 post_meta_col_factor;\n"
            f"{match.group('indent')}    post_meta_col_factor = (f32) col;\n"
            f"{match.group('indent')}    col_offset = y_spacing * post_meta_col_factor;\n"
            f"{match.group('indent')}}}"
        ),
    )
    if patched is not None:
        return patched
    return _patch_draw_col_factor_local_split(function_text)


