            r"(?P<gap>(?:[ \t]*\n|(?P=indent)digit_count\s*=\s*mn_GetDigitCount\([^;]+\);\s*\n|(?P=indent)col_offset\s*=\s*\(f32\)\s*col\s*;\s*\n|(?P=indent)col_offset\s*\*=\s*y_spacing\s*;\s*)*)"
            r"(?P=indent)rowf\s*=\s*\(f32\)\s*row\s*;\s*\n"
