def _indent_draw_patch_gap(gap: str, indent: str) -> str:
    lines: list[str] = []
    for line in gap.splitlines(keepends=True):
        if line.strip():
            lines.append(indent + line.lstrip(" \t"))
        else:
            lines.append(line)
    return "".join(lines)


