def _draw_post_alternate_function_region_ready(
    function_text: str,
) -> tuple[bool, list[str]]:
    checks: list[tuple[str, bool]] = [
        (
            "data/jobjs[11], data/jobjs[12], data/jobjs[7], and data/jobjs[8] pre-loop object anchors",
            all(
                re.search(rf"\bdata\s*->\s*jobjs\s*\[\s*{index}\s*\]", function_text)
                is not None
                for index in (11, 12, 7, 8)
            ),
        ),
        (
            "legacy y_offset or retained row_offset/rowf spacing and offset block",
            _draw_source_context_has_offset_region(function_text),
        ),
        (
            "digit_count = mn_GetDigitCount(...) before the digit loop",
            re.search(r"digit_count\s*=\s*mn_GetDigitCount\s*\(", function_text)
            is not None,
        ),
        (
            "for (i = 0; i < digit_count; i++) digit loop",
            _draw_loop_region(function_text) is not None,
        ),
        (
            "mn_GetDigitAt digit extraction",
            "mn_GetDigitAt" in function_text,
        ),
        (
            "HSD_JObjReqAnimAll followed by HSD_JObjAnimAll",
            "HSD_JObjReqAnimAll" in function_text
            and "HSD_JObjAnimAll" in function_text
            and function_text.find("HSD_JObjReqAnimAll")
            < function_text.find("HSD_JObjAnimAll"),
        ),
        (
            "HSD_JObjSetTranslateX and HSD_JObjSetTranslateY loop callsites",
            "HSD_JObjSetTranslateX" in function_text
            and "HSD_JObjSetTranslateY" in function_text,
        ),
        (
            "HSD_JObjAddChild loop callsite",
            "HSD_JObjAddChild" in function_text,
        ),
    ]
    missing = [label for label, ok in checks if not ok]
    return not missing, missing


def _draw_post_source_context_whole_function_region_ready(
    function_text: str,
) -> tuple[bool, list[str]]:
    post_alt_ready, missing = _draw_post_alternate_function_region_ready(function_text)
    checks: list[tuple[str, bool]] = [
        (
            "data/user_data and data_alias pre-loop ownership anchors",
            re.search(
                r"\bdata\s*=\s*\(\(\s*HSD_GObj\s*\*\s*\)\s*[A-Za-z_]\w*\s*\)"
                r"\s*->\s*user_data\s*;",
                function_text,
            )
            is not None
            and re.search(r"\bdata_alias\s*=\s*data\s*;", function_text) is not None,
        ),
        (
            "data->jobjs[11], [12], [7], [8], [9], and [10] pre-loop object anchors",
            all(
                re.search(rf"\bdata\s*->\s*jobjs\s*\[\s*{index}\s*\]", function_text)
                is not None
                for index in (11, 12, 7, 8, 9, 10)
            ),
        ),
        (
            "legacy y_offset or retained row_offset/rowf split x/y spacing and offset setup",
            all(
                re.search(rf"\b{name}\s*=", function_text) is not None
                for name in (
                    "x_spacing",
                    "y_spacing",
                    "col_offset",
                    "row_offset",
                    "row_offset_adj",
                )
            )
            and _draw_source_context_has_offset_region(function_text),
        ),
        (
            "joint_data = mnDiagram_804A07F4 or &mnDiagram_804A07F4 before the digit loop",
            re.search(
                r"joint_data\s*=\s*&?\s*mnDiagram_804A07F4\s*;",
                function_text,
            )
            is not None,
        ),
    ]
    missing.extend(label for label, ok in checks if not ok)
    return post_alt_ready and not missing, missing


def _draw_source_context_has_offset_region(function_text: str) -> bool:
    sentinel = "__draw_source_context_probe__"
    return (
        _patch_draw_alt_offset_region_legacy(function_text, lambda _: sentinel)
        is not None
        or _patch_draw_alt_offset_region_retained_split(
            function_text,
            lambda _: sentinel,
        )
        is not None
    )


def _patch_draw_source_context_jobjs_array_local(
    function_text: str,
) -> str | None:
    if "HSD_JObj** jobjs;" in function_text:
        return None
    patched = _ensure_draw_local_declaration(
        function_text,
        "HSD_JObj** jobjs;",
        after_decl="Diagram* data;",
    )
    if patched is None:
        return None
    patched = patched.replace("data->jobjs[", "jobjs[")
    return _insert_draw_statement_after_data_alias(
        patched,
        "jobjs = data->jobjs;",
    )


def _patch_draw_source_context_parent_jobj_local(
    function_text: str,
) -> str | None:
    if "HSD_JObj* parent;" in function_text:
        return None
    patched = _ensure_draw_local_declaration(
        function_text,
        "HSD_JObj* parent;",
        after_decl="HSD_JObj* jobj2;",
    )
    if patched is None:
        return None
    patched = _insert_draw_statement_after_data_alias(
        patched,
        "parent = data_alias->jobjs[11];",
    )
    if patched is None:
        return None
    replaced = re.sub(
        r"HSD_JObjAddChild\(\s*data_alias\s*->\s*jobjs\s*\[\s*11\s*\]\s*,",
        "HSD_JObjAddChild(parent,",
        patched,
        count=1,
    )
    return replaced if replaced != function_text else None


def _patch_draw_source_context_base_snapshot_locals(
    function_text: str,
) -> str | None:
    patched = function_text
    for decl in ("f32 x_base;", "f32 y_base;", "f32 row_base;"):
        next_text = _ensure_draw_local_declaration(
            patched,
            decl,
            after_decl="f32 base;",
        )
        if next_text is None:
            return None
        patched = next_text
    first = _replace_first_pattern(
        patched,
        (
            r"(?P<indent>[ \t]*)jobj\s*=\s*data\s*->\s*jobjs\s*\[\s*11\s*\]\s*;\s*\n"
            r"(?P=indent)base\s*=\s*HSD_JObjGetTranslationX\(jobj\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}jobj = data->jobjs[11];\n"
            f"{match.group('indent')}x_base = HSD_JObjGetTranslationX(jobj);\n"
            f"{match.group('indent')}base = x_base;"
        ),
    )
    if first is None:
        return None
    second = _replace_first_pattern(
        first,
        (
            r"(?P<indent>[ \t]*)jobj\s*=\s*data\s*->\s*jobjs\s*\[\s*7\s*\]\s*;\s*\n"
            r"(?P=indent)base\s*=\s*HSD_JObjGetTranslationX\(jobj\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}jobj = data->jobjs[7];\n"
            f"{match.group('indent')}y_base = HSD_JObjGetTranslationX(jobj);\n"
            f"{match.group('indent')}base = y_base;"
        ),
    )
    if second is None:
        return None
    third = _replace_first_pattern(
        second,
        (
            r"(?P<indent>[ \t]*)jobj\s*=\s*data\s*->\s*jobjs\s*\[\s*9\s*\]\s*;\s*\n"
            r"(?P=indent)base\s*=\s*HSD_JObjGetTranslationY\(jobj\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}jobj = data->jobjs[9];\n"
            f"{match.group('indent')}row_base = HSD_JObjGetTranslationY(jobj);\n"
            f"{match.group('indent')}base = row_base;"
        ),
    )
    return third if third is not None and third != function_text else None


