def _patch_draw_post_stack_loop_combined_callsite_owners(
    function_text: str,
) -> str | None:
    patched = _patch_draw_source_context_parent_jobj_local(function_text)
    if patched is None:
        patched = function_text
    next_text = _patch_draw_whole_function_animation_callarg_owner(patched)
    if next_text is not None:
        patched = next_text
    next_text = _replace_draw_loop_body_region(
        patched,
        lambda indent, body: _draw_source_context_loop_body(
            indent,
            body,
            object_name="digit_jobj",
            declare_digit_jobj=True,
            translate_locals=True,
            parent_name="parent",
        ),
    )
    if next_text is not None:
        patched = next_text
    return patched if patched != function_text else None


def _patch_draw_whole_function_joint_data_owner(
    function_text: str,
) -> str | None:
    if "void* digit_joint;" in function_text:
        return None
    joint_data_decl = _draw_joint_data_declaration_anchor(function_text)
    if joint_data_decl is None:
        return None
    patched = function_text
    after_decl = joint_data_decl
    for decl in (
        "void* digit_joint;",
        "void* digit_anim_joint;",
        "void* digit_matanim_joint;",
        "void* digit_shapeanim_joint;",
    ):
        next_text = _ensure_draw_local_declaration(
            patched,
            decl,
            after_decl=after_decl,
        )
        if next_text is None:
            return None
        patched = next_text
        after_decl = decl
    return _replace_draw_loop_body_region(
        patched,
        lambda indent, body: _draw_source_context_loop_body(
            indent,
            _draw_loop_body_with_joint_data_owners(body),
            object_name="jobj",
            declare_digit_jobj=False,
            translate_locals=False,
            parent_name=None,
        ),
    )


def _draw_joint_data_declaration_anchor(function_text: str) -> str | None:
    match = re.search(
        r"(?m)^[ \t]*(?P<decl>(?:void\s*\*\*|mnDiagram_ArchiveData\s*\*)"
        r"\s*joint_data\s*;)\s*$",
        function_text,
    )
    if match is None:
        return None
    return match.group("decl")


