def _patch_draw_source_context_combined_lower_hill_backtrack(
    function_text: str,
) -> str | None:
    patched = function_text
    changed = False
    for patcher in (
        _patch_draw_source_context_jobjs_array_local,
        _patch_draw_source_context_parent_jobj_local,
    ):
        next_text = patcher(patched)
        if next_text is not None and next_text != patched:
            patched = next_text
            changed = True
    next_text = _patch_draw_source_context_retained_split_to_legacy_y_offset(patched)
    if next_text is not None and next_text != patched:
        patched = next_text
        changed = True
    next_text = _replace_draw_loop_body_region(
        patched,
        lambda indent, body: _draw_source_context_loop_body(
            indent,
            body,
            object_name="jobj",
            declare_digit_jobj=False,
            translate_locals=True,
            parent_name="parent",
        ),
    )
    if next_text is not None and next_text != patched:
        patched = next_text
        changed = True
    return patched if changed else None


def _patch_draw_source_context_retained_split_to_legacy_y_offset(
    function_text: str,
) -> str | None:
    patched = _ensure_draw_local_declaration(
        function_text,
        "f32 y_offset;",
        after_decl="f32 col_offset;",
    )
    if patched is None:
        return None
    return _patch_draw_alt_offset_region_retained_split(
        patched,
        lambda match: (
            f"{match.group('indent')}y_offset = HSD_JObjGetTranslationY(jobj2);\n"
            f"{match.group('indent')}y_offset -= base;\n"
            f"{match.group('gap')}"
            f"{match.group('indent')}col_offset = y_spacing * (f32) col;\n"
            f"{match.group('indent')}row_offset = y_offset * (f32) row;"
        ),
    )


def _patch_draw_post_all_known_digit_bound_owner(
    function_text: str,
) -> str | None:
    if "int digit_bound;" in function_text:
        return None
    patched = _ensure_draw_local_declaration(
        function_text,
        "int digit_bound;",
        after_decl="int digit_count;",
    )
    if patched is None:
        return None
    patched = _replace_first_pattern(
        patched,
        r"(?P<indent>[ \t]*)digit_count\s*=\s*mn_GetDigitCount\s*\((?P<arg>.*?)\)\s*;\s*\n",
        lambda match: (
            f"{match.group('indent')}digit_count = mn_GetDigitCount({match.group('arg')});\n"
            f"{match.group('indent')}digit_bound = digit_count;\n"
        ),
    )
    if patched is None:
        return None
    replaced = re.sub(
        r"for\s*\(\s*i\s*=\s*0\s*;\s*i\s*<\s*digit_count\s*;\s*i\+\+\s*\)",
        "for (i = 0; i < digit_bound; i++)",
        patched,
        count=1,
    )
    return replaced if replaced != function_text else None


def _patch_draw_post_all_known_joint_table_alias(
    function_text: str,
) -> str | None:
    if "digit_joint_data;" in function_text:
        return None
    joint_decl = _draw_joint_data_declaration_anchor(function_text)
    if joint_decl is None:
        return None
    alias_decl = joint_decl.replace("joint_data", "digit_joint_data", 1)
    if alias_decl == joint_decl:
        return None
    patched = _ensure_draw_local_declaration(
        function_text,
        alias_decl,
        after_decl=joint_decl,
    )
    if patched is None:
        return None
    patched = _replace_first_pattern(
        patched,
        r"(?P<indent>[ \t]*)joint_data\s*=\s*(?P<expr>[^;]+?)\s*;\s*\n",
        lambda match: (
            f"{match.group('indent')}joint_data = {match.group('expr')};\n"
            f"{match.group('indent')}digit_joint_data = joint_data;\n"
        ),
    )
    if patched is None:
        return None
    return _replace_draw_loop_body_region(
        patched,
        lambda indent, body: _draw_source_context_loop_body(
            indent,
            body.replace("joint_data", "digit_joint_data"),
            object_name="jobj",
            declare_digit_jobj=False,
            translate_locals=False,
            parent_name=None,
        ),
    )


