def _patch_draw_product_translate_col_product_before_row_delta_y_offset(
    function_text: str,
) -> str | None:
    if "f32 y_offset_owner;" in function_text:
        return None
    patched = function_text
    if "f32 y_offset;" not in patched:
        patched = _ensure_draw_local_declaration(
            patched,
            "f32 y_offset;",
            after_decl="f32 row_offset;",
        )
        if patched is None:
            return None
        patched = re.sub(
            r"(?P<indent>[ \t]*)row_offset\s*=\s*HSD_JObjGetTranslationY\s*\(\s*jobj2\s*\)\s*-\s*base\s*;",
            r"\g<indent>y_offset = HSD_JObjGetTranslationY(jobj2) - base;",
            patched,
            count=1,
        )
    patched = _ensure_draw_local_declaration(
        patched,
        "f32 y_offset_owner;",
        after_decl="f32 y_offset;",
    )
    if patched is None:
        patched = _ensure_draw_local_declaration(
            function_text,
            "f32 y_offset_owner;",
            after_decl="f32 row_offset;",
        )
    if patched is None:
        return None
    patched = _ensure_draw_local_declaration(
        patched,
        "f32 col_product_owner;",
        after_decl="f32 col_offset;",
    )
    if patched is None:
        return None
    replaced = _replace_offset_product_block(
        patched,
        (
            "    col_product_owner = (f32) col;\n"
            "    col_product_owner *= y_spacing;\n"
            "    col_offset = col_product_owner;\n"
            "    y_offset_owner = y_offset;\n"
            "    row_offset = y_offset_owner * (f32) row;"
        ),
        (
            "    col_product_owner = (f32) col;\n"
            "    col_product_owner *= y_spacing;\n"
            "    col_offset = col_product_owner;\n"
            "    y_offset_owner = y_offset;\n"
            "    row_offset = y_offset_owner * (f32) row;"
        ),
    )
    return replaced if replaced != function_text else None


