def _patch_draw_alt_digit_inline(function_text: str) -> str | None:
    return _replace_first_pattern(
        function_text,
        (
            r"(?P<indent>[ \t]*)base\s*=\s*\(f32\)\s*digit\s*;\s*\n"
            r"(?P=indent)HSD_JObjReqAnimAll\(\s*jobj\s*,\s*base\s*\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}HSD_JObjReqAnimAll(jobj, (f32) digit);"
        ),
    )


def _patch_draw_alt_digit_copy(function_text: str) -> str | None:
    return _replace_first_pattern(
        function_text,
        (
            r"(?P<indent>[ \t]*)base\s*=\s*\(f32\)\s*digit\s*;\s*\n"
            r"(?P=indent)HSD_JObjReqAnimAll\(\s*jobj\s*,\s*base\s*\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}base = (f32) digit;\n"
            f"{match.group('indent')}{{\n"
            f"{match.group('indent')}    f32 post_alt_digit_arg;\n"
            f"{match.group('indent')}    post_alt_digit_arg = base;\n"
            f"{match.group('indent')}    HSD_JObjReqAnimAll(jobj, post_alt_digit_arg);\n"
            f"{match.group('indent')}}}"
        ),
    )


def _patch_draw_alt_digit_fsubs_temp(function_text: str) -> str | None:
    return _replace_first_pattern(
        function_text,
        (
            r"(?P<indent>[ \t]*)base\s*=\s*\(f32\)\s*digit\s*;\s*\n"
            r"(?P=indent)HSD_JObjReqAnimAll\(\s*jobj\s*,\s*base\s*\)\s*;"
        ),
        lambda match: (
            f"{match.group('indent')}{{\n"
            f"{match.group('indent')}    f32 post_alt_digit_arg;\n"
            f"{match.group('indent')}    post_alt_digit_arg = (f32) digit - 0.0f;\n"
            f"{match.group('indent')}    HSD_JObjReqAnimAll(jobj, post_alt_digit_arg);\n"
            f"{match.group('indent')}}}"
        ),
    )


def _patch_draw_alt_offset_region(
    function_text: str,
    legacy_replacement: Any,
    split_replacement: Any | None = None,
) -> str | None:
    legacy = _patch_draw_alt_offset_region_legacy(
        function_text,
        legacy_replacement,
    )
    if legacy is not None:
        return legacy
    if split_replacement is None:
        return None
    return _patch_draw_alt_offset_region_retained_split(
        function_text,
        split_replacement,
    )


def _patch_draw_alt_offset_region_legacy(
    function_text: str,
    replacement: Any,
) -> str | None:
    return _replace_first_pattern(
        function_text,
        (
            r"(?P<indent>[ \t]*)y_offset\s*=\s*HSD_JObjGetTranslationY\(jobj2\)\s*;\s*\n"
            r"(?P=indent)y_offset\s*-=\s*base\s*;\s*\n"
            r"(?P<gap>(?:[ \t]*\n|[ \t]*digit_count\s*=\s*mn_GetDigitCount\([^;]+\);\s*\n)*)"
            r"(?P=indent)col_offset\s*=\s*y_spacing\s*\*\s*\(f32\)\s*col\s*;\s*\n"
            r"(?P=indent)row_offset\s*=\s*y_offset\s*\*\s*\(f32\)\s*row\s*;"
        ),
        replacement,
    )


def _patch_draw_alt_offset_region_retained_split(
    function_text: str,
    replacement: Any,
) -> str | None:
    return _replace_first_pattern(
        function_text,
        (
            r"(?P<indent>[ \t]*)row_offset\s*=\s*HSD_JObjGetTranslationY\(jobj2\)\s*-\s*base\s*;\s*\n"
            r"(?P<gap>(?:[ \t]*\n|(?P=indent)digit_count\s*=\s*mn_GetDigitCount\([^;]+\);\s*\n)*)"
            r"(?P=indent)col_offset\s*=\s*\(f32\)\s*col\s*;\s*\n"
            r"(?P=indent)col_offset\s*\*=\s*y_spacing\s*;\s*\n"
            r"(?P=indent)rowf\s*=\s*\(f32\)\s*row\s*;\s*\n"
            r"(?P=indent)row_offset\s*\*=\s*rowf\s*;"
        ),
        replacement,
    )


def _replace_first_pattern(
    text: str,
    pattern: str,
    replacement_for_match: Any,
) -> str | None:
    match = re.search(pattern, text, re.MULTILINE)
    if match is None:
        return None
    replacement = replacement_for_match(match)
    return text[: match.start()] + replacement + text[match.end() :]


def _validation_metadata(
    context: MetaCeilingContext,
    options: Mapping[str, Any],
) -> dict[str, Any]:
    metadata: dict[str, Any] = {
        "function": context.function,
        "source_function": context.source_function,
        "score_function": context.source_function or context.function,
        "source_file": context.source_file,
        "cflags_from": str(options.get("cflags_from") or context.source_file),
        "expression_source": str(
            options.get("expression_source") or context.source_file
        ),
        "expression_baseline": (
            str(options.get("expression_baseline"))
            if options.get("expression_baseline") is not None
            else None
        ),
        "target": str(options.get("target"))
        if options.get("target") is not None
        else None,
        "requires_target_score_validation": True,
        "requires_structural_guard": bool(options.get("checkdiff_guard", True)),
        "register_class": context.register_class,
        "target_assignments": context.target_assignments,
        "final_force_phys": dict(context.force_phys),
    }
    metadata["score_source_command_hint"] = _score_command_hint(metadata)
    return metadata


def _score_command_hint(metadata: Mapping[str, Any]) -> str:
    target = metadata.get("target") or "<target.json>"
    parts = [
        "melee-agent",
        "debug",
        "target",
        "score-source",
        "{candidate_path}",
        "--function",
        str(
            metadata.get("score_function") or metadata.get("function") or SORT_FUNCTION
        ),
        "--target",
        str(target),
        "--cflags-from",
        str(metadata.get("cflags_from") or SORT_SOURCE_FILE),
        "--expression-source",
        str(metadata.get("expression_source") or SORT_SOURCE_FILE),
        "--expression-reg-class",
        str(metadata.get("register_class") or "gpr"),
        "--retain-pcdump",
    ]
    expression_baseline = metadata.get("expression_baseline")
    if expression_baseline is not None:
        parts.extend(["--expression-baseline", str(expression_baseline)])
    if metadata.get("requires_full_unit_source") is True:
        parts.append("--full-unit-source")
    if metadata.get("requires_structural_guard", True):
        parts.append("--checkdiff-guard")
    else:
        parts.append("--no-checkdiff-guard")
    parts.append("--json")
    return " ".join(
        shlex.quote(part) if part != "{candidate_path}" else part for part in parts
    )


def _candidate_score_command(candidate: Mapping[str, Any]) -> str:
    metadata = candidate.get("validation_metadata")
    if not isinstance(metadata, Mapping):
        return ""
    hint = metadata.get("score_source_command_hint")
    return str(hint) if isinstance(hint, str) else ""


def _source_hunks(
    base_source: str,
    candidate_source: str,
    variant_id: str,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for hunk in diff_line_hunks(
        base_source,
        candidate_source,
        hunk_prefix=f"post-meta-{variant_id}-h",
    ):
        row = hunk.to_dict()
        base_range = row.get("base_range")
        candidate_range = row.get("candidate_range")
        if isinstance(base_range, Mapping):
            row["old_start"] = base_range.get("start")
            row["old_end"] = base_range.get("end")
        if isinstance(candidate_range, Mapping):
            row["new_start"] = candidate_range.get("start")
            row["new_end"] = candidate_range.get("end")
        row["old_lines"] = list(row.get("removed") or [])
        row["new_lines"] = list(row.get("added") or [])
        rows.append(row)
    return rows


def materialize_sort_semantic_recombine_candidates(
    source_text: str,
    semantic_recombine: Mapping[str, Any] | None,
    context: MetaCeilingContext,
    *,
    validation_options: Mapping[str, Any] | None = None,
    max_candidates: int | None = None,
) -> list[dict[str, Any]]:
    """Turn estimated Sort semantic recombine rows into scoreable source probes."""
    payload = (
        {"semantic_recombine": semantic_recombine}
        if semantic_recombine is not None
        else {}
    )
    return materialize_semantic_recombine_source_candidates(
        payload,
        source_text,
        context,
        validation_options=validation_options,
        max_candidates=max_candidates,
        include_source=True,
    )["candidates"]


def materialize_semantic_recombine_source_candidates(
    payload: Mapping[str, Any],
    source_text: str,
    context: MetaCeilingContext,
    *,
    validation_options: Mapping[str, Any] | None = None,
    max_candidates: int | None = None,
    include_source: bool = False,
) -> dict[str, Any]:
    """Materialize estimated Sort semantic recombine proposals with diagnostics."""
    semantic_recombine = _semantic_recombine_payload(payload)
    if (
        context.function != SORT_FUNCTION
        or not isinstance(semantic_recombine, Mapping)
    ):
        return {
            "status": "not-applicable",
            "attempted_candidate_count": 0,
            "candidates": [],
            "failures": [],
        }
    context = resolve_source_function_context(source_text, context, require=False)
    metadata_base = _validation_metadata(context, validation_options or {})
    materialized: list[dict[str, Any]] = []
    failures: list[dict[str, Any]] = []
    seen_sources: set[str] = set()
    seen_hunks: set[tuple[Any, ...]] = set()
    attempted = 0
    for candidate in semantic_recombine.get("ranked_candidates") or []:
        if not isinstance(candidate, Mapping):
            continue
        if candidate.get("dimension_id") != SORT_SEMANTIC_RECOMBINE_DIMENSION:
            continue
        blockers = set(_string_items(candidate.get("blockers"))) | set(
            _string_items(candidate.get("terminal_blockers"))
        )
        if blockers - {"no-scored-recombine-evidence"}:
            continue
        attempted += 1
        candidate_id = _non_empty_str(candidate.get("candidate_id"))
        if candidate_id is None:
            failures.append({"reason": "candidate-id-missing"})
            continue
        source_hunks = [
            dict(row)
            for row in candidate.get("source_hunks") or []
            if isinstance(row, Mapping)
        ]
        if not source_hunks:
            failures.append(
                {
                    "candidate_id": candidate_id,
                    "reason": "source-hunks-missing",
                }
            )
            continue
        recombined_source = _apply_source_hunks_to_source(source_text, source_hunks)
        if recombined_source is None:
            failures.append(
                {
                    "candidate_id": candidate_id,
                    "reason": "hunk-apply-failed",
                }
            )
            continue
        if recombined_source == source_text:
            failures.append(
                {
                    "candidate_id": candidate_id,
                    "reason": "hunk-apply-no-change",
                }
            )
            continue
        source_hash = hashlib.sha256(recombined_source.encode("utf-8")).hexdigest()
        hunk_signature = _normalized_hunk_signature(source_hunks)
        if source_hash in seen_sources or hunk_signature in seen_hunks:
            failures.append(
                {
                    "candidate_id": candidate_id,
                    "reason": "duplicate-recombined-source",
                }
            )
            continue
        seen_sources.add(source_hash)
        seen_hunks.add(hunk_signature)
        source_components = [
            dict(row)
            for row in candidate.get("source_components") or []
            if isinstance(row, Mapping)
        ]
        metadata = dict(metadata_base)
        metadata.update(
            {
                "candidate_id": candidate_id,
                "dimension_id": SORT_SEMANTIC_RECOMBINE_DIMENSION,
                "equivalence_class": SORT_SEMANTIC_RECOMBINE_DIMENSION,
                "semantic_recombine": True,
                "source_model_layer_dimension_id": (
                    SORT_SEMANTIC_RECOMBINE_DIMENSION
                ),
                "source_hunks": [dict(row) for row in source_hunks],
                "source_components": [dict(row) for row in source_components],
                "parents": list(candidate.get("parents") or []),
                "target_score_estimate": dict(candidate.get("target_score_estimate") or {}),
                "requires_full_unit_source": True,
                "requires_target_score_validation": True,
                "requires_structural_guard": True,
                "required_preserved_assignments": _required_preserved_assignments(
                    context
                ),
            }
        )
        source_route = candidate.get("source_route")
        if isinstance(source_route, Mapping):
            metadata["source_route"] = dict(source_route)
        metadata["score_source_command_hint"] = _score_command_hint(metadata)
        materialized.append(
            SourceFamilyCandidate(
                candidate_id=candidate_id,
                family=str(_profile_value(context.function, "family")),
                dimension_id=SORT_SEMANTIC_RECOMBINE_DIMENSION,
                equivalence_class=SORT_SEMANTIC_RECOMBINE_DIMENSION,
                variant_id=candidate_id.removeprefix("post-meta-"),
                strategy="semantic-sort-dual-target-recombine",
                rationale=(
                    "Combine non-overlapping one-hit Sort semantic source hunks and "
                    "score the retained source as a real dual-target candidate."
                ),
                expected_effect=(
                    "Validate whether the combined semantic Sort algorithm shape "
                    "preserves IG34->r27 and IG44->r25 together."
                ),
                source_function=context.source_function,
                source_text=recombined_source,
                source_hunks=source_hunks,
                source_components=source_components,
                target_assignments=list(context.target_assignments),
                source_spans=[],
                validation_metadata=metadata,
                origin="sort-semantic-recombine",
                origin_family=SORT_SEMANTIC_RECOMBINE_DIMENSION,
                origin_probe_id=candidate_id,
            ).to_dict(include_source=include_source)
        )
        if max_candidates is not None and len(materialized) >= max_candidates:
            break
    return {
        "status": "generated" if materialized else "blocked",
        "attempted_candidate_count": attempted,
        "candidate_count": len(materialized),
        "candidates": materialized,
        "failures": failures,
    }


def _semantic_recombine_payload(payload: Mapping[str, Any]) -> Mapping[str, Any] | None:
    semantic_recombine = payload.get("semantic_recombine")
    if isinstance(semantic_recombine, Mapping):
        return semantic_recombine
    if payload.get("dimension_id") == SORT_SEMANTIC_RECOMBINE_DIMENSION:
        return payload
    return None


def _required_preserved_assignments(context: MetaCeilingContext) -> list[str]:
    return [f"IG{virtual}->r{phys}" for virtual, phys in context.force_phys.items()]


def _apply_source_hunks_to_source(
    source_text: str,
    source_hunks: Sequence[Mapping[str, Any]],
) -> str | None:
    try:
        hunks = tuple(_source_hunk_from_mapping(hunk) for hunk in source_hunks)
        return apply_hunks_to_text(source_text, hunks)
    except (TypeError, ValueError):
        return None


def _source_hunk_from_mapping(hunk: Mapping[str, Any]) -> SourceHunk:
    base_start, base_end = _source_hunk_exact_range(
        hunk,
        start_key="base_start",
        end_key="base_end",
        range_key="base_range",
        fallback_start_key="old_start",
        fallback_end_key="old_end",
    )
    candidate_range = _source_hunk_exact_range(
        hunk,
        start_key="candidate_start",
        end_key="candidate_end",
        range_key="candidate_range",
        fallback_start_key="new_start",
        fallback_end_key="new_end",
        fallback_default=(base_start, base_start + len(hunk.get("added") or hunk.get("new_lines") or [])),
    )
    hunk_id = _non_empty_str(hunk.get("hunk_id")) or "semantic-recombine-hunk"
    kind = _non_empty_str(hunk.get("kind")) or "statement"
    risk = _non_empty_str(hunk.get("risk")) or "low"
    parent_hunk_id = _non_empty_str(hunk.get("parent_hunk_id"))
    removed = tuple(str(line) for line in (hunk.get("removed") or hunk.get("old_lines") or []))
    added = tuple(str(line) for line in (hunk.get("added") or hunk.get("new_lines") or []))
    return SourceHunk(
        hunk_id=hunk_id,
        base_start=base_start,
        base_end=base_end,
        candidate_start=candidate_range[0],
        candidate_end=candidate_range[1],
        removed=removed,
        added=added,
        kind=kind,
        risk=risk,
        parent_hunk_id=parent_hunk_id,
        blockers=tuple(_string_items(hunk.get("blockers"))),
    )


def _source_hunk_exact_range(
    hunk: Mapping[str, Any],
    *,
    start_key: str,
    end_key: str,
    range_key: str,
    fallback_start_key: str,
    fallback_end_key: str,
    fallback_default: tuple[int, int] | None = None,
) -> tuple[int, int]:
    start = _int_or_none(hunk.get(start_key))
    end = _int_or_none(hunk.get(end_key))
    if start is not None and end is not None:
        if start < 0 or end < start:
            raise ValueError("invalid source hunk range")
        return (start, end)
    range_value = hunk.get(range_key)
    if isinstance(range_value, Mapping):
        ranged = _one_based_source_hunk_range(range_value)
        if ranged is not None:
            return ranged
    fallback_start = _int_or_none(hunk.get(fallback_start_key))
    fallback_end = _int_or_none(hunk.get(fallback_end_key))
    if fallback_start is not None and fallback_end is not None:
        ranged = _one_based_source_hunk_range(
            {"start": fallback_start, "end": fallback_end}
        )
        if ranged is not None:
            return ranged
    if fallback_default is not None:
        return fallback_default
    raise ValueError("source hunk range missing")


def _one_based_source_hunk_range(value: Mapping[str, Any]) -> tuple[int, int] | None:
    start = _int_or_none(value.get("start"))
    end = _int_or_none(value.get("end"))
    if start is None or end is None:
        return None
    base_start = max(start - 1, 0)
    if bool(value.get("empty")):
        return (base_start, base_start)
    base_end = max(end, base_start)
    if base_end < base_start:
        raise ValueError("invalid source hunk range")
    return (base_start, base_end)


def _normalized_hunk_signature(hunks: Sequence[Mapping[str, Any]]) -> tuple[Any, ...]:
    return tuple(
        (
            tuple(hunk.get("removed") or ()),
            tuple(hunk.get("added") or ()),
        )
        for hunk in hunks
    )


def _join_score_rows(
    candidates: Sequence[Mapping[str, Any]],
    score_payloads: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> dict[str, Any]:
    candidates_by_id = {
        str(candidate.get("candidate_id")): candidate
        for candidate in candidates
        if candidate.get("candidate_id") is not None
    }
    path_to_id = _candidate_path_index(candidates)
    rows_by_id: dict[str, list[dict[str, Any]]] = {}
    unjoined: list[dict[str, Any]] = []
    mismatches: list[dict[str, Any]] = []
    for index, payload in enumerate(score_payloads):
        indexed_payload = dict(payload)
        indexed_payload.setdefault("score_index", index)
        candidate_id, mismatch = _score_candidate_id(
            indexed_payload,
            candidates_by_id=candidates_by_id,
            path_to_id=path_to_id,
        )
        if mismatch is not None:
            mismatches.append({"score_index": index, **mismatch})
        if candidate_id is None:
            unjoined.append(
                {
                    "score_index": index,
                    "reason": "candidate-id-not-resolved",
                    "candidate_id": indexed_payload.get("candidate_id"),
                    "source_file": indexed_payload.get("source_file"),
                    "source_retained": indexed_payload.get("source_retained"),
                    "pcdump_path": indexed_payload.get("pcdump_path"),
                }
            )
            continue
        candidate = candidates_by_id[candidate_id]
        rows_by_id.setdefault(candidate_id, []).append(
            _score_row(candidate, indexed_payload, context)
        )

    duplicate_rows = [
        {
            "candidate_id": candidate_id,
            "score_count": len(rows),
            "kept_score_index": _best_duplicate_row_index(rows),
            "score_indices": [row["score_index"] for row in rows],
        }
        for candidate_id, rows in rows_by_id.items()
        if len(rows) > 1
    ]
    chosen_rows = [
        _best_duplicate_row(rows)
        for _, rows in sorted(rows_by_id.items(), key=lambda item: item[0])
    ]
    missing = [
        candidate_id
        for candidate_id in sorted(candidates_by_id)
        if candidate_id not in rows_by_id
    ]
    return {
        "score_rows": chosen_rows,
        "duplicate_score_rows": duplicate_rows,
        "unjoined_score_rows": unjoined,
        "metadata_mismatches": mismatches,
        "missing_score_candidate_ids": missing,
    }


def _score_candidate_id(
    payload: Mapping[str, Any],
    *,
    candidates_by_id: Mapping[str, Mapping[str, Any]],
    path_to_id: Mapping[str, str],
) -> tuple[str | None, dict[str, Any] | None]:
    explicit = _non_empty_str(payload.get("candidate_id"))
    metadata = payload.get("validation_metadata")
    metadata_id = (
        _non_empty_str(metadata.get("candidate_id"))
        if isinstance(metadata, Mapping)
        else None
    )
    path_id = _score_path_candidate_id(payload, path_to_id)
    candidate_id = explicit or metadata_id or path_id
    if candidate_id is not None and candidate_id not in candidates_by_id:
        return None, {
            "reason": "unknown-candidate-id",
            "candidate_id": candidate_id,
        }
    mismatch = None
    ids = {item for item in (explicit, metadata_id, path_id) if item is not None}
    if len(ids) > 1:
        mismatch = {
            "reason": "candidate-metadata-disagrees",
            "candidate_ids": sorted(ids),
        }
    return candidate_id, mismatch


def _score_path_candidate_id(
    payload: Mapping[str, Any],
    path_to_id: Mapping[str, str],
) -> str | None:
    for key in ("source_file", "source_retained", "candidate_path", "path"):
        value = _non_empty_str(payload.get(key))
        if value is None:
            continue
        candidate_id = path_to_id.get(_normalize_path_key(value))
        if candidate_id is not None:
            return candidate_id
    pcdump_path = _non_empty_str(payload.get("pcdump_path"))
    if pcdump_path is None:
        return None
    pcdump = Path(pcdump_path)
    stems = [pcdump.stem]
    if pcdump.name.endswith(".pcdump.txt"):
        stems.append(pcdump.name[: -len(".pcdump.txt")])
    matches = [
        candidate_id
        for path_key, candidate_id in path_to_id.items()
        if Path(path_key).stem in stems
    ]
    unique = _dedupe_strings(matches)
    return unique[0] if len(unique) == 1 else None


def _candidate_requires_expression_score_validation(
    candidate: Mapping[str, Any],
) -> bool:
    metadata = candidate.get("validation_metadata")
    return (
        isinstance(metadata, Mapping)
        and metadata.get("requires_expression_score_validation") is True
    )


def _candidate_requires_full_unit_source(candidate: Mapping[str, Any]) -> bool:
    if candidate.get("requires_full_unit_source") is True:
        return True
    metadata = candidate.get("validation_metadata")
    return (
        isinstance(metadata, Mapping)
        and metadata.get("requires_full_unit_source") is True
    )


def _candidate_score_function(
    candidate: Mapping[str, Any],
    context: MetaCeilingContext,
) -> str:
    metadata = candidate.get("validation_metadata")
    if isinstance(metadata, Mapping):
        value = _non_empty_str(metadata.get("score_function"))
        if value is not None:
            return value
    return context.source_function or context.function


def _candidate_path_index(candidates: Sequence[Mapping[str, Any]]) -> dict[str, str]:
    out: dict[str, str] = {}
    for candidate in candidates:
        candidate_id = _non_empty_str(candidate.get("candidate_id"))
        if candidate_id is None:
            continue
        for key in ("candidate_path", "source_retained", "path"):
            value = _non_empty_str(candidate.get(key))
            if value is not None:
                out[_normalize_path_key(value)] = candidate_id
    return out


def _normalize_path_key(value: str) -> str:
    return str(Path(value).expanduser())


def _score_row(
    candidate: Mapping[str, Any],
    payload: Mapping[str, Any],
    context: MetaCeilingContext,
) -> dict[str, Any]:
    target_score = payload.get("target_score")
    target_matched, target_targeted, target_distance = _target_score_counts(
        target_score if isinstance(target_score, Mapping) else None,
        context.force_phys,
    )
    expression_score = payload.get("expression_score")
    expression_matched, expression_targeted, expression_distance = _target_score_counts(
        expression_score if isinstance(expression_score, Mapping) else None,
        context.force_phys,
    )
    structural_guard = payload.get("structural_guard")
    structural_accepted = _structural_guard_accepted(
        structural_guard if isinstance(structural_guard, Mapping) else None
    )
    score_error = _score_error(payload)
    requires_full_unit_source = _candidate_requires_full_unit_source(candidate)
    validation_metadata = dict(candidate.get("validation_metadata") or {})
    row = {
        "score_index": _int_or_none(payload.get("score_index")) or 0,
        "candidate_id": candidate.get("candidate_id"),
        "dimension_id": candidate.get("dimension_id"),
        "equivalence_class": candidate.get("equivalence_class"),
        "variant_id": candidate.get("variant_id"),
        "source_retained": (
            payload.get("source_retained")
            or payload.get("source_file")
            or candidate.get("source_retained")
            or candidate.get("candidate_path")
        ),
        "pcdump_path": payload.get("pcdump_path"),
        "target_score": dict(target_score)
        if isinstance(target_score, Mapping)
        else None,
        "target_matched": target_matched,
        "target_targeted": target_targeted,
        "target_virtual_distance": target_distance,
        "expression_score": (
            dict(expression_score) if isinstance(expression_score, Mapping) else None
        ),
        "expression_matched": expression_matched,
        "expression_targeted": expression_targeted,
        "expression_virtual_distance": expression_distance,
        "structural_guard": (
            dict(structural_guard) if isinstance(structural_guard, Mapping) else None
        ),
        "structural_guard_accepted": structural_accepted,
        "score_error": score_error,
        "normalized_diff_lines": _normalized_diff_lines(payload),
        "match_percent": _match_percent(payload),
        "source_hunks": list(candidate.get("source_hunks") or []),
        "source_components": list(candidate.get("source_components") or []),
        "validation_metadata": validation_metadata,
        "score_command": (
            payload.get("score_command")
            or candidate.get("score_command")
            or _candidate_score_command(candidate)
        ),
        "source_validation": dict(payload.get("source_validation"))
        if isinstance(payload.get("source_validation"), Mapping)
        else dict(candidate.get("source_validation"))
        if isinstance(candidate.get("source_validation"), Mapping)
        else None,
        "source_valid": (
            payload.get("source_valid")
            if payload.get("source_valid") is not None
            else candidate.get("source_valid")
        ),
        "adapted_from_transform_corpus": bool(
            candidate.get("adapted_from_transform_corpus")
        ),
        "adapted_from_expression_interferer": bool(
            candidate.get("adapted_from_expression_interferer")
        ),
        "requires_full_unit_source": requires_full_unit_source,
        "full_unit_source": bool(payload.get("full_unit_source")),
        "requires_expression_score_validation": bool(
            candidate.get("requires_expression_score_validation")
            or _candidate_requires_expression_score_validation(candidate)
        ),
        "origin_family": candidate.get("origin_family"),
        "origin_mutator": candidate.get("origin_mutator"),
        "origin_probe_id": candidate.get("origin_probe_id"),
        "blockers": _normalized_blocker_entries(
            payload.get("blockers") or candidate.get("blockers")
        ),
    }
    for key in (
        "score_error_kind",
        "stdout_tail",
        "stderr_tail",
        "raw_stdout",
        "raw_stderr",
    ):
        if payload.get(key) is not None:
            row[key] = payload.get(key)
    if payload.get("source_file") is not None:
        row["score_source_file"] = payload["source_file"]
    for key in (
        "recovery_goal",
        "recovery_rank",
        "seed_candidate_id",
        "seed_source_retained",
        "seed_pcdump_path",
        "seed_source_hunks",
        "seed_target_score",
        "seed_expression_score",
        "seed_structural_guard",
        "seed_one_hit_targets",
        "seed_stack_frame_facts",
        "seed_ranked_recovery_probes",
        "seed_source_components",
        "ranked_seed_candidates",
        "post_cross_tu_broader_natural_rewrite",
    ):
        if validation_metadata.get(key) is not None:
            row[key] = validation_metadata.get(key)
    if payload.get("score_returncode") is not None:
        row["score_returncode"] = payload["score_returncode"]
    if payload.get("score_stderr") is not None:
        row["score_stderr"] = payload["score_stderr"]
    if payload.get("raw_stdout") is not None:
        row["raw_stdout"] = payload["raw_stdout"]
    return row


def _best_duplicate_row(rows: Sequence[dict[str, Any]]) -> dict[str, Any]:
    return sorted(rows, key=_duplicate_score_sort_key)[0]


def _best_duplicate_row_index(rows: Sequence[dict[str, Any]]) -> int | None:
    return _best_duplicate_row(rows).get("score_index")


def _duplicate_score_sort_key(row: Mapping[str, Any]) -> tuple[Any, ...]:
    return (
        1 if row.get("score_error") else 0,
        0 if row.get("structural_guard_accepted") else 1,
        -int(row.get("target_matched") or 0),
        -int(row.get("expression_matched") or 0),
        int(row.get("target_virtual_distance") or 9999),
        int(row.get("expression_virtual_distance") or 9999),
        int(row.get("normalized_diff_lines") or 999999),
        -float(row.get("match_percent") or 0.0),
        str(row.get("candidate_id") or ""),
    )


def _rank_score_rows(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    return [
        dict(row)
        for row in sorted(
            rows,
            key=lambda row: (
                -int(row.get("target_matched") or 0),
                -int(row.get("expression_matched") or 0),
                int(row.get("target_virtual_distance") or 9999),
                int(row.get("expression_virtual_distance") or 9999),
                0 if row.get("structural_guard_accepted") else 1,
                int(row.get("normalized_diff_lines") or 999999),
                -float(row.get("match_percent") or 0.0),
                len(row.get("source_hunks") or []),
                str(row.get("candidate_id") or ""),
            ),
        )
    ]


def _target_hit_virtuals(
    row: Mapping[str, Any],
    force_phys: Mapping[str, int],
) -> set[str]:
    target_score = row.get("target_score")
    virtuals = (
        target_score.get("virtuals") if isinstance(target_score, Mapping) else None
    )
    if not isinstance(virtuals, Mapping):
        return set()
    hits: set[str] = set()
    for virtual, expected in force_phys.items():
        item = virtuals.get(str(virtual))
        if not isinstance(item, Mapping):
            continue
        actual_expected = _register_num(item.get("expected"))
        actual = _register_num(item.get("actual"))
        if actual_expected in (None, expected) and (
            bool(item.get("matched")) or actual == expected
        ):
            hits.add(str(virtual))
    return hits


def _sort_semantic_recombine_seed_rows(
    rows: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> dict[str, list[dict[str, Any]]]:
    if context.function != SORT_FUNCTION:
        return {}
    eligible_dimensions = set(SORT_PROTECTED_ONE_HIT_RECOMBINE_DIMENSIONS)
    out: dict[str, list[dict[str, Any]]] = {
        str(virtual): [] for virtual in context.force_phys
    }
    for row in rows:
        if row.get("dimension_id") not in eligible_dimensions:
            continue
        hits = _target_hit_virtuals(row, context.force_phys)
        if len(hits) != 1:
            continue
        hit = next(iter(hits))
        out.setdefault(hit, []).append(dict(row))
    return out


def _sort_semantic_recombine_pair_blockers(
    left: Mapping[str, Any],
    right: Mapping[str, Any],
    context: MetaCeilingContext,
) -> list[str]:
    blockers: list[str] = []
    left_hunks = [dict(row) for row in left.get("source_hunks") or []]
    right_hunks = [dict(row) for row in right.get("source_hunks") or []]
    if not left_hunks or not right_hunks:
        blockers.append("missing-source-hunks")
    elif _source_hunk_sets_overlap(left_hunks, right_hunks):
        blockers.append("recombine-overlapping-source-hunks")

    shared_components = _source_component_ids(left) & _source_component_ids(right)
    if shared_components and left.get("candidate_id") != right.get("candidate_id"):
        blockers.extend(
            f"semantic-component-conflict:{component_id}"
            for component_id in sorted(shared_components)
        )

    covered = _target_hit_virtuals(left, context.force_phys) | _target_hit_virtuals(
        right,
        context.force_phys,
    )
    if set(context.force_phys) - covered:
        blockers.append("protected-targets-not-jointly-preserved")
    return _dedupe_strings(blockers)


def _sort_semantic_recombine_candidate(
    left: Mapping[str, Any],
    right: Mapping[str, Any],
    context: MetaCeilingContext,
) -> dict[str, Any]:
    blockers = _sort_semantic_recombine_pair_blockers(left, right, context)
    source_hunks = [
        *[dict(row) for row in left.get("source_hunks") or []],
        *[dict(row) for row in right.get("source_hunks") or []],
    ]
    source_components = _dedupe_dicts(
        [
            *[dict(row) for row in left.get("source_components") or []],
            *[dict(row) for row in right.get("source_components") or []],
        ]
    )
    parent_ids = [str(left.get("candidate_id")), str(right.get("candidate_id"))]
    target_score = _combined_recombine_target_score(left, right, context)
    digest = hashlib.sha1(
        json.dumps(
            {
                "parents": parent_ids,
                "source_hunks": source_hunks,
                "source_components": source_components,
            },
            sort_keys=True,
            default=str,
        ).encode("utf-8")
    ).hexdigest()[:12]
    actionable = not blockers
    source_route = None
    if actionable:
        source_route = {
            "kind": SORT_SEMANTIC_RECOMBINE_DIMENSION,
            "parents": parent_ids,
            "source_hunks": source_hunks,
            "source_components": source_components,
        }
    normalized_diff_lines = sum(
        _int_or_none(row.get("normalized_diff_lines")) or 0 for row in (left, right)
    )
    candidate = {
        "candidate_id": f"post-meta-sort-semantic-recombine-{digest}",
        "dimension_id": SORT_SEMANTIC_RECOMBINE_DIMENSION,
        "source": "source-model-semantic-recombine",
        "parents": parent_ids,
        "parent_details": [
            _sort_semantic_recombine_parent(left, context),
            _sort_semantic_recombine_parent(right, context),
        ],
        "target_score_estimate": target_score,
        "target_score": target_score,
        "target_matched": target_score["matched"],
        "target_targeted": target_score["targeted"],
        "target_virtual_distance": target_score["virtual_distance"],
        "expression_matched": 0,
        "expression_targeted": len(context.force_phys),
        "expression_virtual_distance": len(context.force_phys),
        "source_hunks": source_hunks,
        "source_components": source_components,
        "structural_guard": {
            "accepted": actionable,
            "estimated": True,
            "status": (
                "source-recombine-ready" if actionable else "source-recombine-blocked"
            ),
        },
        "structural_guard_accepted": actionable,
        "normalized_diff_lines": normalized_diff_lines,
        "frame_delta": 0,
        "blockers": blockers,
        "recommendation": "continue" if actionable else "blocked",
        "accepted": actionable,
    }
    if source_route is not None:
        candidate["source_route"] = source_route
    return candidate


def _sort_semantic_recombine_summary(
    score_rows: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> dict[str, Any] | None:
    if context.function != SORT_FUNCTION:
        return None
    eligible_dimensions = set(SORT_PROTECTED_ONE_HIT_RECOMBINE_DIMENSIONS)
    eligible_rows = [
        row for row in score_rows if row.get("dimension_id") in eligible_dimensions
    ]
    if not eligible_rows:
        return None
    seeds = _sort_semantic_recombine_seed_rows(score_rows, context)
    target_keys = [str(virtual) for virtual in context.force_phys]
    if len(target_keys) < 2:
        return None
    first, second = target_keys[:2]
    if not seeds.get(first) or not seeds.get(second):
        return {
            "kind": "sort-semantic-dual-target-recombine",
            "dimension_id": SORT_SEMANTIC_RECOMBINE_DIMENSION,
            "status": "terminal",
            "candidate_count": 0,
            "ranked_candidates": [],
            "terminal_blockers": [
                {
                    "reason": "semantic-recombine-no-complementary-one-hit-seeds",
                    "candidate_ids": [
                        str(row.get("candidate_id"))
                        for row in eligible_rows
                        if row.get("candidate_id")
                    ],
                }
            ],
            "target_hits_by_parent": {
                str(row.get("candidate_id")): sorted(
                    _target_hit_virtuals(row, context.force_phys)
                )
                for row in eligible_rows
                if row.get("candidate_id")
            },
            "terminal_reason": SORT_SEMANTIC_RECOMBINE_TERMINAL_REASON,
        }
    candidates = [
        _sort_semantic_recombine_candidate(left, right, context)
        for left in seeds[first]
        for right in seeds[second]
        if left.get("candidate_id") != right.get("candidate_id")
    ]
    if not candidates:
        return None
    ranked = _rank_sort_semantic_recombine_candidates(candidates)
    actionable = [row for row in ranked if not row.get("blockers")]
    status = "actionable" if actionable else "terminal"
    terminal_blockers = (
        [] if actionable else _sort_semantic_recombine_terminal_blockers(ranked)
    )
    summary = {
        "kind": "sort-semantic-dual-target-recombine",
        "dimension_id": SORT_SEMANTIC_RECOMBINE_DIMENSION,
        "status": status,
        "candidate_count": len(ranked),
        "ranked_candidates": ranked,
        "terminal_blockers": terminal_blockers,
        "target_hits_by_parent": {
            str(row.get("candidate_id")): sorted(
                _target_hit_virtuals(row, context.force_phys)
            )
            for rows in seeds.values()
            for row in rows
        },
        "terminal_reason": (
            SORT_SEMANTIC_RECOMBINE_TERMINAL_REASON if status == "terminal" else None
        ),
    }
    real_score_summary = _sort_semantic_recombine_score_source_summary(score_rows)
    if real_score_summary is not None:
        _apply_sort_recombine_real_score_authority(summary, [real_score_summary])
    return summary


def _sort_semantic_recombine_score_source_summary(
    score_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any] | None:
    candidates = [
        dict(row)
        for row in score_rows
        if isinstance(row, Mapping) and _score_source_semantic_recombine_candidate(row)
    ]
    if not candidates:
        return None
    return {
        "kind": "score-source",
        "status": "available",
        "ranked_candidates": _rank_sort_semantic_recombine_candidates(candidates),
        "candidate_count": len(candidates),
        "scored_count": len(candidates),
    }


def _rank_sort_semantic_recombine_candidates(
    rows: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    return [
        dict(row)
        for row in sorted(
            rows,
            key=lambda row: (
                0 if not row.get("blockers") else 1,
                -int(row.get("target_matched") or 0),
                0 if row.get("structural_guard_accepted") else 1,
                abs(int(row.get("frame_delta") or 0)),
                int(row.get("normalized_diff_lines") or 999999),
                len(row.get("source_hunks") or []),
                len(row.get("blockers") or []),
                str(row.get("candidate_id") or ""),
            ),
        )
    ]


def _sort_semantic_recombine_terminal_blockers(
    candidates: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    blockers: list[dict[str, Any]] = []
    for candidate in candidates:
        candidate_id = str(candidate.get("candidate_id"))
        for blocker in candidate.get("blockers") or []:
            reason = _sort_semantic_recombine_blocker_reason(str(blocker))
            row = {
                "reason": reason,
                "candidate_ids": [candidate_id],
                "blocker": str(blocker),
            }
            if str(blocker).startswith("semantic-component-conflict:"):
                row["component_id"] = str(blocker).split(":", 1)[1]
            blockers.append(row)
    return _dedupe_dicts(blockers)


def _sort_semantic_recombine_blocker_reason(blocker: str) -> str:
    if blocker == "recombine-overlapping-source-hunks":
        return "semantic-recombine-overlapping-source-hunks"
    if blocker.startswith("semantic-component-conflict:"):
        return "semantic-recombine-overlapping-components"
    if blocker == "missing-source-hunks":
        return "semantic-recombine-missing-source-hunks"
    if blocker == "protected-targets-not-jointly-preserved":
        return "semantic-recombine-protected-targets-not-jointly-preserved"
    if blocker == "no-scored-recombine-evidence":
        return "semantic-recombine-not-scored"
    return blocker


def _sort_semantic_recombine_parent(
    row: Mapping[str, Any],
    context: MetaCeilingContext,
) -> dict[str, Any]:
    parent = {
        "candidate_id": row.get("candidate_id"),
        "dimension_id": row.get("dimension_id"),
        "target_hits": sorted(_target_hit_virtuals(row, context.force_phys)),
        "source_hunks": list(row.get("source_hunks") or []),
        "source_components": list(row.get("source_components") or []),
    }
    for key in ("source_retained", "source_file", "path", "candidate_path"):
        value = _non_empty_str(row.get(key))
        if value is not None:
            parent[key] = value
    return parent


def _apply_sort_recombine_real_score_authority(
    semantic_recombine: dict[str, Any],
    artifact_summaries: Sequence[Mapping[str, Any]],
) -> None:
    if semantic_recombine.get("dimension_id") != SORT_SEMANTIC_RECOMBINE_DIMENSION:
        return
    semantic_context = _semantic_recombine_source_context_by_pair(
        semantic_recombine.get("ranked_candidates", []) or []
    )
    for summary in artifact_summaries:
        if summary.get("kind") not in _REAL_COMBINE_SUMMARY_KINDS:
            continue
        _inherit_sort_recombine_source_context(summary, semantic_context)
    real_by_id, real_by_pair = _real_combine_candidate_indexes(artifact_summaries)
    real_evidence_supplied = bool(real_by_id or real_by_pair) or any(
        _summary_has_real_combine_evidence(summary) for summary in artifact_summaries
    )

    changed = False
    terminal_blockers = _string_items(semantic_recombine.get("terminal_blockers"))
    for candidate in semantic_recombine.get("ranked_candidates", []) or []:
        if not isinstance(candidate, dict):
            continue
        if candidate.get("dimension_id") != SORT_SEMANTIC_RECOMBINE_DIMENSION:
            continue
        real_match = None
        for alias in _sort_recombine_candidate_identity_aliases(candidate):
            real_match = real_by_id.get(alias)
            if real_match is not None:
                break
        for pair_key in _sort_recombine_candidate_pair_keys(candidate):
            if real_match is not None:
                break
            real_match = real_by_pair.get(pair_key)
            if real_match is not None:
                break
        if real_match is None:
            if not real_evidence_supplied and candidate.get("accepted") is not True:
                terminal_blockers.extend(candidate.get("blockers") or [])
                continue
            _mark_estimated_sort_recombine_score_required(
                candidate,
                real_evidence_supplied=real_evidence_supplied,
            )
            terminal_blockers.extend(candidate.get("blockers") or [])
            changed = True
            continue
        real_candidate, real_summary = real_match
        if _real_combine_candidate_preserves_all(
            real_candidate
        ) and _candidate_has_source_route(real_candidate):
            _apply_real_combine_score(candidate, real_candidate)
            changed = True
            continue
        _supersede_estimated_sort_recombine(
            candidate,
            real_candidate=real_candidate,
            real_summary=real_summary,
        )
        changed = True
        terminal_blockers.extend(candidate.get("blockers") or [])
        terminal_blockers.extend(_string_items(real_summary.get("terminal_blockers")))

    if changed:
        accepted = [
            row
            for row in semantic_recombine.get("ranked_candidates", []) or []
            if isinstance(row, Mapping) and row.get("accepted") is True
        ]
        semantic_recombine["ranked_candidates"] = (
            _rank_sort_semantic_recombine_candidates(
                semantic_recombine.get("ranked_candidates", []) or []
            )
        )
        if accepted:
            semantic_recombine["status"] = "actionable"
            semantic_recombine["terminal_blockers"] = []
            semantic_recombine["terminal_reason"] = None
        elif real_evidence_supplied:
            semantic_recombine["status"] = "terminal"
            semantic_recombine["terminal_blockers"] = _dedupe_strings(
                [str(row) for row in terminal_blockers if row]
            )
            semantic_recombine["terminal_reason"] = (
                SORT_SEMANTIC_RECOMBINE_TERMINAL_REASON
            )
        else:
            semantic_recombine["status"] = "blocked"
            semantic_recombine["terminal_blockers"] = []
            semantic_recombine["terminal_reason"] = (
                "sort-semantic-dual-target-recombine-needs-real-score"
            )


def _summary_has_real_combine_evidence(summary: Mapping[str, Any]) -> bool:
    kind = summary.get("kind")
    if kind == "score-source":
        return any(
            isinstance(candidate, Mapping)
            and _score_source_semantic_recombine_candidate(candidate)
            for candidate in summary.get("ranked_candidates", []) or []
        )
    if kind not in _REAL_COMBINE_SUMMARY_KINDS:
        return False
    coverage = summary.get("score_coverage")
    if isinstance(coverage, Mapping):
        for key in (
            "ok_combinations",
            "skipped_combinations",
            "evaluable_combinations",
        ):
            if (_int_or_none(coverage.get(key)) or 0) > 0:
                return True
    return any(
        isinstance(candidate, Mapping)
        for candidate in summary.get("ranked_candidates", []) or []
    )


def _semantic_recombine_superseded_estimates(
    semantic_recombine: Mapping[str, Any] | None,
) -> list[dict[str, Any]]:
    if not isinstance(semantic_recombine, Mapping):
        return []
    out: list[dict[str, Any]] = []
    for row in semantic_recombine.get("ranked_candidates", []) or []:
        if not isinstance(row, Mapping):
            continue
        real_score_superseded_by = row.get("real_score_superseded_by")
        real_score_authority = row.get("real_score_authority")
        if real_score_superseded_by is None and real_score_authority is None:
            continue
        out.append(
            {
                "candidate_id": row.get("candidate_id"),
                "parents": list(row.get("parents") or []),
                "real_score_superseded_by": real_score_superseded_by,
            }
        )
    return out


def _semantic_recombine_source_context_by_pair(
    candidates: Sequence[Mapping[str, Any]],
) -> dict[tuple[str, ...], dict[str, Any]]:
    out: dict[tuple[str, ...], dict[str, Any]] = {}
    for candidate in candidates:
        pair_keys = _sort_recombine_candidate_pair_keys(candidate)
        if not pair_keys:
            continue
        context = {
            "parents": [
                str(parent)
                for parent in candidate.get("parents") or []
                if isinstance(parent, (str, int)) and str(parent)
            ],
            "source_hunks": [dict(row) for row in candidate.get("source_hunks") or []],
            "source_components": [
                dict(row) for row in candidate.get("source_components") or []
            ],
            "source_route": (
                dict(candidate["source_route"])
                if isinstance(candidate.get("source_route"), Mapping)
                else None
            ),
        }
        for index, pair_key in enumerate(pair_keys):
            if index == 0:
                out[pair_key] = context
            else:
                out.setdefault(pair_key, context)
    return out


def _sort_recombine_candidate_pair_keys(
    candidate: Mapping[str, Any],
) -> list[tuple[str, ...]]:
    parents = [
        str(parent)
        for parent in candidate.get("parents") or []
        if isinstance(parent, (str, int)) and str(parent)
    ]
    keys: list[tuple[str, ...]] = []
    exact_key = _parent_pair_key(parents)
    if exact_key is not None:
        keys.append(exact_key)
    if len(parents) < 2:
        return keys

    details = [
        dict(row)
        for row in candidate.get("parent_details") or []
        if isinstance(row, Mapping)
    ]
    details_by_id = {
        str(row["candidate_id"]): row
        for row in details
        if row.get("candidate_id") is not None
    }
    alias_groups: list[list[str]] = []
    for index, parent in enumerate(parents[:2]):
        detail = details_by_id.get(parent)
        if detail is None and index < len(details):
            detail = details[index]
        alias_groups.append(_sort_recombine_parent_aliases(parent, detail))
    for left in alias_groups[0]:
        for right in alias_groups[1]:
            pair_key = _parent_pair_key([left, right])
            if pair_key is not None and pair_key not in keys:
                keys.append(pair_key)
    return keys


def _sort_recombine_parent_aliases(
    parent: str,
    detail: Mapping[str, Any] | None,
) -> list[str]:
    aliases: list[str] = []

    def add(value: Any) -> None:
        text = _non_empty_str(value)
        if text is None:
            return
        aliases.append(text)
        path_name = Path(text).name
        if path_name and path_name != text:
            aliases.append(path_name)
        stem = Path(path_name).stem if path_name else ""
        if stem:
            aliases.append(stem)
        semantic_alias = _sort_recombine_known_alias(text)
        if semantic_alias is not None:
            aliases.append(semantic_alias)
        if path_name and path_name != text:
            semantic_alias = _sort_recombine_known_alias(path_name)
            if semantic_alias is not None:
                aliases.append(semantic_alias)
        if stem:
            semantic_alias = _sort_recombine_known_alias(stem)
            if semantic_alias is not None:
                aliases.append(semantic_alias)

    add(parent)
    if isinstance(detail, Mapping):
        for key in (
            "candidate_id",
            "dimension_id",
            "source_retained",
            "source_file",
            "path",
            "candidate_path",
        ):
            add(detail.get(key))
        for component in detail.get("source_components") or []:
            if isinstance(component, Mapping):
                add(component.get("component_id"))
        for hunk in detail.get("source_hunks") or []:
            if isinstance(hunk, Mapping):
                add(hunk.get("hunk_id"))
    return _dedupe_strings(aliases)


def _sort_recombine_known_alias(value: str) -> str | None:
    normalized = value.lower().replace("_", "-")
    if "init-indexed-write" in normalized or "name-total-locals" in normalized:
        return "init"
    if "indexed-byte-cache" in normalized or "byte-cache" in normalized:
        return "idxbyte"
    if "j-text" in normalized or "jtext" in normalized:
        return "jtext"
    if "max-text" in normalized or "maxtext" in normalized:
        return "maxtext"
    return None


def _inherit_sort_recombine_source_context(
    summary: Mapping[str, Any],
    semantic_context: Mapping[tuple[str, ...], Mapping[str, Any]],
) -> None:
    for key in ("ranked_candidates", "repair_candidates"):
        rows = summary.get(key)
        if not isinstance(rows, list):
            continue
        for candidate in rows:
            if not isinstance(candidate, dict):
                continue
            context = None
            for pair_key in _sort_recombine_candidate_pair_keys(candidate):
                context = semantic_context.get(pair_key)
                if context is not None:
                    break
            if context is None:
                continue
            if not candidate.get("resolved_parents") and isinstance(
                context.get("parents"),
                Sequence,
            ):
                candidate["resolved_parents"] = list(context["parents"])
            if not candidate.get("source_hunks"):
                candidate["source_hunks"] = [
                    dict(row) for row in context.get("source_hunks") or []
                ]
            if not candidate.get("source_components"):
                candidate["source_components"] = [
                    dict(row) for row in context.get("source_components") or []
                ]
            if not candidate.get("source_route") and isinstance(
                context.get("source_route"),
                Mapping,
            ):
                candidate["source_route"] = dict(context["source_route"])


def _real_combine_candidate_indexes(
    artifact_summaries: Sequence[Mapping[str, Any]],
) -> tuple[
    dict[str, tuple[Mapping[str, Any], Mapping[str, Any]]],
    dict[tuple[str, ...], tuple[Mapping[str, Any], Mapping[str, Any]]],
]:
    by_id: dict[str, tuple[Mapping[str, Any], Mapping[str, Any]]] = {}
    by_pair: dict[tuple[str, ...], tuple[Mapping[str, Any], Mapping[str, Any]]] = {}
    for summary in artifact_summaries:
        kind = summary.get("kind")
        if kind not in {*_REAL_COMBINE_SUMMARY_KINDS, "score-source"}:
            continue
        for candidate in summary.get("ranked_candidates", []) or []:
            if not isinstance(candidate, Mapping):
                continue
            if kind in _REAL_COMBINE_SUMMARY_KINDS:
                if candidate.get("dimension_id") == (
                    SORT_SEMANTIC_PROTECTED_LOSS_REPAIR_DIMENSION
                ):
                    continue
            elif not _score_source_semantic_recombine_candidate(candidate):
                continue
            match = (candidate, summary)
            for alias in _sort_recombine_candidate_identity_aliases(candidate):
                by_id.setdefault(alias, match)
            for pair_key in _sort_recombine_candidate_pair_keys(candidate):
                by_pair.setdefault(pair_key, match)
    return by_id, by_pair


def _score_source_semantic_recombine_candidate(candidate: Mapping[str, Any]) -> bool:
    if candidate.get("dimension_id") == SORT_SEMANTIC_RECOMBINE_DIMENSION:
        return True
    return any(
        _is_sort_semantic_recombine_identity(alias)
        for alias in _sort_recombine_candidate_identity_aliases(candidate)
    )


def _sort_recombine_candidate_identity_aliases(
    candidate: Mapping[str, Any],
) -> list[str]:
    aliases: list[str] = []

    def add(value: Any) -> None:
        text = _non_empty_str(value)
        if text is None:
            return
        aliases.append(text)
        path_name = Path(text).name
        if path_name and path_name != text:
            aliases.append(path_name)
        for item in (text, path_name):
            if not item:
                continue
            if item.endswith(".score.json"):
                aliases.append(item[: -len(".score.json")])
            if item.endswith(".pcdump.txt"):
                aliases.append(item[: -len(".pcdump.txt")])
        stem = Path(path_name).stem if path_name else ""
        if stem:
            aliases.append(stem)
            if stem.endswith(".pcdump"):
                aliases.append(stem[: -len(".pcdump")])

    for key in (
        "candidate_id",
        "source_retained",
        "source_file",
        "path",
        "candidate_path",
        "pcdump_path",
    ):
        add(candidate.get(key))
    return _dedupe_strings(aliases)


def _is_sort_semantic_recombine_identity(value: Any) -> bool:
    text = _non_empty_str(value)
    if text is None:
        return False
    variants = [text, Path(text).name]
    path_name = Path(text).name
    if path_name:
        variants.append(Path(path_name).stem)
    for variant in variants:
        normalized = variant.lower().replace("_", "-")
        if normalized.startswith("post-meta-sort-semantic-recombine-"):
            return True
        if "sort-semantic-recombine" in normalized:
            return True
    return False


def _real_combine_candidate_preserves_all(candidate: Mapping[str, Any]) -> bool:
    targeted = _int_or_none(candidate.get("target_targeted")) or 0
    matched = _int_or_none(candidate.get("target_matched")) or 0
    structural_accepted = candidate.get(
        "structural_guard_accepted"
    ) is True or _structural_guard_accepted(
        candidate.get("structural_guard")
        if isinstance(candidate.get("structural_guard"), Mapping)
        else None
    )
    if targeted > 0 and matched >= targeted and structural_accepted:
        return True
    missing = candidate.get("missing_protected_assignments")
    return isinstance(missing, list) and not missing and structural_accepted


def _apply_real_combine_score(
    candidate: dict[str, Any],
    real_candidate: Mapping[str, Any],
) -> None:
    if "target_score_estimate" not in candidate:
        candidate["target_score_estimate"] = candidate.get("target_score")
    for key in (
        "target_score",
        "target_score_total",
        "target_matched",
        "target_targeted",
        "target_virtual_distance",
        "structural_guard",
        "structural_guard_accepted",
        "expression_score",
        "expression_matched",
        "expression_targeted",
        "expression_virtual_distance",
        "pcdump_path",
        "source_retained",
        "path",
        "source_hunks",
        "source_components",
        "source_route",
        "missing_protected_assignments",
        "satisfied_protected_assignments",
        "protected_assignments_satisfied",
        "normalized_diff_lines",
        "frame_delta",
    ):
        if real_candidate.get(key) is not None:
            candidate[key] = real_candidate.get(key)
    candidate["accepted"] = True
    candidate["recommendation"] = "retain"
    candidate["blockers"] = [
        blocker
        for blocker in candidate.get("blockers", [])
        if blocker != "no-scored-recombine-evidence"
    ]


def _mark_estimated_sort_recombine_score_required(
    candidate: dict[str, Any],
    *,
    real_evidence_supplied: bool,
) -> None:
    if "target_score_estimate" not in candidate:
        candidate["target_score_estimate"] = candidate.get("target_score")
    candidate["target_score"] = None
    candidate["target_matched"] = 0
    candidate["target_virtual_distance"] = candidate.get("target_targeted") or 0
    structural = (
        dict(candidate.get("structural_guard"))
        if isinstance(candidate.get("structural_guard"), Mapping)
        else {}
    )
    structural["accepted"] = False
    structural["status"] = "real-score-required"
    structural["estimated"] = True
    candidate["structural_guard"] = structural
    candidate["structural_guard_accepted"] = False
    candidate["accepted"] = False
    candidate["recommendation"] = "score-required"
    candidate["estimated_recombine_suppressed"] = True
    if real_evidence_supplied:
        candidate["real_score_authority"] = "semantic-recombine-real-score"
    candidate["blockers"] = _dedupe_strings(
        [
            *[str(row) for row in candidate.get("blockers") or []],
            "no-scored-recombine-evidence",
        ]
    )


def _supersede_estimated_sort_recombine(
    candidate: dict[str, Any],
    *,
    real_candidate: Mapping[str, Any],
    real_summary: Mapping[str, Any],
) -> None:
    if "target_score_estimate" not in candidate:
        candidate["target_score_estimate"] = candidate.get("target_score")
    _apply_real_combine_score(candidate, real_candidate)
    structural = (
        dict(candidate.get("structural_guard"))
        if isinstance(candidate.get("structural_guard"), Mapping)
        else {}
    )
    structural["accepted"] = False
    structural["status"] = "real-score-protected-loss"
    structural["real_score_candidate_id"] = real_candidate.get("candidate_id")
    candidate["structural_guard"] = structural
    candidate["structural_guard_accepted"] = False
    candidate["accepted"] = False
    candidate["recommendation"] = "reject"
    candidate["real_score_superseded_by"] = real_candidate.get("candidate_id")
    candidate["terminal_blockers"] = _dedupe_strings(
        [
            *[str(row) for row in real_candidate.get("terminal_blockers") or []],
            *[str(row) for row in real_summary.get("terminal_blockers") or []],
        ]
    )
    candidate["next_actions"] = [
        dict(row) if isinstance(row, Mapping) else row
        for row in real_summary.get("next_actions") or []
    ]
    candidate["blockers"] = _dedupe_strings(
        [
            "real-score-protected-loss",
            *[str(row) for row in candidate.get("blockers") or []],
            *candidate.get("terminal_blockers", []),
        ]
    )


def _combined_recombine_target_score(
    left: Mapping[str, Any],
    right: Mapping[str, Any],
    context: MetaCeilingContext,
) -> dict[str, Any]:
    virtuals: dict[str, dict[str, Any]] = {}
    for virtual, expected in context.force_phys.items():
        key = str(virtual)
        chosen: dict[str, Any] = {
            "expected": expected,
            "actual": None,
            "matched": False,
        }
        for row in (left, right):
            target_score = row.get("target_score")
            row_virtuals = (
                target_score.get("virtuals")
                if isinstance(target_score, Mapping)
                else None
            )
            item = row_virtuals.get(key) if isinstance(row_virtuals, Mapping) else None
            if not isinstance(item, Mapping):
                continue
            current = dict(item)
            if bool(current.get("matched")):
                chosen = current
                break
            if chosen.get("actual") is None:
                chosen = current
        virtuals[key] = chosen
    matched = sum(1 for row in virtuals.values() if bool(row.get("matched")))
    targeted = len(context.force_phys)
    return {
        "matched": matched,
        "targeted": targeted,
        "virtual_distance": max(targeted - matched, 0),
        "virtuals": virtuals,
        "estimated": True,
    }


def _source_component_ids(row: Mapping[str, Any]) -> set[str]:
    out: set[str] = set()
    for component in row.get("source_components") or []:
        if not isinstance(component, Mapping):
            continue
        component_id = _non_empty_str(component.get("component_id"))
        if component_id is not None:
            out.add(component_id)
    return out


def _source_hunk_sets_overlap(
    left_hunks: Sequence[Mapping[str, Any]],
    right_hunks: Sequence[Mapping[str, Any]],
) -> bool:
    for left in left_hunks:
        left_range = _source_hunk_base_range(left)
        if left_range is None:
            continue
        for right in right_hunks:
            right_range = _source_hunk_base_range(right)
            if right_range is None:
                continue
            if line_ranges_overlap(*left_range, *right_range):
                return True
    return False


def _source_hunk_base_range(hunk: Mapping[str, Any]) -> tuple[int, int] | None:
    start = _int_or_none(hunk.get("base_start"))
    end = _int_or_none(hunk.get("base_end"))
    if start is not None and end is not None:
        return (start, end)
    base_range = hunk.get("base_range")
    if isinstance(base_range, Mapping):
        start = _int_or_none(base_range.get("start"))
        end = _int_or_none(base_range.get("end"))
        if start is not None and end is not None:
            return (max(start - 1, 0), max(end, start - 1))
    start = _int_or_none(hunk.get("old_start"))
    end = _int_or_none(hunk.get("old_end"))
    if start is not None and end is not None:
        return (max(start - 1, 0), max(end, start - 1))
    return None


def _continuation_context(classified: Mapping[str, Any]) -> MetaCeilingContext:
    function = _non_empty_str(classified.get("function"))
    if function is None:
        raise SourceFamilySynthesisError(
            "missing-function",
            "classified source-family JSON must contain a function",
        )
    profile = _require_profile(function)
    force_phys = _continuation_force_phys(classified, profile)
    proof = (
        classified.get("source_model_proof")
        if isinstance(classified.get("source_model_proof"), Mapping)
        else {}
    )
    synthesis = (
        proof.get("source_family_synthesis")
        if isinstance(proof.get("source_family_synthesis"), Mapping)
        else {}
    )
    classified_context = (
        classified.get("context") if isinstance(classified.get("context"), Mapping) else {}
    )
    return MetaCeilingContext(
        function=function,
        source_function=(
            _non_empty_str(classified.get("source_function"))
            or str(profile["source_function"])
        ),
        source_file=str(profile["source_file"]),
        register_class=str(profile["register_class"]),
        force_phys=force_phys,
        source_spans=_continuation_source_spans(classified),
        allocator_facts=[],
        force_phys_conflicts=[],
        closed_families=_dedupe_strings(
            [
                *_payload_closed_families(classified),
                COMPAT_SOURCE_MODEL_FAMILY,
                CONTINUATION_FAMILY,
            ]
        ),
        next_unsupported_source_dimension=_first_non_empty_str(
            classified.get("next_unsupported_source_dimension"),
            proof.get("next_unsupported_source_dimension"),
            synthesis.get("next_unsupported_source_dimension"),
            classified_context.get("next_unsupported_source_dimension"),
        ),
        next_unsupported_source_model=_first_non_empty_str(
            classified.get("next_unsupported_source_model"),
            proof.get("next_unsupported_source_model"),
            synthesis.get("next_unsupported_source_model"),
            classified_context.get("next_unsupported_source_model"),
        ),
        next_unsupported_source_family=_first_non_empty_str(
            classified.get("next_unsupported_source_family"),
            proof.get("next_unsupported_source_family"),
            synthesis.get("next_unsupported_source_family"),
            classified_context.get("next_unsupported_source_family"),
        ),
        current_ceiling=(
            dict(classified_context.get("current_ceiling"))
            if isinstance(classified_context.get("current_ceiling"), Mapping)
            else {}
        ),
    )


def _continuation_force_phys(
    classified: Mapping[str, Any],
    profile: Mapping[str, Any],
) -> dict[str, int]:
    for row in _classification_score_rows(classified):
        metadata = row.get("validation_metadata")
        if isinstance(metadata, Mapping):
            force = _normalized_force_phys(metadata.get("final_force_phys"))
            if force:
                return force
        target_score = row.get("target_score")
        virtuals = (
            target_score.get("virtuals") if isinstance(target_score, Mapping) else None
        )
        if isinstance(virtuals, Mapping):
            force: dict[str, int] = {}
            for virtual, item in virtuals.items():
                if not isinstance(item, Mapping):
                    continue
                expected = _register_num(item.get("expected"))
                if expected is not None:
                    force[str(virtual)] = expected
            if force:
                return force
    return {str(key): int(value) for key, value in dict(profile["force_phys"]).items()}


def _normalized_force_phys(raw: Any) -> dict[str, int]:
    if not isinstance(raw, Mapping):
        return {}
    out: dict[str, int] = {}
    for key, value in raw.items():
        parsed = _register_num(value)
        if parsed is not None:
            out[str(key)] = parsed
    return out


def _continuation_source_spans(classified: Mapping[str, Any]) -> list[dict[str, Any]]:
    spans: list[dict[str, Any]] = []
    for row in _classification_score_rows(classified):
        expression_score = row.get("expression_score")
        virtuals = (
            expression_score.get("virtuals")
            if isinstance(expression_score, Mapping)
            else None
        )
        if not isinstance(virtuals, Mapping):
            continue
        for raw_virtual, item in virtuals.items():
            if not isinstance(item, Mapping):
                continue
            baseline = item.get("baseline_source")
            if not isinstance(baseline, Mapping):
                continue
            span = dict(baseline)
            virtual = _int_or_none(raw_virtual)
            if virtual is not None:
                span.setdefault("virtual", virtual)
            signature = item.get("signature")
            if isinstance(signature, Mapping):
                span.setdefault("name", signature.get("name"))
                span.setdefault("expression", signature.get("expression"))
                span.setdefault("kind", signature.get("source_kind"))
            spans.append(span)
    return _dedupe_dicts(spans)


def _classification_score_rows(classified: Mapping[str, Any]) -> list[dict[str, Any]]:
    for key in ("score_rows", "ranked_candidates", "risky_candidates"):
        rows = classified.get(key)
        if isinstance(rows, list) and rows:
            return [dict(row) for row in rows if isinstance(row, Mapping)]
    score_classification = classified.get("score_classification")
    rows = (
        score_classification.get("candidates")
        if isinstance(score_classification, Mapping)
        else None
    )
    if isinstance(rows, list):
        return [dict(row) for row in rows if isinstance(row, Mapping)]
    return []


def _classified_sort_cross_tu_no_modeled_terminal_exhaustion(
    classified: Mapping[str, Any],
) -> dict[str, Any] | None:
    if classified.get("function") != SORT_FUNCTION:
        return None
    context = _continuation_context(classified)
    proof = (
        classified.get("source_model_proof")
        if isinstance(classified.get("source_model_proof"), Mapping)
        else {}
    )
    synthesis = (
        proof.get("source_family_synthesis")
        if isinstance(proof.get("source_family_synthesis"), Mapping)
        else {}
    )
    sources = [
        source
        for source in (classified, proof, synthesis, context.current_ceiling)
        if isinstance(source, Mapping)
    ]
    if not any(
        _sort_cross_tu_no_modeled_final_source(source, function=SORT_FUNCTION)
        for source in sources
    ):
        return None

    rows = _classification_score_rows(classified)
    proof_rows = _dedupe_dicts(
        [
            *[
                row
                for source in sources
                for row in _sort_cross_tu_proof_score_evidence_rows(source)
            ],
        ]
    )
    all_rows = _dedupe_dicts([*rows, *proof_rows])
    if not all_rows:
        return None
    has_real_evidence = any(
        isinstance(row.get("target_score"), Mapping)
        or _non_empty_str(row.get("source_retained")) is not None
        or _non_empty_str(row.get("pcdump_path")) is not None
        or isinstance(row.get("structural_guard"), Mapping)
        for row in all_rows
    ) or any(_sort_cross_tu_proof_has_retained_real_evidence(source) for source in sources)
    has_one_hit_evidence = any(
        _sort_cross_tu_proof_has_one_hit_terminal_evidence(source)
        for source in sources
    )
    if not has_one_hit_evidence:
        hit_virtuals: set[str] = set()
        for row in all_rows:
            hits = _target_hit_virtuals(row, context.force_phys)
            if len(hits) == 1:
                hit_virtuals.update(hits)
        has_one_hit_evidence = {"34", "44"} <= hit_virtuals
    if not has_real_evidence or not has_one_hit_evidence:
        return None

    retained_scored_probes = _dedupe_dicts(
        [
            *[_retained_scored_probe(row) for row in rows],
            *[
                dict(row)
                for row in proof_rows
                if isinstance(row, Mapping)
            ],
        ]
    )
    retained_scored_probes = [
        row
        for row in retained_scored_probes
        if row.get("candidate_id") or row.get("target_score")
    ]
    source_hunks_by_candidate = _dedupe_dicts(
        [
            {
                "candidate_id": row.get("candidate_id"),
                "dimension_id": (
                    row.get("dimension_id")
                    or SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION
                ),
                "source_hunks": list(row.get("source_hunks") or []),
                "source_components": list(row.get("source_components") or []),
                **(
                    {"source_retained": row["source_retained"]}
                    if row.get("source_retained")
                    else {}
                ),
                **(
                    {"pcdump_path": row["pcdump_path"]}
                    if row.get("pcdump_path")
                    else {}
                ),
            }
            for row in retained_scored_probes
            if row.get("candidate_id")
            and (row.get("source_hunks") or row.get("source_components"))
        ]
    )
    exhausted_dimensions = _dedupe_dicts(
        [
            *[
                dict(row)
                for source in sources
                for row in _list_of_dicts(source.get("exhausted_dimensions"))
            ],
            {
                "dimension_id": SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION,
                "status": "scored-terminal",
                "exhaustion_reason": (
                    "one-hit-recombine-protected-targets-not-jointly-preserved"
                ),
                "candidate_ids": _dedupe_strings(
                    [
                        str(row.get("candidate_id"))
                        for row in retained_scored_probes
                        if row.get("candidate_id")
                    ]
                ),
            },
        ]
    )
    terminal_blockers = _dedupe_strings(
        [
            SORT_CROSS_TU_NO_MODELED_SOURCE_TERMINAL_BLOCKER,
            SORT_CROSS_TU_ONE_HIT_TERMINAL_BLOCKER,
            "protected-targets-not-jointly-preserved",
            *[
                blocker
                for source in sources
                for blocker in _sort_cross_tu_raw_terminal_blockers(source)
            ],
        ]
    )
    next_hint = {
        "next_unsupported_source_model": (
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_MODEL
        ),
        "next_unsupported_source_family": (
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_FAMILY
        ),
        "next_unsupported_source_spans": source_hunks_by_candidate,
        "terminal_reason": (
            "post-meta-gpr-one-hit-source-family-continuation-exhausted/"
            "protected-structural-ceiling"
        ),
    }
    return {
        "next_unsupported_source_model": next_hint["next_unsupported_source_model"],
        "next_hint": next_hint,
        "exhausted_dimensions": exhausted_dimensions,
        "terminal_blockers": terminal_blockers,
        "retained_scored_probes": retained_scored_probes,
    }


def _classified_full_selection_swap_terminal_exhaustion(
    classified: Mapping[str, Any],
) -> dict[str, Any] | None:
    terminal_cases = (
        (
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION,
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_MODEL,
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_FAMILY,
        ),
        (
            SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION,
            SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_EXHAUSTED_NEXT_MODEL,
            SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_EXHAUSTED_NEXT_FAMILY,
        ),
        (
            SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION,
            SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_MODEL,
            SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_FAMILY,
        ),
        (
            SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION,
            SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_EXHAUSTED_NEXT_MODEL,
            SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_EXHAUSTED_NEXT_FAMILY,
        ),
        (
            SORT_FULL_SELECTION_SWAP_DIMENSION,
            SORT_FULL_SELECTION_SWAP_EXHAUSTED_NEXT_MODEL,
            SORT_FULL_SELECTION_SWAP_EXHAUSTED_NEXT_FAMILY,
        ),
    )
    if classified.get("status") != "terminal":
        return _classified_sort_scored_rows_terminal_exhaustion(
            classified,
            terminal_cases,
        )
    proof = (
        classified.get("source_model_proof")
        if isinstance(classified.get("source_model_proof"), Mapping)
        else {}
    )
    synthesis = (
        proof.get("source_family_synthesis")
        if isinstance(proof.get("source_family_synthesis"), Mapping)
        else {}
    )
    proof_kind = _non_empty_str(classified.get("kind"))
    synthesis_status = _non_empty_str(synthesis.get("status"))
    if (
        proof_kind != "post-meta-ceiling-gpr-source-family-synthesis-proof"
        and synthesis_status != "synthesis-exhausted"
    ):
        return None

    attempted = set(_string_items(proof.get("attempted_equivalence_classes")))
    attempted.update(_string_items(synthesis.get("attempted_equivalence_classes")))
    for source in (classified, proof, synthesis):
        for row in source.get("exhausted_dimensions") or []:
            if isinstance(row, Mapping) and row.get("dimension_id"):
                attempted.add(str(row["dimension_id"]))
    next_model = _first_non_empty_str(
        classified.get("next_unsupported_source_model"),
        proof.get("next_unsupported_source_model"),
        synthesis.get("next_unsupported_source_model"),
    )
    next_family = _first_non_empty_str(
        classified.get("next_unsupported_source_family"),
        proof.get("next_unsupported_source_family"),
        synthesis.get("next_unsupported_source_family"),
    )
    matched_case: tuple[str, str, str] | None = None
    for dimension_id, expected_model, expected_family in terminal_cases:
        if dimension_id in attempted or next_family == expected_family:
            matched_case = (dimension_id, expected_model, expected_family)
            break
    if matched_case is None:
        return None
    _dimension_id, expected_model, expected_family = matched_case
    if next_model != expected_model and next_family != expected_family:
        return None
    spans = _first_mapping_list(
        classified.get("next_unsupported_source_spans"),
        proof.get("next_unsupported_source_spans"),
        synthesis.get("next_unsupported_source_spans"),
    )
    next_hint = {
        "next_unsupported_source_model": (next_model or expected_model),
        "next_unsupported_source_family": (next_family or expected_family),
        "next_unsupported_source_spans": spans,
    }
    return {
        "next_unsupported_source_model": next_hint["next_unsupported_source_model"],
        "next_hint": next_hint,
    }


def _classified_sort_scored_rows_terminal_exhaustion(
    classified: Mapping[str, Any],
    terminal_cases: Sequence[tuple[str, str, str]],
) -> dict[str, Any] | None:
    if classified.get("function") != SORT_FUNCTION:
        return None
    if classified.get("status") != "blocked":
        return None
    rows = _classification_score_rows(classified)
    if not rows:
        return None
    if _classified_sort_raw_score_artifact_incomplete(classified, rows):
        return None
    rows_by_dimension: dict[str, list[Mapping[str, Any]]] = {}
    for row in rows:
        dimension_id = _non_empty_str(row.get("dimension_id"))
        if dimension_id is None:
            continue
        rows_by_dimension.setdefault(dimension_id, []).append(row)
    cross_tu_rows = _classified_sort_scored_rows_cross_tu_layer_rows(
        classified,
        rows,
    )
    if cross_tu_rows:
        rows_by_dimension.setdefault(
            SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION,
            cross_tu_rows,
        )

    matched_case: tuple[str, str, str] | None = None
    for dimension_id, expected_model, expected_family in terminal_cases:
        if dimension_id in rows_by_dimension:
            matched_case = (dimension_id, expected_model, expected_family)
            break
    if matched_case is None:
        return None

    dimension_id, expected_model, expected_family = matched_case
    if any(row.get("score_error") for row in rows_by_dimension[dimension_id]):
        return None
    force_phys = _continuation_force_phys(classified, _require_profile(SORT_FUNCTION))
    required_virtuals = set(force_phys)
    for row in rows_by_dimension[dimension_id]:
        if (
            required_virtuals
            and required_virtuals <= _target_hit_virtuals(row, force_phys)
            and _row_structural_guard_accepted(row)
            and _candidate_has_source_route(row)
        ):
            return None

    best_row = next(iter(_rank_score_rows(rows_by_dimension[dimension_id])), {})
    spans: list[dict[str, Any]] = []
    if best_row:
        span = {
            "candidate_id": best_row.get("candidate_id"),
            "dimension_id": dimension_id,
            "source_components": list(best_row.get("source_components") or []),
            "source_hunks": list(best_row.get("source_hunks") or []),
        }
        source_retained = _non_empty_str(best_row.get("source_retained"))
        if source_retained is not None:
            span["source_retained"] = source_retained
        pcdump_path = _non_empty_str(best_row.get("pcdump_path"))
        if pcdump_path is not None:
            span["pcdump_path"] = pcdump_path
        spans.append(span)

    exhausted_dimensions = _dedupe_dicts(
        [
            *[
                dict(row)
                for row in _list_of_dicts(classified.get("exhausted_dimensions"))
            ],
            {
                "dimension_id": dimension_id,
                "status": "scored-terminal",
                "exhaustion_reason": "protected-targets-not-jointly-preserved",
                "candidate_ids": _dedupe_strings(
                    [
                        str(row.get("candidate_id"))
                        for row in rows_by_dimension[dimension_id]
                        if row.get("candidate_id")
                    ]
                ),
            },
        ]
    )
    next_hint = {
        "next_unsupported_source_model": expected_model,
        "next_unsupported_source_family": expected_family,
        "next_unsupported_source_spans": spans,
        "exhausted_dimensions": exhausted_dimensions,
        "terminal_blockers": ["protected-targets-not-jointly-preserved"],
    }
    return {
        "next_unsupported_source_model": expected_model,
        "next_hint": next_hint,
        "exhausted_dimensions": exhausted_dimensions,
        "terminal_blockers": next_hint["terminal_blockers"],
    }


def _classified_sort_scored_rows_cross_tu_layer_rows(
    classified: Mapping[str, Any],
    rows: Sequence[Mapping[str, Any]],
) -> list[Mapping[str, Any]]:
    force_phys = _continuation_force_phys(classified, _require_profile(SORT_FUNCTION))
    if not {"34", "44"} <= set(force_phys):
        return []
    scored_rows = [
        row for row in rows if _row_has_complete_target_score(row, force_phys)
    ]
    if not scored_rows:
        return []
    text_values: list[Any] = [
        classified.get("output_dir"),
        classified.get("source_retained"),
        classified.get("source_file"),
        classified.get("artifact"),
        classified.get("_artifact_path"),
        classified.get("next_unsupported_source_family"),
        classified.get("next_unsupported_source_model"),
        _nested_value(
            classified,
            ("context", "current_ceiling", "next_unsupported_source_family"),
        ),
        _nested_value(
            classified,
            ("context", "current_ceiling", "next_unsupported_source_model"),
        ),
    ]
    for row in rows:
        text_values.extend([
            row.get("candidate_id"),
            row.get("dimension_id"),
            row.get("family"),
            row.get("strategy"),
            row.get("source_retained"),
            row.get("source_file"),
        ])
    text = " ".join(str(value or "") for value in text_values).lower()
    if (
        "cross_tu_symbol_linkage" in text
        or "cross-tu-symbol-linkage" in text
        or "sort_cross_after_whole_function" in text
        or "sort-cross-after-whole-function" in text
        or SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION in text
    ):
        return scored_rows
    return []


def _classified_sort_raw_score_artifact_incomplete(
    classified: Mapping[str, Any],
    rows: Sequence[Mapping[str, Any]],
) -> bool:
    incomplete_keys = (
        "missing_score_candidate_ids",
        "unjoined_score_rows",
        "missing_inputs",
        "score_errors",
    )
    if any(classified.get(key) for key in incomplete_keys):
        return True
    candidate_count = _int_or_none(classified.get("candidate_count"))
    score_count = _int_or_none(classified.get("score_count"))
    joined_score_count = _int_or_none(classified.get("joined_score_count"))
    if candidate_count is not None:
        if score_count is not None and score_count < candidate_count:
            return True
        if joined_score_count is not None and joined_score_count < candidate_count:
            return True
        if (
            score_count is None
            and joined_score_count is None
            and len(rows) < candidate_count
        ):
            return True
    return False


