def _sort_post_inline_final_source(source: Mapping[str, Any]) -> bool:
    for key in (
        "terminal_reason",
        "terminal_blocker",
        "reason",
        "next_unsupported_source_family",
        "next_unsupported_source_model",
    ):
        value = _non_empty_str(source.get(key))
        if value in {
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_TERMINAL_REASON,
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_TERMINAL_BLOCKER,
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_FINAL_FAMILY,
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_FINAL_MODEL,
        }:
            return True
    if (
        _non_empty_str(source.get("exhausted_source_dimension"))
        == SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
    ):
        return True
    for row in _list_of_dicts(source.get("exhausted_dimensions")):
        if row.get("exhaustion_reason") == (
            SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_TERMINAL_REASON
        ):
            return True
        if (
            row.get("dimension_id")
            == SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
            and row.get("status") in {"terminal", "scored-terminal", "exhausted"}
        ):
            return True
    return False


