def _strip_generic_draw_expression_handoff(value: Any) -> Any:
    if isinstance(value, Mapping):
        out: dict[str, Any] = {}
        for key, item in value.items():
            if (
                key == "unsupported_source_expression_class"
                and item == DRAW_UNSUPPORTED_SOURCE_EXPRESSION_CLASS
            ):
                continue
            if (
                key == "unsupported_source_expression_model"
                and item == DRAW_UNSUPPORTED_SOURCE_EXPRESSION_MODEL
            ):
                continue
            if (
                key == "next_unsupported_source_model"
                and item == DRAW_UNSUPPORTED_SOURCE_EXPRESSION_MODEL
            ):
                continue
            out[str(key)] = _strip_generic_draw_expression_handoff(item)
        return out
    if isinstance(value, list):
        return [_strip_generic_draw_expression_handoff(item) for item in value]
    return value


