def _transform_corpus_adapter_outcomes(
    candidates: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    dimensions = tuple(_profile_dimensions(_function_from_rows(candidates, ())))
    emitted_by_dimension: dict[str, int] = {dimension: 0 for dimension in dimensions}
    for candidate in candidates:
        if candidate.get("adapted_from_transform_corpus"):
            dimension = str(candidate.get("dimension_id"))
            emitted_by_dimension[dimension] = emitted_by_dimension.get(dimension, 0) + 1
    outcomes: list[dict[str, Any]] = []
    for dimension in dimensions:
        emitted = emitted_by_dimension.get(dimension, 0)
        if emitted:
            outcomes.append(
                {
                    "dimension_id": dimension,
                    "status": "emitted",
                    "emitted_candidate_count": emitted,
                }
            )
        else:
            outcomes.append(
                {
                    "dimension_id": dimension,
                    "status": "skipped",
                    "reason": (
                        "no transform-corpus adapter input was provided; "
                        "post-meta synthesis emitted retained-source variants only"
                    ),
                }
            )
    return outcomes


def _target_anchors(context: MetaCeilingContext) -> list[dict[str, Any]]:
    expression_by_virtual = {
        str(row["virtual"]): row for row in _expression_anchors(context)
    }
    anchors: list[dict[str, Any]] = []
    for virtual, expected in sorted(
        context.force_phys.items(), key=lambda item: int(item[0])
    ):
        expression_anchor = expression_by_virtual.get(str(virtual), {})
        anchors.append(
            {
                "virtual": int(virtual),
                "baseline_virtual": int(virtual),
                "name": expression_anchor.get("name", f"ig{virtual}"),
                "expression": expression_anchor.get("expression"),
                "expected": expected,
                "actual": expression_anchor.get("actual"),
                "matched": False,
            }
        )
    return anchors


def _expression_anchors(context: MetaCeilingContext) -> list[dict[str, Any]]:
    if context.register_class != "fpr":
        return []
    anchors: list[dict[str, Any]] = []
    for virtual, expected in sorted(
        context.force_phys.items(), key=lambda item: int(item[0])
    ):
        span = _source_span_for_virtual(context, int(virtual))
        actual = _best_actual_for_virtual(context.allocator_facts, int(virtual))
        name = _non_empty_str(span.get("name")) if span else None
        expression = _non_empty_str(span.get("expression")) if span else None
        anchors.append(
            {
                "virtual": int(virtual),
                "baseline_virtual": int(virtual),
                "name": name,
                "expression": expression,
                "expected": expected,
                "actual": actual,
                "matched": actual == expected if actual is not None else False,
                "source_kind": span.get("kind") if span else None,
                "baseline_source": dict(span) if span else {},
            }
        )
    return anchors


def _unsupported_source_expression_class(
    context: MetaCeilingContext,
    expression_anchors: Sequence[Mapping[str, Any]],
) -> str | None:
    if context.function != DRAW_FUNCTION or context.register_class != "fpr":
        return None
    virtuals = {
        _int_or_none(row.get("virtual"))
        for row in expression_anchors
        if isinstance(row, Mapping)
    }
    texts = " ".join(
        str(row.get(key) or "")
        for row in expression_anchors
        if isinstance(row, Mapping)
        for key in ("name", "expression", "source_kind")
    )
    if {32, 37, 46} <= {value for value in virtuals if value is not None}:
        return DRAW_UNSUPPORTED_SOURCE_EXPRESSION_CLASS
    if (
        "col_offset" in texts
        and "row_offset" in texts
        and ("fsubs" in texts or "fpr-temp" in texts)
    ):
        return DRAW_UNSUPPORTED_SOURCE_EXPRESSION_CLASS
    return None


def _source_span_for_virtual(
    context: MetaCeilingContext,
    virtual: int,
) -> dict[str, Any] | None:
    preferred_names = {
        32: ("col_offset", "y_spacing * (f32) col"),
        37: ("row_offset", "row_offset", "HSD_JObjGetTranslationY"),
        46: ("fsubs f46,f45,f44", "fpr-temp"),
    }.get(virtual, ())
    for needle in preferred_names:
        for span in context.source_spans:
            text = " ".join(
                str(span.get(key) or "") for key in ("name", "expression", "kind")
            )
            if needle and needle in text:
                return dict(span)
    return None


def _best_actual_for_virtual(
    allocator_facts: Sequence[Mapping[str, Any]],
    virtual: int,
) -> int | None:
    for fact in allocator_facts:
        if _int_or_none(fact.get("virtual")) != virtual:
            continue
        actual = _int_or_none(fact.get("actual"))
        if actual is not None:
            return actual
    return None


def _residual_blockers(
    score_rows: Sequence[Mapping[str, Any]],
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    best_by_virtual: dict[str, Mapping[str, Any]] = {}
    for row in _rank_score_rows(score_rows):
        score = row.get("target_score")
        virtuals = score.get("virtuals") if isinstance(score, Mapping) else None
        if not isinstance(virtuals, Mapping):
            continue
        for virtual in context.force_phys:
            if virtual in best_by_virtual:
                continue
            virtual_row = virtuals.get(virtual)
            if isinstance(virtual_row, Mapping):
                best_by_virtual[virtual] = virtual_row
    blockers: list[dict[str, Any]] = []
    for virtual, expected in sorted(
        context.force_phys.items(), key=lambda item: int(item[0])
    ):
        row = best_by_virtual.get(virtual)
        actual = _int_or_none(row.get("actual")) if isinstance(row, Mapping) else None
        matched = bool(row.get("matched")) if isinstance(row, Mapping) else False
        if actual == expected:
            matched = True
        if matched:
            continue
        blockers.append(
            {
                "virtual": int(virtual),
                "expected": expected,
                "actual": actual,
                "matched": False,
                "score_source": "target_score",
            }
        )
    return blockers


def _target_score_counts(
    target_score: Mapping[str, Any] | None,
    force_phys: Mapping[str, int],
) -> tuple[int, int, int]:
    if not isinstance(target_score, Mapping):
        return 0, len(force_phys), len(force_phys)
    matched = 0
    targeted = 0
    virtuals = target_score.get("virtuals")
    if isinstance(virtuals, Mapping):
        for virtual, expected in force_phys.items():
            row = virtuals.get(str(virtual))
            if not isinstance(row, Mapping):
                continue
            targeted += 1
            actual = _int_or_none(row.get("actual"))
            if row.get("matched") is True or actual == expected:
                matched += 1
        if targeted:
            return matched, targeted, max(targeted - matched, 0)
    raw_matched = _int_or_none(target_score.get("matched"))
    raw_targeted = _int_or_none(target_score.get("targeted"))
    raw_distance = _int_or_none(target_score.get("virtual_distance"))
    matched = raw_matched if raw_matched is not None else 0
    targeted = raw_targeted if raw_targeted is not None else len(force_phys)
    distance = raw_distance if raw_distance is not None else max(targeted - matched, 0)
    return matched, targeted, distance


def _row_progress_count(row: Mapping[str, Any]) -> int:
    return max(
        int(row.get("target_matched") or 0),
        int(row.get("expression_matched") or 0),
    )


def _structural_guard_accepted(structural: Mapping[str, Any] | None) -> bool:
    if not isinstance(structural, Mapping):
        return False
    if structural.get("accepted") is True or structural.get("ok") is True:
        return True
    status = str(structural.get("status") or "").lower()
    return status in {"accepted", "ok", "normalized-structural-match"}


def _score_row_invalid_generated_source(row: Mapping[str, Any]) -> bool:
    validation = row.get("source_validation")
    if isinstance(validation, Mapping) and validation.get("status") == "invalid-source":
        return True
    return row.get("score_error") == "invalid-source"


def _score_error(payload: Mapping[str, Any]) -> str | None:
    validation = payload.get("source_validation")
    if isinstance(validation, Mapping) and validation.get("status") == "invalid-source":
        return "invalid-source"
    for key in ("error", "exception", "structural_guard_error"):
        value = payload.get(key)
        if value:
            return str(value)
    returncode = _int_or_none(payload.get("score_returncode"))
    if returncode not in (None, 0):
        return f"score-source exited {returncode}"
    return None


def _normalized_diff_lines(payload: Mapping[str, Any]) -> int | None:
    for value in (
        payload.get("normalized_diff_lines"),
        payload.get("ndl"),
        _nested_value(payload, ("structural_guard", "normalized_diff_lines")),
        _nested_value(payload, ("checkdiff_payload", "normalized_diff_lines")),
    ):
        parsed = _int_or_none(value)
        if parsed is not None:
            return parsed
    return None


def _match_percent(payload: Mapping[str, Any]) -> float | None:
    for value in (
        payload.get("match_percent"),
        payload.get("percent"),
        _nested_value(payload, ("structural_guard", "match_percent")),
        _nested_value(payload, ("checkdiff_payload", "match_percent")),
    ):
        parsed = _float_or_none(value)
        if parsed is not None:
            return parsed
    return None


def _allocator_facts(raw: Any) -> list[dict[str, Any]]:
    if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes)):
        return []
    facts: list[dict[str, Any]] = []
    for row in raw:
        if not isinstance(row, Mapping):
            continue
        fact = _allocator_fact(row)
        if fact is not None:
            facts.append(fact)
    return facts


def _allocator_fact(row: Mapping[str, Any]) -> dict[str, Any] | None:
    virtual = _int_or_none(
        _first_present(row, "virtual", "baseline_virtual", "ig_idx", "target_ig")
    )
    expected = _register_num(
        _first_present(row, "expected", "target_reg", "phys", "target_reg_num")
    )
    actual = _register_num(_first_present(row, "actual", "assigned_reg", "current_reg"))
    if virtual is None or expected is None:
        return None
    out: dict[str, Any] = {"virtual": virtual, "expected": expected, "actual": actual}
    name = _non_empty_str(row.get("name"))
    if name is not None:
        out["name"] = name
    return out


def _select_force_phys(
    allocator_facts: Sequence[Mapping[str, Any]],
    *,
    preferred: Mapping[str, int],
) -> tuple[dict[str, int], list[dict[str, Any]]]:
    selected: dict[str, int] = {}
    conflicts: list[dict[str, Any]] = []
    facts_by_virtual: dict[str, list[Mapping[str, Any]]] = {}
    for fact in allocator_facts:
        virtual = _int_or_none(fact.get("virtual"))
        expected = _int_or_none(fact.get("expected"))
        if virtual is None or expected is None:
            continue
        facts_by_virtual.setdefault(str(virtual), []).append(fact)
    for virtual, preferred_reg in preferred.items():
        facts = facts_by_virtual.get(virtual, [])
        chosen = next(
            (
                _int_or_none(fact.get("expected"))
                for fact in facts
                if _int_or_none(fact.get("expected")) == preferred_reg
            ),
            None,
        )
        if chosen is None and facts:
            chosen = _int_or_none(facts[0].get("expected"))
        if chosen is None:
            chosen = preferred_reg
        selected[virtual] = chosen
        for fact in facts:
            expected = _int_or_none(fact.get("expected"))
            if expected is not None and expected != chosen:
                conflicts.append(
                    {
                        "virtual": int(virtual),
                        "selected_expected": chosen,
                        "conflicting_expected": expected,
                        "fact": dict(fact),
                    }
                )
    return selected, conflicts


def _source_span_rows(raw: Any) -> list[dict[str, Any]]:
    if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes)):
        return []
    return [dict(row) for row in raw if isinstance(row, Mapping)]


def _context_source_file(
    source_spans: Sequence[Mapping[str, Any]],
    *,
    repo_root: Path | None,
    preferred: str,
) -> str:
    del repo_root
    for span in source_spans:
        source_file = _non_empty_str(span.get("source_file"))
        if source_file and source_file.endswith(preferred):
            return preferred
    return preferred


def _candidate_source_filename(candidate_id: str) -> str:
    stem = re.sub(r"[^A-Za-z0-9_.-]+", "-", candidate_id).strip(".-")
    if not stem:
        stem = "candidate"
    encoded = stem.encode("utf-8")
    if len(encoded) > 178:
        stem = encoded[:178].decode("ascii", "ignore").rstrip(".-") or "candidate"
    return f"{stem}.c"


def _candidate_path(candidate: Mapping[str, Any]) -> Path | None:
    for key in ("candidate_path", "source_retained", "path"):
        value = _non_empty_str(candidate.get(key))
        if value is not None:
            return Path(value)
    return None


def _default_next_unsupported_source_model(function: str) -> str:
    return str(_profile_value(function, "default_next"))


def _full_selection_swap_next_hint(
    score_rows: Sequence[Mapping[str, Any]],
    attempted_dimensions: Sequence[Mapping[str, Any]],
    next_unsupported: str,
) -> dict[str, Any] | None:
    attempted_ids = {
        str(row.get("dimension_id"))
        for row in attempted_dimensions
        if row.get("dimension_id") is not None
    }
    if (
        SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_DIMENSION in attempted_ids
        and next_unsupported
        == SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_EXHAUSTED_NEXT_MODEL
    ):
        best_unbounded_context = next(
            (
                row
                for row in _rank_score_rows(score_rows)
                if row.get("dimension_id")
                == SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_DIMENSION
            ),
            None,
        )
        spans: list[dict[str, Any]] = []
        if best_unbounded_context is not None:
            spans.append(
                {
                    "candidate_id": best_unbounded_context.get("candidate_id"),
                    "dimension_id": (
                        SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_DIMENSION
                    ),
                    "source_components": list(
                        best_unbounded_context.get("source_components") or []
                    ),
                    "source_hunks": list(
                        best_unbounded_context.get("source_hunks") or []
                    ),
                }
            )
        return {
            "next_unsupported_source_family": (
                SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_EXHAUSTED_NEXT_FAMILY
            ),
            "next_unsupported_source_spans": spans,
        }
    if (
        SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION in attempted_ids
        and next_unsupported
        == SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_EXHAUSTED_NEXT_MODEL
    ):
        best_tu_context = next(
            (
                row
                for row in _rank_score_rows(score_rows)
                if row.get("dimension_id")
                == SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION
            ),
            None,
        )
        spans: list[dict[str, Any]] = []
        if best_tu_context is not None:
            spans.append(
                {
                    "candidate_id": best_tu_context.get("candidate_id"),
                    "dimension_id": (
                        SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION
                    ),
                    "source_components": list(
                        best_tu_context.get("source_components") or []
                    ),
                    "source_hunks": list(best_tu_context.get("source_hunks") or []),
                }
            )
        return {
            "next_unsupported_source_family": (
                SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_EXHAUSTED_NEXT_FAMILY
            ),
            "next_unsupported_source_spans": spans,
        }
    if (
        SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION in attempted_ids
        and next_unsupported == SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_MODEL
    ):
        best_helper = next(
            (
                row
                for row in _rank_score_rows(score_rows)
                if row.get("dimension_id") == SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION
            ),
            None,
        )
        spans: list[dict[str, Any]] = []
        if best_helper is not None:
            spans.append(
                {
                    "candidate_id": best_helper.get("candidate_id"),
                    "dimension_id": SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION,
                    "source_components": list(
                        best_helper.get("source_components") or []
                    ),
                    "source_hunks": list(best_helper.get("source_hunks") or []),
                }
            )
        return {
            "next_unsupported_source_family": (
                SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_FAMILY
            ),
            "next_unsupported_source_spans": spans,
        }
    if (
        SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION in attempted_ids
        and next_unsupported
        == SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_EXHAUSTED_NEXT_MODEL
    ):
        best_whole_function = next(
            (
                row
                for row in _rank_score_rows(score_rows)
                if row.get("dimension_id")
                == SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION
            ),
            None,
        )
        spans: list[dict[str, Any]] = []
        if best_whole_function is not None:
            spans.append(
                {
                    "candidate_id": best_whole_function.get("candidate_id"),
                    "dimension_id": (SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION),
                    "source_components": list(
                        best_whole_function.get("source_components") or []
                    ),
                    "source_hunks": list(best_whole_function.get("source_hunks") or []),
                }
            )
        return {
            "next_unsupported_source_family": (
                SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_EXHAUSTED_NEXT_FAMILY
            ),
            "next_unsupported_source_spans": spans,
        }
    if (
        SORT_FULL_SELECTION_SWAP_DIMENSION not in attempted_ids
        or next_unsupported != SORT_FULL_SELECTION_SWAP_EXHAUSTED_NEXT_MODEL
    ):
        return None
    best_full_selection = next(
        (
            row
            for row in _rank_score_rows(score_rows)
            if row.get("dimension_id") == SORT_FULL_SELECTION_SWAP_DIMENSION
        ),
        None,
    )
    spans: list[dict[str, Any]] = []
    if best_full_selection is not None:
        spans.append(
            {
                "candidate_id": best_full_selection.get("candidate_id"),
                "dimension_id": SORT_FULL_SELECTION_SWAP_DIMENSION,
                "source_components": list(
                    best_full_selection.get("source_components") or []
                ),
                "source_hunks": list(best_full_selection.get("source_hunks") or []),
            }
        )
    return {
        "next_unsupported_source_family": (
            SORT_FULL_SELECTION_SWAP_EXHAUSTED_NEXT_FAMILY
        ),
        "next_unsupported_source_spans": spans,
    }


def _terminal_next_unsupported_source_model(
    context: MetaCeilingContext,
    attempted_dimensions: Sequence[Mapping[str, Any]],
    *,
    sort_post_inline_boundary_selection_emission_terminal: bool = False,
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_terminal: bool = False,
    draw_post_row_offset_owner_expression_lifetime_terminal: bool = False,
) -> str:
    attempted_ids = {
        str(row.get("dimension_id"))
        for row in attempted_dimensions
        if row.get("dimension_id") is not None
    }
    if draw_post_row_offset_owner_expression_lifetime_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_FINAL_MODEL
    if draw_post_stack_loop_callsite_expression_anchor_source_ownership_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_DIMENSION
        in attempted_ids
    ):
        return DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_LOOP_CALLSITE_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_DIMENSION in attempted_ids
    ):
        return DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION in attempted_ids
    ):
        return DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_DIMENSION in attempted_ids
    ):
        return DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_SOURCE_CONTEXT_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ALTERNATE_SOURCE_CONTEXT_FINAL_MODEL
    if (
        context.function == DRAW_FUNCTION
        and DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_DIMENSION in attempted_ids
    ):
        return DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_EXHAUSTED_NEXT_MODEL
    if context.function != SORT_FUNCTION:
        return (
            context.next_unsupported_source_model
            or _default_next_unsupported_source_model(context.function)
        )
    if sort_post_inline_boundary_selection_emission_terminal or (
        SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_FINAL_MODEL
    if (
        SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_FINAL_MODEL
    if SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_DIMENSION in attempted_ids:
        return SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_FINAL_MODEL
    if (
        SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_FINAL_MODEL
    if SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_DIMENSION in attempted_ids:
        return SORT_UNBOUNDED_TU_DATA_OWNERSHIP_CONTEXT_EXHAUSTED_NEXT_MODEL
    if SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_DIMENSION in attempted_ids:
        return SORT_TU_DATA_SYMBOL_HELPER_BOUNDARY_CONTEXT_EXHAUSTED_NEXT_MODEL
    if SORT_HELPER_DATA_LAYOUT_CONTEXT_DIMENSION in attempted_ids:
        return SORT_HELPER_DATA_LAYOUT_CONTEXT_EXHAUSTED_NEXT_MODEL
    if SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_DIMENSION in attempted_ids:
        return SORT_WHOLE_FUNCTION_CONTROL_DATA_FLOW_EXHAUSTED_NEXT_MODEL
    if SORT_FULL_SELECTION_SWAP_DIMENSION in attempted_ids:
        return SORT_FULL_SELECTION_SWAP_EXHAUSTED_NEXT_MODEL
    if SORT_PROTECTED_LOSS_INIT_LIFETIME_DIMENSION in attempted_ids:
        return SORT_FULL_SELECTION_SWAP_UNSUPPORTED_SOURCE_MODEL
    if set(SORT_SEMANTIC_ALGORITHM_DIMENSIONS) <= attempted_ids:
        return SORT_SEMANTIC_ALGORITHM_EXHAUSTED_NEXT_MODEL
    if attempted_ids & set(SORT_NATURAL_REWRITE_DIMENSIONS):
        return SORT_NATURAL_REWRITE_EXHAUSTED_NEXT_MODEL
    if (
        SORT_SEMANTIC_RECOMBINE_DIMENSION in attempted_ids
        and context.next_unsupported_source_family
        == SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION
    ):
        return SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_MODEL
    return (
        context.next_unsupported_source_model
        or SORT_LEGACY_NEXT_UNSUPPORTED_SOURCE_MODEL
    )


def _terminal_next_unsupported_source_family(
    context: MetaCeilingContext,
    attempted_dimensions: Sequence[Mapping[str, Any]],
    *,
    draw_alternate_terminal: bool,
    draw_source_context_terminal: bool = False,
    draw_post_source_context_terminal: bool = False,
    draw_post_all_known_source_context_terminal: bool = False,
    draw_product_translate_expression_graph_terminal: bool = False,
    sort_post_inline_boundary_selection_emission_terminal: bool = False,
    draw_post_stack_loop_callsite_expression_anchor_source_ownership_terminal: bool = False,
    draw_post_row_offset_owner_expression_lifetime_terminal: bool = False,
) -> str | None:
    attempted_ids = {
        str(row.get("dimension_id"))
        for row in attempted_dimensions
        if row.get("dimension_id") is not None
    }
    if draw_post_row_offset_owner_expression_lifetime_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_FINAL_FAMILY
    if draw_post_stack_loop_callsite_expression_anchor_source_ownership_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_DIMENSION
        in attempted_ids
    ):
        return DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_FINAL_FAMILY
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_LOOP_CALLSITE_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_STACK_LOOP_CALLSITE_EXPRESSION_ANCHOR_SOURCE_OWNERSHIP_FAMILY
    if (
        context.function == DRAW_FUNCTION
        and DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_DIMENSION in attempted_ids
    ):
        return DRAW_POST_STACK_CLEAN_NO_ANCHOR_SOURCE_SHAPE_FINAL_FAMILY
    if (
        context.function == DRAW_FUNCTION
        and DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION in attempted_ids
    ):
        return DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_FINAL_FAMILY
    if draw_product_translate_expression_graph_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_DIMENSION in attempted_ids
    ):
        return DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_FINAL_FAMILY
    if draw_post_all_known_source_context_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ALL_KNOWN_SOURCE_CONTEXT_FINAL_FAMILY
    if draw_post_source_context_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_SOURCE_CONTEXT_FINAL_FAMILY
    if draw_source_context_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION in attempted_ids
    ):
        return DRAW_POST_ALTERNATE_SOURCE_CONTEXT_FINAL_FAMILY
    if draw_alternate_terminal or (
        context.function == DRAW_FUNCTION
        and DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_DIMENSION in attempted_ids
    ):
        return DRAW_ALTERNATE_FPR_EXPRESSION_STRUCTURE_EXHAUSTED_NEXT_FAMILY
    if sort_post_inline_boundary_selection_emission_terminal or (
        context.function == SORT_FUNCTION
        and SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_FINAL_FAMILY
    if (
        context.function == SORT_FUNCTION
        and SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_BROADER_NATURAL_INLINE_BOUNDARY_SOURCE_HYPOTHESIS_FINAL_FAMILY
    if (
        context.function == SORT_FUNCTION
        and SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_DIMENSION in attempted_ids
    ):
        return SORT_POST_CROSS_TU_BROADER_NATURAL_REWRITE_FINAL_FAMILY
    if (
        context.function == SORT_FUNCTION
        and SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_DIMENSION
        in attempted_ids
    ):
        return SORT_POST_CROSS_TU_SELECTION_SWAP_SOURCE_HYPOTHESIS_FINAL_FAMILY
    if (
        context.function == SORT_FUNCTION
        and SORT_SEMANTIC_RECOMBINE_DIMENSION in attempted_ids
        and context.next_unsupported_source_family
        == SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_DIMENSION
    ):
        return SORT_CROSS_TU_SYMBOL_LINKAGE_CONTEXT_EXHAUSTED_NEXT_FAMILY
    return context.next_unsupported_source_family


def _draw_alternate_terminal_attempt(
    context: MetaCeilingContext,
    candidates: Sequence[Mapping[str, Any]],
    score_rows: Sequence[Mapping[str, Any]],
) -> bool:
    if context.function != DRAW_FUNCTION or context.register_class != "fpr":
        return False
    return any(
        _is_draw_alternate_fpr_expression_structure_row(row)
        for row in [*candidates, *score_rows]
        if isinstance(row, Mapping)
    )


