def _is_draw_post_alternate_source_context_row(
    row: Mapping[str, Any],
) -> bool:
    if row.get("dimension_id") == DRAW_POST_ALTERNATE_SOURCE_CONTEXT_DIMENSION:
        return True
    metadata = row.get("validation_metadata")
    return (
        isinstance(metadata, Mapping)
        and metadata.get("post_alternate_source_context_lane") is True
    )


