def _sort_post_cross_tu_broader_natural_rewrite_terminal_attempt(
    context: MetaCeilingContext,
    candidates: Sequence[Mapping[str, Any]],
    score_rows: Sequence[Mapping[str, Any]],
) -> bool:
    if context.function != SORT_FUNCTION or context.register_class != "gpr":
        return False
    return any(
        _is_sort_post_cross_tu_broader_natural_rewrite_row(row)
        for row in [*candidates, *score_rows]
        if isinstance(row, Mapping)
    )


def _sort_post_broader_natural_inline_boundary_terminal_attempt(
    context: MetaCeilingContext,
    candidates: Sequence[Mapping[str, Any]],
    score_rows: Sequence[Mapping[str, Any]],
) -> bool:
    if context.function != SORT_FUNCTION or context.register_class != "gpr":
        return False
    return any(
        _is_sort_post_broader_natural_inline_boundary_row(row)
        for row in [*candidates, *score_rows]
        if isinstance(row, Mapping)
    )


def _sort_post_inline_boundary_selection_emission_terminal_attempt(
    context: MetaCeilingContext,
    candidates: Sequence[Mapping[str, Any]],
    score_rows: Sequence[Mapping[str, Any]],
) -> bool:
    if context.function != SORT_FUNCTION or context.register_class != "gpr":
        return False
    rows = [*candidates, *score_rows]
    if any(
        _is_sort_post_inline_boundary_selection_emission_row(row)
        for row in rows
        if isinstance(row, Mapping)
    ):
        return True
    if not _sort_post_inline_boundary_selection_emission_final_terminal_sentinel(
        context
    ):
        return False
    return any(
        _is_sort_post_inline_boundary_selection_emission_fallback_row(row)
        for row in rows
        if isinstance(row, Mapping)
    )


def _is_sort_post_inline_boundary_selection_emission_row(
    row: Mapping[str, Any],
) -> bool:
    candidate_id = _non_empty_str(row.get("candidate_id")) or ""
    if (
        row.get("dimension_id")
        == SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_DIMENSION
    ):
        return True
    if candidate_id.startswith(
        SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_SOURCE_SHAPE_CANDIDATE_PREFIX
    ):
        return True
    metadata = row.get("validation_metadata")
    return (
        isinstance(metadata, Mapping)
        and metadata.get("post_inline_boundary_selection_emission_source_shape")
        is True
    )


def _is_sort_post_inline_boundary_selection_emission_fallback_row(
    row: Mapping[str, Any],
) -> bool:
    candidate_id = _non_empty_str(row.get("candidate_id")) or ""
    dimension_id = row.get("dimension_id")
    if dimension_id not in SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_FALLBACK_DIMENSIONS:
        return False
    return candidate_id.startswith(
        SORT_POST_INLINE_BOUNDARY_SELECTION_EMISSION_FALLBACK_PREFIXES
    )


