def _draw_post_stack_loop_callsite_seed_rows(
    context: MetaCeilingContext,
) -> list[dict[str, Any]]:
    post_evidence = _draw_post_stack_clean_context_evidence(context) or {}
    post_evidence_rows = _list_of_dicts(post_evidence.get("retained_scored_probes"))
    if not post_evidence_rows:
        post_evidence_rows = _list_of_dicts(
            post_evidence.get("ranked_post_stack_clean_probes")
        )
    nested_rows = [
        row
        for key in ("retained_scored_probes", "candidate_scores")
        for row in _list_of_dicts_for_nested_key(context.current_ceiling, key)
        if _is_draw_post_stack_clean_no_anchor_source_shape_row(row)
    ]
    rows = _dedupe_dicts(
        [
            *post_evidence_rows,
            *nested_rows,
        ]
    )
    fallback_evidence = _draw_stack_clean_no_anchor_recovery_evidence(context) or {}
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(rows, start=1):
        if not isinstance(row, Mapping):
            continue
        out = dict(row)
        if out.get("candidate_id") is None:
            out["candidate_id"] = out.get("seed_candidate_id") or out.get("probe_id")
        if out.get("source_retained") is None:
            out["source_retained"] = fallback_evidence.get("source_retained")
        if out.get("pcdump_path") is None:
            out["pcdump_path"] = fallback_evidence.get("pcdump_path")
        if out.get("stack_frame_facts") is None:
            out["stack_frame_facts"] = fallback_evidence.get("stack_frame_facts") or {}
        out.setdefault("rank", index)
        if out.get("source_retained") is not None:
            normalized.append(out)
    if not normalized and fallback_evidence.get("source_retained") is not None:
        normalized.append(dict(fallback_evidence))
    return sorted(normalized, key=_draw_post_stack_clean_seed_rank_key)


def _draw_post_stack_clean_context_evidence(
    context: MetaCeilingContext,
) -> dict[str, Any] | None:
    proof = context.current_ceiling
    source_model_proof = _proof_source_model_proof(proof)
    synthesis = _proof_source_family_synthesis(proof)
    return _first_mapping_value(
        "post_stack_clean_no_anchor_evidence",
        (proof, source_model_proof, synthesis),
    )


def _patch_draw_post_stack_clean_declare_fpr_owners_adjacent(
    function_text: str,
) -> str | None:
    old = (
        "    f32 x_spacing;\n"
        "    f32 y_spacing;\n"
        "    f32 base;\n"
        "    f32 row_offset;\n"
        "    f32 y_offset_owner;\n"
        "    f32 rowf;\n"
        "    f32 col_offset;\n"
        "    f32 col_product_owner;\n"
    )
    new = (
        "    f32 base;\n"
        "    f32 y_offset;\n"
        "    f32 row_offset;\n"
        "    f32 col_product_owner;\n"
        "    f32 col_offset;\n"
        "    f32 row_offset_adj;\n"
        "    f32 x_spacing;\n"
        "    f32 y_spacing;\n"
        "    f32 y_offset_owner;\n"
        "    f32 rowf;\n"
    )
    patched = _replace_once_or_none(function_text, old, new)
    if patched is None:
        old = (
            "    f32 x_spacing;\n"
            "    f32 y_spacing;\n"
            "    f32 base;\n"
            "    f32 row_offset;\n"
            "    f32 rowf;\n"
            "    f32 col_offset;\n"
            "    f32 col_product_owner;\n"
        )
        new = (
            "    f32 base;\n"
            "    f32 y_offset;\n"
            "    f32 row_offset;\n"
            "    f32 col_product_owner;\n"
            "    f32 col_offset;\n"
            "    f32 row_offset_adj;\n"
            "    f32 x_spacing;\n"
            "    f32 y_spacing;\n"
            "    f32 rowf;\n"
        )
        patched = _replace_once_or_none(function_text, old, new)
    if patched is None:
        return None
    patched = _replace_once_or_none(patched, "    f32 row_offset_adj;\n", "")
    if patched is None:
        return None
    return _replace_once_or_none(
        patched,
        "    u8 row = arg2;\n    f32 y_offset;\n",
        "    u8 row = arg2;\n",
    )


def _patch_draw_post_stack_clean_row_delta_two_step_owner_reuse(
    function_text: str,
) -> str | None:
    old = "    y_offset_owner = y_offset;\n    row_offset = y_offset_owner * (f32) row;\n"
    new = "    row_offset = y_offset;\n    row_offset *= (f32) row;\n"
    patched = _replace_once_or_none(function_text, old, new)
    if patched is not None:
        return patched
    return _replace_once_or_none(
        function_text,
        "    row_offset = y_offset * (f32) row;\n",
        new,
    )


def _patch_draw_post_stack_clean_row_delta_callsite_late(
    function_text: str,
) -> str | None:
    row_delta_expr = "y_offset_owner"
    patched = _replace_once_or_none(
        function_text,
        "    y_offset_owner = y_offset;\n    row_offset = y_offset_owner * (f32) row;\n    row_offset_adj = row_offset - 0.4f;\n",
        "    y_offset_owner = y_offset;\n",
    )
    if patched is None:
        row_delta_expr = "y_offset"
        patched = _replace_once_or_none(
            function_text,
            "    row_offset = y_offset * (f32) row;\n    row_offset_adj = row_offset - 0.4f;\n",
            "",
        )
    if patched is None:
        return None
    return _replace_once_or_none(
        patched,
        "        if (row < 10) {\n",
        (
            f"        row_offset = {row_delta_expr} * (f32) row;\n"
            "        row_offset_adj = row_offset - 0.4f;\n"
            "        if (row < 10) {\n"
        ),
    )


def _patch_draw_post_stack_clean_col_product_direct_first(
    function_text: str,
) -> str | None:
    return _replace_once_or_none(
        function_text,
        "                jobj, (x_spacing * (f32) i) + col_offset);\n",
        "                jobj, (x_spacing * (f32) i) + col_product_owner);\n",
    )


def _patch_draw_post_stack_clean_digit_base_post_anim_temp(
    function_text: str,
) -> str | None:
    old = "        base = (f32) digit;\n        HSD_JObjReqAnimAll(jobj, base);\n"
    new = "        HSD_JObjReqAnimAll(jobj, (base = (f32) digit));\n"
    return _replace_once_or_none(function_text, old, new)


def _draw_stack_clean_no_anchor_seed_source_text(
    evidence: Mapping[str, Any],
) -> str | None:
    source_retained = _non_empty_str(evidence.get("source_retained"))
    if source_retained is None:
        return None
    path = Path(source_retained).expanduser()
    candidates = [path]
    if not path.is_absolute():
        candidates.append(Path.cwd() / path)
    for candidate in candidates:
        if not candidate.is_file():
            continue
        try:
            return candidate.read_text(encoding="utf-8")
        except OSError:
            return None
    return None


def _draw_stack_clean_no_anchor_recovery_goal_specs() -> dict[str, dict[str, Any]]:
    return {
        "row-delta-anchor-local": {
            "strategy": "materialize-row-delta-anchor-local",
            "rationale": (
                "Give the row delta product an explicit rowf owner local while "
                "preserving the opcode-clean product/translate seed."
            ),
            "expected_effect": "recover IG37 row-delta FPR anchor",
            "patcher": _patch_draw_stack_clean_row_delta_anchor_local,
        },
        "digit-fsubs-anchor-temp": {
            "strategy": "materialize-digit-fsubs-anchor-temp",
            "rationale": (
                "Give the digit animation fsubs/callarg expression its own temporary owner before HSD_JObjReqAnimAll."
            ),
            "expected_effect": "recover IG46 digit fsubs FPR anchor",
            "patcher": _patch_draw_stack_clean_digit_fsubs_anchor_temp,
        },
        "col-product-anchor-owner-transfer": {
            "strategy": "materialize-col-product-anchor-owner-transfer",
            "rationale": (
                "Split the col product owner transfer through a second anchor local before assigning col_offset."
            ),
            "expected_effect": "recover IG32 col-product FPR anchor",
            "patcher": _patch_draw_stack_clean_col_product_anchor_owner_transfer,
        },
        "frame-clean-owner-prune": {
            "strategy": "materialize-frame-clean-owner-prune",
            "rationale": (
                "Prune one extra owner local from the retained seed while keeping the product/translate opcode shape."
            ),
            "expected_effect": "remove stack-frame delta without losing anchors",
            "patcher": _patch_draw_stack_clean_frame_clean_owner_prune,
        },
    }


def _patch_draw_stack_clean_row_delta_anchor_local(
    function_text: str,
) -> str | None:
    old = "    row_offset = y_offset_owner * (f32) row;\n"
    new = "    rowf = (f32) row;\n    row_offset = y_offset_owner * rowf;\n"
    return _replace_once_or_none(function_text, old, new)


def _patch_draw_stack_clean_digit_fsubs_anchor_temp(
    function_text: str,
) -> str | None:
    patched = _insert_after_once_or_none(
        function_text,
        "    f32 col_product_owner;\n",
        "    f32 digit_fsubs_anchor;\n",
    )
    if patched is None:
        return None
    old = "        base = (f32) digit;\n        HSD_JObjReqAnimAll(jobj, base);\n"
    new = (
        "        digit_fsubs_anchor = (f32) digit;\n"
        "        base = digit_fsubs_anchor;\n"
        "        HSD_JObjReqAnimAll(jobj, base);\n"
    )
    return _replace_once_or_none(patched, old, new)


def _patch_draw_stack_clean_col_product_anchor_owner_transfer(
    function_text: str,
) -> str | None:
    patched = _insert_after_once_or_none(
        function_text,
        "    f32 col_product_owner;\n",
        "    f32 col_product_anchor;\n",
    )
    if patched is None:
        return None
    old = "    col_product_owner = (f32) col;\n    col_product_owner *= y_spacing;\n    col_offset = col_product_owner;\n"
    new = (
        "    col_product_owner = (f32) col;\n"
        "    col_product_owner *= y_spacing;\n"
        "    col_product_anchor = col_product_owner;\n"
        "    col_offset = col_product_anchor;\n"
    )
    return _replace_once_or_none(patched, old, new)


def _patch_draw_stack_clean_frame_clean_owner_prune(
    function_text: str,
) -> str | None:
    patched = _replace_once_or_none(function_text, "    f32 y_offset_owner;\n", "")
    if patched is None:
        return None
    patched = _replace_once_or_none(patched, "    y_offset_owner = y_offset;\n", "")
    if patched is None:
        return None
    return _replace_once_or_none(
        patched,
        "    row_offset = y_offset_owner * (f32) row;\n",
        "    row_offset = y_offset * (f32) row;\n",
    )


def _replace_once_or_none(text: str, old: str, new: str) -> str | None:
    if old not in text:
        return None
    return text.replace(old, new, 1)


def _insert_after_once_or_none(text: str, anchor: str, insertion: str) -> str | None:
    if insertion in text:
        return text
    if anchor not in text:
        return None
    return text.replace(anchor, anchor + insertion, 1)


def _draw_stack_clean_no_anchor_recovery_evidence(
    context: MetaCeilingContext,
) -> dict[str, Any] | None:
    evidence = _draw_stack_clean_no_anchor_terminal_evidence(context)
    if evidence:
        return dict(evidence)
    for frontier in context.continuation_frontiers:
        continuation = frontier.get("continuation")
        if not isinstance(continuation, Mapping):
            continue
        if continuation.get("route") != DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION:
            continue
        return _draw_stack_clean_no_anchor_frontier_evidence(frontier, continuation)
    proof = context.current_ceiling
    source_model_proof = _proof_source_model_proof(proof)
    synthesis = _proof_source_family_synthesis(proof)
    retained_rows = _dedupe_dicts(
        [
            row
            for container in (proof, source_model_proof, synthesis)
            for key in (
                "candidate_scores",
                "retained_evidence",
                "retained_scored_probes",
                "ranked_retained_c_probes",
            )
            for row in _list_of_dicts(container.get(key))
        ]
    )
    evidence = _draw_product_translate_stack_clean_no_anchor_evidence(
        retained_rows,
        context,
    )
    if evidence:
        return evidence
    return None


def _draw_stack_clean_no_anchor_frontier_evidence(
    frontier: Mapping[str, Any],
    continuation: Mapping[str, Any],
) -> dict[str, Any]:
    evidence = {
        "kind": "draw-product-translate-stack-clean-no-anchor-evidence",
        "status": "repair-handoff",
        "dimension_id": DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION,
        "source_dimension_id": DRAW_PRODUCT_TRANSLATE_EXPRESSION_GRAPH_DIMENSION,
        "seed_candidate_id": (
            continuation.get("seed_candidate_id")
            or continuation.get("candidate_id")
            or frontier.get("seed_candidate_id")
            or frontier.get("candidate_id")
        ),
        "source_retained": (
            continuation.get("source_retained") or frontier.get("source_retained")
        ),
        "pcdump_path": continuation.get("pcdump_path") or frontier.get("pcdump_path"),
        "source_hunks": list(
            continuation.get("source_hunks") or frontier.get("source_hunks") or []
        ),
        "source_components": list(
            continuation.get("source_components")
            or frontier.get("source_components")
            or []
        ),
        "target_score": continuation.get("target_score")
        or frontier.get("target_score"),
        "expression_score": (
            continuation.get("expression_score") or frontier.get("expression_score")
        ),
        "stack_frame_facts": dict(
            continuation.get("stack_frame_facts")
            or frontier.get("stack_frame_facts")
            or {}
        ),
        "ranked_recovery_probes": list(
            continuation.get("ranked_recovery_probes")
            or frontier.get("ranked_recovery_probes")
            or []
        ),
        "source_actionable_frontier": dict(frontier),
        "continuation": dict(continuation),
    }
    for key in (
        "target_virtual_facts",
        "expression_virtual_facts",
        "normalized_diff_lines",
        "opcode_similarity",
        "classification",
        "classification_primary",
        "expected_frame",
        "current_frame",
        "frame_delta",
    ):
        value = (
            continuation.get(key)
            if continuation.get(key) is not None
            else frontier.get(key)
        )
        if value is not None:
            evidence[key] = value
    if not evidence["stack_frame_facts"]:
        frame_facts = {
            key: evidence[key]
            for key in (
                "classification",
                "classification_primary",
                "expected_frame",
                "current_frame",
                "frame_delta",
                "normalized_diff_lines",
                "opcode_similarity",
            )
            if key in evidence
        }
        if frame_facts:
            evidence["stack_frame_facts"] = frame_facts
    if not evidence["ranked_recovery_probes"]:
        evidence["ranked_recovery_probes"] = (
            _draw_stack_clean_no_anchor_recovery_probes(evidence)
        )
    return evidence


def _draw_stack_clean_no_anchor_terminal_evidence(
    context: MetaCeilingContext,
) -> dict[str, Any] | None:
    evidence = context.current_ceiling.get("stack_clean_no_anchor_evidence")
    if isinstance(evidence, Mapping) and evidence:
        return dict(evidence)
    for row in _list_of_dicts_for_nested_key(
        context.current_ceiling,
        "stack_clean_no_anchor_evidence",
    ):
        if row:
            return row
    return None


