def _draw_post_row_offset_owner_expression_lifetime_retained_terminal_evidence(
    context: MetaCeilingContext,
    generation_blockers: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    evidence = _draw_post_row_offset_owner_expression_lifetime_evidence(context)
    candidate_scores = _list_of_dicts(evidence.get("candidate_scores"))
    retained_scored_probes = _list_of_dicts(evidence.get("retained_scored_probes"))
    source_hunks_by_candidate = _list_of_dicts(
        evidence.get("source_hunks_by_candidate")
    )
    exhausted_dimension = {
        "dimension_id": DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_DIMENSION,
        "status": "blocked",
        "exhaustion_reason": (
            DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_TERMINAL_REASON
        ),
        "blockers": [dict(row) for row in generation_blockers],
    }
    available_candidate_ids = _dedupe_strings(
        [
            *[
                str(row.get("candidate_id"))
                for row in [*candidate_scores, *retained_scored_probes]
                if row.get("candidate_id")
            ],
            *_string_items(evidence.get("generated_candidate_ids")),
        ]
    )
    scored_candidate_ids = _dedupe_strings(
        [
            str(row.get("candidate_id"))
            for row in [*candidate_scores, *retained_scored_probes]
            if row.get("candidate_id")
        ]
    )
    terminal_blockers = _dedupe_strings(
        [
            _non_empty_str(row.get("terminal_blocker")) or str(row.get("reason"))
            for row in generation_blockers
            if row.get("terminal_blocker") or row.get("reason")
        ]
        or [DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_TERMINAL_BLOCKER]
    )
    return {
        "candidate_scores": candidate_scores,
        "retained_scored_probes": retained_scored_probes,
        "source_hunks_by_candidate": source_hunks_by_candidate,
        "exhausted_dimensions": [exhausted_dimension],
        "attempted_equivalence_classes": [
            DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_DIMENSION
        ],
        "next_unsupported_source_spans": [
            {
                "dimension_id": (
                    DRAW_POST_ROW_OFFSET_OWNER_EXPRESSION_LIFETIME_DIMENSION
                ),
                "status": "not-materializable",
                "reason": row.get("reason"),
                "source_retained": row.get("source_retained"),
                "pcdump_path": row.get("pcdump_path"),
                "required_source_patterns": row.get("required_patterns"),
            }
            for row in generation_blockers
        ],
        "one_hit_summary": {},
        "terminal_blockers": terminal_blockers,
        "scored_count": len(scored_candidate_ids),
        "available_candidate_ids": available_candidate_ids,
        "generated_candidate_ids": _dedupe_strings(
            [
                *_string_items(evidence.get("generated_candidate_ids")),
                *available_candidate_ids,
            ]
        ),
        "scored_candidate_ids": scored_candidate_ids,
        "unscored_candidate_ids": [
            candidate_id
            for candidate_id in available_candidate_ids
            if candidate_id not in set(scored_candidate_ids)
        ],
        "stack_clean_no_anchor_evidence": dict(
            _draw_stack_clean_no_anchor_recovery_evidence(context) or {}
        ),
        "post_stack_clean_no_anchor_evidence": dict(
            _draw_post_stack_clean_context_evidence(context) or {}
        ),
        "post_row_offset_owner_expression_lifetime_evidence": evidence,
    }


def _draw_stack_clean_no_anchor_recovery_exhausted(
    context: MetaCeilingContext,
) -> bool:
    if _find_nested_string(
        context.current_ceiling,
        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_FINAL_FAMILY,
    ):
        return True
    if _find_nested_string(
        context.current_ceiling,
        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_TERMINAL_REASON,
    ):
        return True
    if _find_nested_string(
        context.current_ceiling,
        DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_TERMINAL_BLOCKER,
    ):
        return True
    for row in _list_of_dicts_for_nested_key(
        context.current_ceiling,
        "exhausted_dimensions",
    ):
        if row.get("dimension_id") == DRAW_STACK_CLEAN_NO_ANCHOR_RECOVERY_DIMENSION:
            return True
    return False


