def _dedupe_dicts(rows: Sequence[Mapping[str, Any]]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        key = json.dumps(row, sort_keys=True, default=str)
        if key in seen:
            continue
        seen.add(key)
        out.append(dict(row))
    return out


def _dedupe_strings(values: Sequence[str]) -> list[str]:
    out: list[str] = []
    for value in values:
        if value and value not in out:
            out.append(value)
    return out


def _string_items(raw: Any) -> list[str]:
    if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes)):
        return []
    return [str(item) for item in raw if item]


def _non_empty_str(raw: Any) -> str | None:
    if isinstance(raw, (str, Path)) and str(raw):
        return str(raw)
    return None


def _first_present(row: Mapping[str, Any], *keys: str) -> Any:
    for key in keys:
        if row.get(key) is not None:
            return row[key]
    return None


def _first_non_none(*values: Any) -> Any:
    for value in values:
        if value is not None:
            return value
    return None


def _list_of_dicts(raw: Any) -> list[dict[str, Any]]:
    if not isinstance(raw, Sequence) or isinstance(raw, (str, bytes)):
        return []
    return [dict(item) for item in raw if isinstance(item, Mapping)]


def _list_of_dicts_for_nested_key(raw: Any, key: str) -> list[dict[str, Any]]:
    if isinstance(raw, Mapping):
        rows: list[dict[str, Any]] = []
        value = raw.get(key)
        rows.extend(_list_of_dicts(value))
        for item in raw.values():
            if isinstance(item, (Mapping, list, tuple)):
                rows.extend(_list_of_dicts_for_nested_key(item, key))
        return rows
    if isinstance(raw, Sequence) and not isinstance(raw, (str, bytes)):
        rows: list[dict[str, Any]] = []
        for item in raw:
            rows.extend(_list_of_dicts_for_nested_key(item, key))
        return rows
    return []


def _int_or_none(raw: Any) -> int | None:
    if isinstance(raw, bool):
        return None
    if isinstance(raw, int):
        return raw
    if isinstance(raw, float) and raw.is_integer():
        return int(raw)
    if isinstance(raw, str):
        text = raw.strip().lower()
        if text.startswith(("r", "f")) and text[1:].isdigit():
            text = text[1:]
        if text.startswith("ig") and text[2:].isdigit():
            text = text[2:]
        try:
            return int(text, 0)
        except ValueError:
            match = re.search(r"-?\d+", text)
            if match:
                return int(match.group(0), 10)
    return None


def _register_num(raw: Any) -> int | None:
    return _int_or_none(raw)


def _float_or_none(raw: Any) -> float | None:
    if isinstance(raw, bool):
        return None
    if isinstance(raw, (int, float)):
        return float(raw)
    if isinstance(raw, str):
        try:
            return float(raw.strip())
        except ValueError:
            return None
    return None


def _nested_value(payload: Mapping[str, Any], keys: Sequence[str]) -> Any:
    current: Any = payload
    for key in keys:
        if not isinstance(current, Mapping):
            return None
        current = current.get(key)
    return current
